TURATH_CHUNK(27,[{"num":5400,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ....فَاعْتَمَرَ مِنَ الْعَامِ الْمُقْبِلِ، فَدَخَلَهَا كَمَا كَانَ صَالَحَهُمْ، فَلَمَّا أَقَامَ بِهَا ثَلاَثًا أَمَرُوهُ أَنْ يَخْرُجَ فَخَرَجَ."],"takhrij":"صحيح: رواه البخاريّ في الصلح (2701) عن محمد بن رافع، حدثنا سريج بن النعمان، حدّثنا فليح، عن نافع، عن ابن عمر، فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب مدة قيام النبي ﷺ في عمرة القضاء","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2701).","chapter_en":"The length of the Prophet’s stay during the make-up Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ performed Umrah the following year and entered it according to the agreement he had made with them. Then when he had stayed there for three days, they ordered him to leave, so he left."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2701).","voc":["bukhari",2701]},{"num":5401,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عَبَّاسٍ: أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقَامَ فِي عُمْرَةِ الْقَضَاءِ ثَلاَثًا."],"takhrij":"حسن: رواه أبو داود (1997) عن داود بن رُشيد، حدّثنا يحيى بن زكريا، حدّثنا محمد بن إسحاق، عن أبان بن صالح، وعن ابن أبي نجيح، عن مجاهد، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب مدة قيام النبي ﷺ في عمرة القضاء","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1997) and Ibn Hisham (2/372).","chapter_en":"The length of the Prophet’s stay during the make-up Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ stayed for three days during the make-up Umrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1997)، وابن هشام (2/372)."},{"num":5402,"demo":false,"sanad":"","matn":["عن عَائِشَةَ، قَالَتْ: نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُحَصَّبَ، فَدَعَا عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ، فَقَالَ: اخْرُجْ بِأُخْتِكَ مِنَ الْحَرَمِ فَلْتُهِلَّ بِعُمْرَةٍ، ثُمَّ لْتَطُفْ بِالْبَيْتِ، فَإِنِّي أَنْتَظِرُكُمَا هَا هُنَا. قَالَتْ: فَخَرَجْنَا، فَأَهْلَلْتُ، ثُمَّ طُفْتُ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، فَجِئْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي مَنْزِلِهِ مِنْ جَوْفِ اللَّيْلِ، فَقَالَ: هَلْ فَرَغْتِ؟ قُلْتُ: نَعَمْ، فَآذَنَ فِي أَصْحَابِهِ بِالرَّحِيلِ، فَخَرَجَ، فَمَرَّ بِالْبَيْتِ، فَطَافَ بِهِ قَبْلَ صَلَاةِ الصُّبْحِ، ثُمَّ خَرَجَ إِلَى الْمَدِينَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الحج (1788)، ومسلم في الحج (1211: 123) كلاهما من حديث أفلح بن حميد، عن القاسم، عن عائشة، فذكرته في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب في إجزاء طواف العمرة عن الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1788) and Muslim (1211/123).","chapter_en":"That the tawaf of Umrah can suffice for the farewell tawaf","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ stopped at al-Muhassab and called Abd al-Rahman ibn Abi Bakr and said: “Take your sister out of the sanctuary so that she may enter ihram for Umrah, then let her perform tawaf of the House. I will wait for both of you here.” She said: So we went out, and I entered ihram, then I circumambulated the House and went between al-Safa and al-Marwah. Then we came back to the Messenger of Allah ﷺ while he was in his lodging in the middle of the night. He said: “Have you finished?” I said: Yes. Then he announced departure to his Companions, so he went out and passed by the House and performed tawaf before the dawn prayer, then departed for Madinah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1788)، ومسلم (1211: 123)."},{"num":5403,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: إِنَّكُمْ تَقُولُونَ: إِنَّ أَبَا هُرَيْرَةَ يُكْثِرُ الْحَدِيثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَتَقُولُونَ: مَا بَالُ الْمُهَاجِرِينَ وَالأَنْصَارِ لاَ يُحَدِّثُونَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِثْلِ حَدِيثِ أَبِي هُرَيْرَةَ؟! وَإِنَّ إِخْوَتِي مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمْ صفقٌ بِالأَسْوَاقِ، وَكُنْتُ أَلْزَمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى ملءِ بَطْنِي، فَأَشْهَدُ إِذَا غَابُوا، وَأَحْفَظُ إِذَا نَسُوا، وَكَانَ يَشْغَلُ إِخْوَتِي مِنَ الأَنْصَارِ عملُ أَمْوَالِهِمْ، وَكُنْتُ امْرَأً مِسْكِينًا مِنْ مَسَاكِينِ الصُّفَّة، أَعِي حينَ ينسَوْن، وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَدِيثٍ يُحدِّثه: إنَّه لنْ يَبسُط أحدٌ ثَوْبَهُ حَتَّى أَقْضِيَ مَقَالَتِي هَذِهِ، ثُمَّ يَجْمَعَ إِلَيْهِ ثَوْبَهُ، إلاّ وعَى مَا أَقُولُ فَبَسَطْتُ نَمرةً عليّ، حَتَّى إِذَا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقَالَتَهُ جَمَعْتُهَا إِلَى صَدْرِي، فمَا نَسيتُ مِن مَقَالَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِلكَ مِن شَيْءٍ."],"takhrij":"متفق عليه: رواه البخاريّ في البيوع (2047) ومسلم في فضائل الصحابة (2492/...) كلاهما من حديث أبي اليمان، حدثنا شعيب، عن الزهري، قال: أخبرني سعيد بن المسيب، وأبو سلمة بن عبد الرحمن، أن أبا هريرة قال فذكره. واللفظ للبخاري، ولفظ مسلم مختصر.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2047) and Muslim (2492). The wording is that of al-Bukhari.","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: You say that Abu Hurayrah narrates many reports from the Messenger of Allah ﷺ, and you say: Why is it that the Emigrants and the Helpers do not narrate from the Messenger of Allah ﷺ like the reports of Abu Hurayrah? My brothers from the Emigrants were occupied with buying and selling in the marketplaces, while I stayed close to the Messenger of Allah ﷺ so long as my stomach was filled. So I was present when they were absent, and I remembered when they forgot. And my brothers from the Helpers were occupied with working on their wealth, while I was a poor man from among the poor people of the bench, so I retained what they forgot. And the Messenger of Allah ﷺ once said in a report he delivered: “No one will spread out his garment until I finish this statement of mine, then gather it to himself, except that he will retain what I say.” So I spread out a striped cloth over myself, and when the Messenger of Allah ﷺ finished his statement, I gathered it to my chest, and after that I forgot nothing from that statement of the Messenger of Allah ﷺ."]},"buhuth":{"en":["Al-Bukhari also narrated (118) from Abu Hurayrah that he said: “People say: Abu Hurayrah narrates too much. Were it not for two verses in the Book of Allah, I would not narrate any report,” then he recited: “Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Book — those are cursed by Allah and cursed by those who curse, except those who repent, correct themselves, and make it clear. Those — I will accept their repentance, and I am the Acceptor of repentance, the Merciful.” [Surat al-Baqarah: 159–160] He then said: My brothers from the Emigrants were occupied with trade in the markets, and my brothers from the Helpers were occupied with working on their wealth, while Abu Hurayrah stayed with the Messenger of Allah ﷺ with only enough to fill his stomach, attending what they did not attend and preserving what they did not preserve."]},"intro_kitab":{"ar":["جموع ما جاء في أحكام البيوع والتجارات"],"en":["A collection of what has been narrated regarding the rulings of sales and trade"]},"intro":{"ar":["قال الله تعالى: ( وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا ) [سورة البقرة: ٢٧٥].","وقال تعالى: ( لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ بَيْنَكُمْ ) [سورة النساء: ٢٩]."],"en":["Allah the Exalted said: “Allah has made trade lawful and has forbidden usury.” [Surat al-Baqarah: 275]","And He said: “Do not consume one another’s wealth unjustly, except that it be trade conducted by mutual consent among you.” [Surat al-Nisa’: 29]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2047) ومسلم (2492). واللفظ للبخاري."},{"num":5404,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ الْمَدِينَةَ، فَآخَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُ وَبَيْنَ سَعْدِ بْنِ الرَّبِيعِ الأَنْصَارِيِّ، وَكَانَ سَعْدٌ ذَا غِنًى، فَقَالَ لِعَبْدِ الرَّحْمَنِ: أُقَاسِمُكَ مَالِي نِصْفَيْنِ، وَأُزَوِّجُكَ. قَالَ: بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، دُلُّونِي عَلَى السُّوقِ. فَمَا."],"takhrij":"صحيح: رواه البخاري في البيوع (2049) عن أحمد بن يونس، حدثنا زهير، حدثنا حميد، عن أنس قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2049).","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: Abd al-Rahman ibn Awf came to Madinah, and the Prophet ﷺ established brotherhood between him and Sa‘d ibn al-Rabi‘ al-Ansari. Sa‘d was a wealthy man, and he said to Abd al-Rahman: I will divide my wealth with you in two equal parts, and I will arrange a marriage for you… But he replied: “May Allah bless your family and your wealth for you. Show me the market.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2049)."},{"num":5405,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَتْ عُكَاظٌ، وَمِجَنَّةُ، وَذُو الْمَجَازِ، أَسْوَاقًا فِي الْجَاهِلِيَّةِ، فَلَمَّا كَانَ الإِسْلاَمُ فَكَأَنَّهُمْ تَأَثَّمُوا فِيهِ، فَنَزَلَتْ: ﴿لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ﴾ [سورة البقرة: 198] } فِي مَوَاسِمِ الْحَجِّ، قَرَأَهَا ابْنُ عَبَّاسٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2050) عن عبد الله بن محمد، حدثنا سفيان، عن عمرو (هو ابن دينار)، عن ابن عباس قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2050).","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: Ukaz, Majannah, and Dhu al-Majaz were marketplaces in the pre-Islamic period. Then when Islam came, it was as though the people felt guilty about conducting trade there, so the verse was revealed: “There is no sin upon you in seeking bounty from your Lord,” referring to the seasons of pilgrimage. Ibn Abbas recited it in that way."]},"buhuth":{"en":["As for the word “Ukaz” — with a rounded vowel at the beginning and the letter zha at the end — it is the name of one of the well-known marketplaces of the Arabs in the pre-Islamic period. The Arab tribes used to gather there every year, boasting before one another, and their poets and men of letters would attend it. The name is related to their expression meaning that one man outdid another in boasting and overcame him in rivalry.","And “Majannah” — with an open letter mim, a jim, and a doubled open nun — was also one of the Arab marketplaces in the pre-Islamic period. It was located at Marr al-Zahran near a mountain called al-Asfar, below Makkah at about the distance of one postal stage from it, according to al-Asma‘i. It is also said that Majannah was near Arafah.","And “Dhu al-Majaz” was likewise one of the marketplaces of the Arabs, near Arafat. Ibn al-Athir said: Ukaz, Dhu al-Majaz, and Majannah were annual markets where the Arabs gathered during the pilgrimage season, and they would feel safe with one another until those days ended. Majannah was at al-Zahran, Ukaz was between Nakhlah and al-Ta’if, and Dhu al-Majaz was on the left side when one stood at the place of standing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2050)."},{"num":5406,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ، رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَكَلَ أَحَدٌ طَعَامًا قَطُّ خَيْرًا مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2072) عن إبراهيم بن موسى، أخبرنا عيسى بن يونس، عن ثور، عن خالد بن معدان، عن المقدام به.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2072).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam narrated from the Messenger of Allah ﷺ: “No one has ever eaten food better than that earned from the work of his own hands, and indeed the Prophet of Allah Dawud, peace be upon him, used to eat from the work of his own hands.”"]}},"tuhfa":{},"full":1,"rep":[8452,12036],"tks":"صحيح: رواه البخاري (2072)."},{"num":5407,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ الزُّبَيْدِيِّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا كَسَبَ الرَّجُلُ كَسْبًا أَطْيَبَ مِنْ عَمَلِ يَدِهِ. وَمَا أَنْفَقَ الرَّجُلُ عَلَى نَفْسِهِ، وَأَهْلِهِ وَوَلَدِهِ، وَخَادِمِهِ فَهُوَ صَدَقَةٌ."],"takhrij":"حسن: رواه ابن ماجه (2138) عن هشام بن عمار قال: حدثنا إسماعيل بن عياش، عن بحير بن سعد، عن خالد بن معدان، عـن المقدام بن معديكرب فذكره.","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2138). Ahmad also narrated it (17190) through another route with the wording: “None of you eats any food in this world better for him than what he eats from the work of his own hand.” In another narration: “None of you eats any food more beloved to Allah the Mighty and Majestic than what he earns from the work of his own hand.” Narrated by Ahmad (17181).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam ibn Ma‘di Karib al-Zubaydi narrated that the Messenger of Allah ﷺ said: “No man ever earns anything purer than what he earns by the work of his own hand. And whatever a man spends on himself, his family, his children, and his servant is charity.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2138). ورواه أحمد (17190) من وجه آخر بلفظ: (( ما أكل أحدكم طعاما في الدنيا خيرا له من أن يأكل من عمل يده)). وفي رواية: (( ما أكل أحد منكم طعاما أحب إلى الله عز وجل من عمل يده)). رواه أحمد (17181)."},{"num":5408,"demo":false,"sanad":"","matn":["عَنْ أَبِى هُرَيْرَةَ قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِذْ طَلَعَ عَلَيْنَا شَابٌّ مِنَ الثَّنِيَّةِ، فَلَمَّا رَأَيْنَاهُ بِأَبْصَارِنَا قُلْنَا: لَوْ أَنَّ هَذَا الشَّابَ جَعَلَ شَبَابَهُ وَنَشَاطَهُ وَقُوَّتَهُ فِي سَبِيلِ الله، قَالَ: فَسَمِعَ مَقَالَتَنَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: وَمَا سَبِيلُ الله إِلاَّ مَنْ قُتِلَ؟ مَنْ سَعَى عَلَى وَالِدَيْهِ فَفِي سَبِيلِ الله، وَمَنْ سَعَى عَلَى عِيَالِهِ فَفِي سَبِيلِ الله، وَمَنْ سَعَى عَلَى نَفْسِهِ لِيُعِفَّهَا فَفِي سَبِيلِ الله، وَمَنْ سَعَى عَلَى التَّكَاثُرِ فَهُوَ فِى سَبِيلِ الشَّيْطَانِ."],"takhrij":"حسن: أخرجه البزار –كشف الأستار (1871)، والطبراني في الأوسط (4372)، والبيهقي في الكبرى (17824) –والسياق له- كلهم من طريق رياح بن عمرو القيسي، حدثنا أيوب، عن محمد بن سيرين، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Reported by al-Bazzar in Kashf al-Astar (1871), al-Tabarani in al-Awsat (4372), and al-Bayhaqi (9/25).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: While we were sitting with the Messenger of Allah ﷺ, a young man came up toward us from the mountain path. When we saw him, we said: If only this young man would devote his youth, energy, and strength to the cause of Allah. The Messenger of Allah ﷺ heard what we said and replied: “Is the cause of Allah only for the one who is killed? Whoever strives for his parents is in the cause of Allah. Whoever strives for his dependents is in the cause of Allah. Whoever strives for himself in order to keep himself chaste is in the cause of Allah. And whoever strives for accumulation is in the cause of Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه البزار - كشف الأستار (1871)، والطبراني في الأوسط (4372)، والبيهقي (17824)."},{"num":5409,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ دَاوُدَ عَلَيْهِ السَّلاَمُ كَانَ لاَ يَأْكُلُ إِلاَّ مِنْ عَمَلِ يَدِهِ."],"takhrij":"صحيح: رواه البخاري في البيوع (2073) عن يحيى بن موسى، حدثنا عبدالرزاق، أخبرنا معمر، عن همام بن منبه، حدثنا أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2073).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ: “Dawud, peace be upon him, used to eat only from the work of his own hands.”"]}},"tuhfa":{},"full":1,"rep":[8453],"tks":"صحيح: رواه البخاري (2073)."},{"num":5410,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَعَثَ اللَّهُ نَبِيًّا إِلاَّ رَعَى الْغَنَمَ. فَقَالَ أَصْحَابُهُ: وَأَنْتَ؟ فَقَالَ: نَعَمْ كُنْتُ أَرْعَاهَا عَلَى قَرَارِيطَ لأَهْلِ مَكَّةَ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2262) عن أحمد بن محمد المكي، عن عمرو بن يحيى بن سعيد القرشي، عن جده، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2262).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Allah did not send any prophet except that he herded sheep.” His companions said: Even you? He said: “Yes, I used to herd them for some qirats for the people of Makkah.”"]}},"tuhfa":{},"full":1,"rep":[5511],"tks":"صحيح: رواه البخاري (2262)."},{"num":5411,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ زكريا نَجَّارًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (2379) عن هدَّاب بن خالد، حدثنا حماد بن سلمة، عن ثابت، عن أبي رافع، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2379).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Zakariyya was a carpenter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2379)."},{"num":5412,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَحْتَطِبَ عَلَى ظَهْرِهِ خيرٌ لَهُ مِنْ أَنْ يَأْتِيَ رَجُلاً أَعْطَاهُ اللَّهِ مِنْ فَضْلِهِ فَيَسْأَلَهُ أَعْطَاهُ أَوْ مَنَعَهُ."],"takhrij":"متفق عليه: رواه مالك في الصدقة (60) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الزكاة (1470) عن عبد الله بن يوسف، عن مالك، ورواه مسلم في الزكاة (1042) من وجه آخر عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (60), al-Bukhari (1470), and Muslim (1042).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “By the One in Whose hand is my soul, for one of you to take his rope and gather firewood on his back is better for him than going to a man whom Allah has given from His bounty and asking him, whether he gives him or refuses him.”"]}},"tuhfa":{},"full":1,"rep":[4221],"tks":"متفق عليه: رواه مالك (60) والبخاري (1470)، ومسلم (1042)."},{"num":5413,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَمَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا خَرَّ عَلَيْهِ رِجْلُ جَرَادٍ مِنْ ذَهَبٍ، فَجَعَلَ يَحْثِي فِي ثَوْبِهِ، فَنَادَى رَبُّهُ: يَا أَيُّوبُ، أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟ قَالَ: بَلَى يَا رَبِّ، وَلَكِنْ لاَ غِنَى لِي عَنْ بَرَكَتِكَ."],"takhrij":"صحيح: رواه البخاري في أحاديث الأنبياء (3391) عن عبد الله بن محمد الجحفي، حدثنا عبد الرزاق، أخـبرنا معمر، عن هـمام، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3391).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “While Ayyub was bathing unclothed, a swarm of golden locusts fell upon him, and he began gathering them into his garment. Then his Lord called out to him: O Ayyub, did I not make you free of need from what you see? He replied: Yes, my Lord, but I can never do without Your blessing.”"]}},"tuhfa":{},"full":1,"rep":[8414],"tks":"صحيح: رواه البخاري (3391)."},{"num":5414,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَيْرُ الْكَسْبِ، كَسْبُ يَدِ الْعَامِلِ إِذَا نَصَحَ."],"takhrij":"حسن: رواه الإمام أحمد (8412، 8691) من طريقين عن محمد بن عمار كشَّاكش مؤذن مسجد رسول الله صلى الله عليه وسلم  قال: سمعت سعيدا المقبري قال: سمع أبا هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (8691, 8412).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “The best earning is the earning of a worker’s own hand when he is sincere.”"]},"buhuth":{"en":["The phrase “when he is sincere” means when he is honest and sincere in his work. This includes builders and scribes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (8691، 8412)."},{"num":5415,"demo":false,"sanad":"","matn":["عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ فَيَأْتِيَ بِحُزْمَةِ الْحَطَبِ عَلَى ظَهْرِهِ فَيَبِيعَهَا فَيَكُفَّ اللَّهُ بِهَا وَجْهَهُ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ مَنَعُوهُ."],"takhrij":"صحيح: رواه البخاري في الزكاة (1471) عن موسى، حدثنا وهيب، حدثنا هشام، عن أبيه، عن الزبير بن العوام، به.","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1471).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Zubayr ibn al-ʿAwwām reported that the Prophet ﷺ said: “For one of you to take his rope, bring a bundle of firewood upon his back and sell it, thereby allowing Allah to preserve his dignity, is better for him than asking people, whether they give him or refuse him.”"]}},"tuhfa":{},"full":1,"rep":[4223],"tks":"صحيح: رواه البخاري (1471)."},{"num":5416,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، قَالَ قَالَتْ: عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا كَانَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُمَّالَ أَنْفُسِهِمْ، وَكَانَ يَكُونُ لَهُمْ أَرْوَاحٌ، فَقِيلَ لَهُمْ: لَوِ اغْتَسَلْتُمْ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2071) ومسلم في الجمعة (6/847) من طريق عروة بن الزبير، عن عائشة، قالت فذكرته.","grade":"متفق عليه","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2071) and Muslim (847).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Aishah said: The companions of the Messenger of Allah ﷺ used to do their own labor, and they would come with the smell of perspiration. So it was said to them: “If only you would wash yourselves.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2071) ومسلم (6/847)."},{"num":5417,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ، عَنْ أَبِيهِ، عَنْ عَمِّهِ، قَالَ: كُنَّا فِي مَجْلِسٍ. فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى رَأْسِهِ أَثَرُ مَاءٍ، فَقَالَ لَهُ بَعْضُنَا، نَرَاكَ الْيَوْمَ طَيِّبَ النَّفْسِ. فَقَالَ: أَجَلْ. وَالْحَمْدُ لِلَّهِ. ثُمَّ أَفَاضَ الْقَوْمُ فِي ذِكْرِ الْغِنَى، فَقَالَ: لاَ بَأْسَ بِالْغِنَى لِمَنِ اتَّقَى، وَالصِّحَّةُ لِمَنِ اتَّقَى خَيْرٌ مِنَ الْغِنَى، وَطِيبُ النَّفْسِ مِنَ النِّعَمِ."],"takhrij":"حسن: رواه ابن ماجه (2141) واللفظ له وأحمد (23158) والحاكم (2131) كلهم من حديث عبد الله بن سليمان، حدثنا معاذ بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2141), and this is his wording; also by Ahmad (23158) and al-Hakim (2131).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Mu‘adh ibn Abdullah ibn Khubayb narrated from his father, from his uncle, who said: We were sitting in a gathering when the Prophet ﷺ came, and there was a trace of water on his head. Some of us said to him: We see that you are in good spirits today. He said: “Yes, and praise be to Allah.” Then the people began discussing wealth, and he said: “There is no harm in wealth for the one who is mindful of Allah, and good health for the one who is mindful of Allah is better than wealth, and contentment of the soul is part of bliss.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2141) واللفظ له، وأحمد (23158) والحاكم (2131)."},{"num":5418,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَطْيَبِ الْكَسْبِ؟ فَقَالَ: عَمَلُ الرَّجُلِ بِيَدِهِ، وَكُلُّ بَيْعٍ مَبْرُورٍ."],"takhrij":"حسن: رواه الطبراني في الأوسط (2161) عن أحمد (بن زهير)، عن الحسن بن عرفة قال: ثنا قدامة بن شهاب المازني، ثنا إسماعيل بن أبي خالد، عن وبره بن عبدالرحمن، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (2161).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ was asked about the purest earning, and he said: “A man’s work with his own hand, and every righteous sale.”"]},"buhuth":{"en":["The phrase “every righteous sale” means a sale not mixed with sin, false oaths, or the like."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (2161)."},{"num":5419,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: وَلَدُ الرَّجُلِ مِنْ كَسْبِهِ، مِنْ أَطْيَبِ كَسْبِهِ، فَكُلُوا مِنْ أَمْوَالِهِمْ."],"takhrij":"حسن: رواه أبو داود (3529)، وأحمد (24951)، ومن طريقه الحاكم (2/45، 46) كلهم من حديث محمد بن جعفر، ثنا شعبة، عن الحكم، عن عمارة بن عمير، عن أمه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3529), Ahmad (24951), and al-Hakim (2/45–46).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["The Mother of the Believers Aishah narrated that the Prophet ﷺ said: “A man’s child is from his earnings, from the best of his earnings, so eat from their wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3529)، وأحمد (24951)، والحاكم (46)."},{"num":5420,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَلَدُ مِنْ كَسْبِ الْوَالِدِ."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (2193) عن محمد بن علي بن شعيب، حدثنا محمد بن أبي بلال التميمي، حدثنا خلف بن خليفة، عن محارب بن دثار، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat, as cited in Majma‘ al-Bahrayn (2193).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “The child is from the earnings of the parent.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6678)، وابن الجارود في المنتقى (995)، والبيهقي (15858)، وأبو داود (3530)."},{"num":5421,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: أَتَى أَعْرَابِيٌّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنَّ أَبِي يُرِيدُ أَنْ يَجْتَاحَ مَالِي؟ قَالَ: أَنْتَ وَمَالُكَ لِوَالِدِكَ، إِنَّ أَطْيَبَ مَا أَكَلْتُمْ مِنْ كَسْبِكُمْ، وَإِنَّ أَمْوَالَ أَوْلَادِكُمْ مِنْ كَسْبِكُمْ، فَكُلُوهُ هَنِيئًا."],"takhrij":"حسن: رواه أحمد (6678)، وابن الجارود (995)، والبيهقي (15748) كلهم من حديث يحيى بن سعيد، حدثنا عبيد الله بن الأخنس، حدثني عمرو بن شعيب فذكره.","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6678), Ibn al-Jarud in al-Muntaqa (995), al-Bayhaqi (7/480), and Abu Dawud (3530).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As said: A Bedouin came to the Messenger of Allah ﷺ and said: My father wants to take all my wealth. He said: “You and your wealth belong to your father. Indeed, the best of what you eat is from your own earnings, and the wealth of your children is from your earnings, so consume it with ease.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2291)."},{"num":5422,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَجُلاً، قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ لِي مَالاً وَوَلَدًا، وَإِنَّ أَبِي يُرِيدُ أَنْ يَجْتَاحَ مَالِي، فَقَالَ أَنْتَ وَمَالُكَ لأَبِيكَ."],"takhrij":"حسن: رواه ابن ماجه (2291) عن هشام بن عمار قال: حدثنا عيسى بن يونس قال: حدثنا يوسف بن إسحـاق، عن محمد بن المنكـدر، عن جابر فذكره. وإسناده حسن من أجل شيخ ابن ماجه؛ فإنه حسن الحديث، وبقية رجالـه ثقات.","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2291).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a man said: O Messenger of Allah ﷺ, I have wealth and children, and my father wants to take my wealth, so he said: “You and your wealth belong to your father.”"]},"buhuth":{"en":["The phrase “You and your wealth belong to your father” means that if the father needs his son’s wealth, he may take from it according to his need. It does not mean that he may consume all of it absolutely, rightly or wrongly. No qualified scholar said that. Al-Bayhaqi said in al-Kubra (7/481): Whoever claimed that the child’s wealth fully belongs to the father relied on the outward wording of this hadith. But whoever held that the father may take only what suffices him when he is in need, and that if he has no need then he has no right to any of it, relied on the reports prohibiting unlawful consumption of another’s wealth, and on the fact that if a person dies and leaves a father and a son, the father receives only one-sixth. If the father truly owned all of his son’s wealth, he would take all of it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (2193)."},{"num":5423,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رَحِمَ اللَّهُ رَجُلاً سَمْحًا إِذَا بَاعَ، وَإِذَا اشْتَرَى، وَإِذَا اقْتَضَى."],"takhrij":"صحيح:  رواه البخاري في البيوع (2076) عن علي بن عيَّاش، حدثنا أبو غسان محمد بن مطرِّف، حدثني محمد المنكدر، عن جابر به.","grade":"صحيح","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2076).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Messenger of Allah ﷺ said: “May Allah have mercy on a man who is easygoing when he sells, when he buys, and when he asks for what is due to him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2076)."},{"num":5424,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَفَرَ اللَّهُ لِرَجُلٍ كَانَ قَبْلَكُمْ كَانَ سَهْلاً إِذَا بَاعَ، سَهْلاً إِذَا اشْتَرَى، سَهْلاً إِذَا اقْتَضَى."],"takhrij":"حسن: رواه الترمذي (1320) عن عباس الدوري، حدثنا عبد الوهاب بن عطاء، أخبرنا إسرائيل، عن زيد بن عطاء بن السائب، عن محمد بن المنكدر، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1320) and al-Bayhaqi (5/357–358). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Allah forgave a man who lived before you because he was easygoing when he sold, easygoing when he bought, and easygoing when he sought his due.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1320) والبيهقي (10979). قال الترمذي: حسن صحيح."},{"num":5425,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَخَلَ رَجُلٌ الْجَنَّةَ بِسَمَاحَتِهِ، قَاضِيًا وَمُتَقَاضِيًا."],"takhrij":"حسن: رواه أحمد (6963) عن عبد الصمد، حدثني أبي، حدثنا حبيب -يعني المعلم-، عن عمور بن شعيب، عن أبيه، عن عبد الله بن عـمرو فذكره. وإسناده حسن من أجل عمرو بن شعيب؛ فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6963).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As said: The Messenger of Allah ﷺ said: “A man entered Paradise because of his lenience when selling, buying, and collecting what was owed to him.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أحمد (6963)."},{"num":5426,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْمَحْ، يُسْمَحْ لَكَ."],"takhrij":"صحيح: رواه أحمد (2233)، والطبراني في الصغير (1169)، والقضاعي في مسند الشهاب (648)، والبيهقي في شعب الإيمان (11258) كلهم من حديث الوليد بن مسلم، حدثنا ابن جريج، حدثنا عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2233), al-Tabarani in al-Saghir (1169), and al-Quda‘i in Musnad al-Shihab (648).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “Be easy with others, and ease will be shown to you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (2233)، والطبراني في الصغير (1169)، والقضاعي في مسند الشهاب (648)."},{"num":5427,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ حِزَامٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا، فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كتما وكذبا مُحقت بَرَكَةُ بَيْعِهِمَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2079)، ومسلم في البيوع (1532) من طريق شعبة، عن قتادة، عن صالح أبي الخليل، عن عبدالله بن الحارث، عن حكيم بن حزام قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب النصح والصدق في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2079) and Muslim (1532).","chapter_en":"Sincerity and truthfulness in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Hakim ibn Hizam said: The Messenger of Allah ﷺ said: “The buyer and seller retain the choice as long as they have not separated. If they are truthful and make things clear, their sale will be blessed for them. But if they conceal and lie, the blessing of their sale will be erased.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2079)، ومسلم (1532)."},{"num":5428,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أن رجلا ذَكَرَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ يُخْدَعُ فِي الْبُيُوعِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا بَايَعْتَ فَقُلْ: لَا خِلَابَةَ قَالَ: فَكَانَ الرَّجُلُ إِذَا بَايَعَ يَقُولُ: لَا خِلَابَةَ."],"takhrij":"متفق عليه: رواه مالك في البيوع (98) عن عبد الله بن دينار، عن عبدالله بن عمر فذكره. ورواه البخاري في البيوع (2117) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (98), al-Bukhari (2117), and Muslim (1533).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abdullah ibn Umar narrated that a man mentioned to the Messenger of Allah ﷺ that he was being deceived in transactions. So the Messenger of Allah ﷺ said: “When you make a sale, say: No deception.” So whenever that man entered into a sale, he would say: “No deception.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (98) والبخاري (2117) ومسلم (1533)."},{"num":5429,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلاً، عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَبْتَاعُ، وَفِي عُقْدَتِهِ ضَعْفٌ، فَأَتَى أَهْلُهُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا نَبِيَّ اللَّهِ، احْجُرْ عَلَى فُلاَنٍ؛ فَإِنَّهُ يَبْتَاعُ، وَفِي عُقْدَتِهِ ضَعْفٌ، فَدَعَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَهَاهُ عَنِ الْبَيْعِ، فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنِّي لاَ أَصْبِرُ عَنِ الْبَيْعِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنْ كُنْتَ غَيْرَ تَارِكٍ الْبَيْعَ فَقُلْ: هَاءَ وَهَاءَ، وَلاَ خِلاَبَةَ."],"takhrij":"حسن: رواه أبو داود (3501)، وابن الجارود في المنتقى (568)، وابن حبان (5049)، والحاكم (7061)، والبيهقي (11338)، وأحمد (13276) كلهم من حديث عبد الوهاب بن عطاء الخفاف، أخبرنا سعيد بن أبي عروبة، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3501), Ibn al-Jarud in al-Muntaqa (568), Ibn Hibban (5049), and Ahmad (13276).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Anas narrated that during the time of the Messenger of Allah ﷺ, a man used to buy and sell, but he had weakness in his judgment. His family came to the Prophet ﷺ and said: O Prophet of Allah, restrict so-and-so from trade, because he buys and sells while his judgment is weak. So the Prophet ﷺ called him and forbade him from trading. The man said: O Prophet of Allah, I cannot be patient without trade. So the Messenger of Allah ﷺ said: “If you cannot leave trade, then say: Hand to hand, and no deception.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3501)، وابن الجارود في المنتقى (568)، وابن حبان (5049)، وأحمد (13276)."},{"num":5430,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانٍ، قَالَ: هُوَ جَدِّي مُنْقِذُ بْنُ عَمْرٍو وَكَانَ رَجُلاً قَدْ أَصَابَتْهُ آمَّةٌ فِي رَأْسِهِ فَكَسَرَتْ لِسَانَهُ وَكَانَ لاَ يَدَعُ عَلَى ذَلِكَ التِّجَارَةَ، وَكَانَ لاَ يَزَالُ يُغْبَنُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ لَهُ: إِذَا أَنْتَ بَايَعْتَ فَقُلْ: لاَ خِلاَبَةَ. ثُمَّ أَنْتَ فِي كُلِّ سِلْعَةٍ ابْتَعْتَهَا بِالْخِيَارِ ثَلاَثَ لَيَالٍ، فَإِنْ رَضِيتَ فَأَمْسِكْ، وَإِنْ سَخِطْتَ فَارْدُدْهَا عَلَى صَاحِبِهَا."],"takhrij":"حسن: رواه ابن ماجه (2355) عن أبي بكر بن أبي شيبة، قال: حدثنا عبد الأعلى، عن محمد بن إسحاق، عن محمد بن يحيى بن حبان، قال: هو جدي منقذ بن عمرو- وكان رجلا قد أصابته أَمَّةٌ في رأسه، فذكره.","grade":"حسن","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2355).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Muhammad ibn Yahya ibn Hibban said: He was my grandfather Munqidh ibn Amr — and he was a man who had received an injury to his head which affected his tongue. Even so, he would not leave trade, and he would continually be cheated. So he came to the Prophet ﷺ and mentioned that to him, and he said to him: “When you make a purchase, say: No deception. Then for every item you buy, you have the choice for three nights. If you are pleased, keep it, and if you are displeased, return it to its seller.”"]},"buhuth":{"en":["The phrase “No deception” means no fraud or trickery. In Arabic, khalaba means to deceive someone. This hadith indicates protection for one who is weak in judgment, similar to one under legal restriction. Although this wording was specific to him, others with similar mental weakness may be compared to him. However, most jurists held that when two legally competent people transact willingly, then mere unfairness in price does not by itself allow the contract to be undone. Al-Khattabi mentioned this in al-Ma‘alim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2355)."},{"num":5431,"demo":false,"sanad":"","matn":["عَنْ حُصَيْنِ بْنِ قَيْسٍ أَنَّهُ حَمَلَ طَعَامًا إِلَى الْمَدِينَةِ فَلَقِيَ رَسُولَ اللهِ صلى الله عليه وسلم فَقَالَ: مَاذَا تَحْمِلُ يَا أَعْرَابِيُّ؟. قَالَ: قَمْحًا. قَالَ: مَا أَرَدْتَ بِهِ أَوْ مَا تُرِيدُ بِهِ؟. قَالَ: أَرَدْتُ بَيْعَهُ. فَمَسَحَ رَأْسِي، وَقَالَ: أَحْسِنُوا مُبَايَعَةَ الْأَعْرَابِيِّ."],"takhrij":"حسن: رواه الطبراني في الكبير (3559) عن أحمد بن علي الجارودي الأصبهاني، ثنا محمد بن سهل أبو سهل البصري. (ح) وحدثنا الحسين بن إسحاق التستري، ثنا إسحاق بن إبراهيم الصواف، قالا: ثنا أبو الهيثم خلف بن الهيثم النهشلي القصار، حدثنا غسان بن الأغر النهشلي، ثنا عمي زياد بن حصين، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب الإحسان إلى من لا يعرف البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (4/35) and al-Bazzar in Kashf al-Astar (1273).","chapter_en":"Showing kindness to one who does not know buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Husayn ibn Qays narrated that he brought food to Madinah and met the Messenger of Allah ﷺ, who said: “What are you carrying, O Bedouin?” He said: Wheat. He said: “What did you intend with it, or what do you want with it?” He said: I intended to sell it. So he wiped my head and said: “Treat the Bedouin well in buying and selling.”"]},"buhuth":{"en":["The phrase “Treat the Bedouin well in buying and selling” means: do not cheat them, because they generally know less about market dealings."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (3559)، والبزار - كشف الأستار (1273)."},{"num":5432,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كِيلُوا طَعَامَكُمْ يُبَارَكْ لَكُمْ."],"takhrij":"صحيح: رواه البخاري في البيوع (2128) عن إبراهيم بن موسى، حدثنا الوليد، عن ثور، عن خالد بن معدان، عن المقدام فذكره.","grade":"صحيح","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2128).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Al-Miqdam ibn Ma‘di Karib narrated from the Prophet ﷺ: “Measure your food, and blessing will be given to you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2128)."},{"num":5433,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ الْمَازِنِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كِيلُوا طَعَامَكُمْ يُبَارَكْ لَكُمْ فِيهِ."],"takhrij":"حسن: رواه ابن ماجه (2231) عن هشام بن عمار قال: حدثنا إسماعيل بن عياش قال: حدثنا محمد بن عبد الرحمن اليحصبي، عن عبد الله بن بُسر المازني فذكره.","grade":"حسن","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2231).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Busr al-Mazini said: I heard the Messenger of Allah ﷺ say: “Measure your food, and it will be blessed for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2231)."},{"num":5434,"demo":false,"sanad":"","matn":["عن عُثْمَانَ قَالَ: كُنْتُ أَبْتَاعُ التَّمْرَ مِنْ بَطْنٍ مِنَ الْيَهُودِ يُقَالُ لَهُمْ: بَنُو قَيْنُقَاعَ، فَأَبِيعُهُ بِرِبْحٍ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عُثْمَانُ، إِذَا اشْتَرَيْتَ فَاكْتَلْ، وَإِذَا بِعْتَ فَكِلْ."],"takhrij":"حسن: رواه أحمد (444) عن أبي سعيد مولى بني هاشم-، وابن ماجه (2230) من حديث عبدالله بن يزيد-، وعبد بن حميد (52) من حديث عبدالله بن المبارك-، والبيهقي (5/315) من حديث سعيد بن أبي مريم ـ، كل هؤلاء عن عبدالله بن لهيعة، حدثنا موسى بن وردان، سمعت سعيد بن المسيب يقـــــول: سمعت عثمــــــان يخطب على المنبر يقول: فذكره.","grade":"حسن","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (444), Ibn Majah (2230), Abd ibn Humayd (52), and al-Bayhaqi (5/315).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Uthman said: I used to buy dates from a group of Jews called Banu Qaynuqa‘, then sell them at a profit. News of that reached the Messenger of Allah ﷺ, and he said: “O Uthman, when you buy, have it measured for you, and when you sell, measure it out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (444)، وابن ماجه (2230)، وعبد بن حميد (52)، والبيهقي (5/315)."},{"num":5435,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ كَانُوا مِنْ أَخْبَثِ النَّاسِ كَيْلاً، فَأَنْزَلَ اللَّهُ سُبْحَانَهُ {وَيْلٌ لِلْمُطَفِّفِينَ} فَأَحْسَنُوا الْكَيْلَ بَعْدَ ذَلِكَ."],"takhrij":"حسن: رواه ابن ماجه (2223)، وابن حبان (4919)، والحاكم (2240)، والبيهقي (11165) كلهم من طريق علي بن الحسين بن واقد، أخبرنا أبي، عن يزيد النحوي، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب التوقي في الكيل والميزان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2223), Ibn Hibban (4919), al-Hakim (2240), and al-Bayhaqi (6/32).","chapter_en":"Being careful and just in measurement and weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn Abbas said: When the Prophet ﷺ came to Madinah, they were among the worst people in measurement. So Allah, Glorified and Exalted, revealed: “Woe to those who give less in measure,” and after that they improved their measuring."]},"intro":{"ar":["قال الله تعالى: (وَيْلٌ لِلْمُطَفِّفِينَ ١ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ ٢ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ) [سورة المطففين: ١-٣].","وقال تعالى: (فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ) [سورة الأعراف: ٨٥].","وقال تعالى: (وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ) [سورة الإسراء: ٣٥].","وقال تعالى: (وَلَا تَنْقُصُوا الْمِكْيَالَ وَالْمِيزَانَ) [سورة هود: ٨٤]."],"en":["Allah Most High said: “Woe to those who give less in measure, those who, when they take a measure from people, take in full, but when they give by measure or by weight to them, they cause loss.” [Surat al-Mutaffifin, 1–3]","And He said: “So give full measure and weight, and do not deprive people of their things.” [Surat al-A‘raf, 85]","And He said: “Give full measure when you measure, and weigh with a straight balance.” [Surat al-Isra’, 35]","And He said: “Do not reduce the measure and the weight.” [Surat Hud, 84]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13687],"tks":"حسن: رواه ابن ماجه (2223)، وابن حبان (4919)، والحاكم (2240)، والبيهقي (11165)."},{"num":5436,"demo":false,"sanad":"","matn":["عَنْ سُوَيْدِ بْنِ قَيْسٍ، قَالَ: جَلَبْتُ أَنَا وَمَخْرَفَةُ الْعَبْدِيُّ، بَزًّا مِنْ هَجَرَ، فَجَاءَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَاوَمَنَا بِسَرَاوِيلَ، وَعِنْدِي وَزَّانٌ، يَزِنُ بِالأَجْرِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْوَزَّانِ: زِنْ، وَأَرْجِحْ."],"takhrij":"حسن: رواه أبو داود (3336)، والترمذي (1305)، والنسائي (4592)، وابن ماجه (1220)، وأحمد (19098) كلهم من طريق سفيان الثوري، عن سماك، عن سويد بن قيس فذكره، وصحّحه ابن حبان (5147)، والحاكم (2230).","grade":"حسن","chapter_ar":"باب الرجحان في الوزن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3336), al-Tirmidhi (1305), al-Nasa’i (4592), Ibn Majah (2220), and Ahmad (19098).","chapter_en":"Giving extra in weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Suwayd ibn Qays said: Makhrafah al-Abdi and I brought cloth from Hajar. The Prophet ﷺ came to bargain with us for some trousers. I had with me a weigher who weighed for payment, and the Prophet ﷺ said to the weigher: “Weigh, and give extra.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3336)، والترمذي (1305)، والنسائي (4592)، وابن ماجه (1220)، وأحمد (19098)."},{"num":5437,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا وَزَنْتُمْ فَأَرْجِحُوا."],"takhrij":"صحيح: رواه ابن ماجه (2222)، وأبو عوانة (8276)، والقضاعي في مسند الشهاب (759) كلهم من حديث عبد الصمد قال: حدثنا شعبة، عن محارب بن دثار، عن جابر بن عبد الله فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الرجحان في الوزن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2222), Abu Awanah (3/255), and al-Quda‘i in Musnad al-Shihab (759).","chapter_en":"Giving extra in weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “When you weigh, then give extra.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه ابن ماجه (2222)، وأبو عوانة (8276)، والقضاعي في مسند الشهاب (759)."},{"num":5438,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْوَزْنُ وَزْنُ أَهْلِ مَكَّةَ، وَالْمِكْيَالُ مِكْيَالُ أَهْلِ الْمَدِينَةِ."],"takhrij":"صحيح: رواه أبو داود (3340)، والنسائي (2521، 4594)، والبيهقي (7717)، وعبد بن حميد (803) كلهم من طريق أبي نعيم الفضل بن دكين الملائي، حدثنا سفيان، عن حنظلة بن أبي سفيان، عن طاوس، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الوزن وزن أهل مكة، والمكيال مكيال أهل المدينة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3340), al-Nasa’i (4594, 2521), al-Bayhaqi (6/31), and Abd ibn Humayd (803).","chapter_en":"The standard weight is the weight of the people of Makkah, and the standard measure is the measure of the people of Madinah","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “The standard for weight is the weight of the people of Makkah, and the standard for dry measure is the measure of the people of Madinah.”"]},"buhuth":{"en":["The meaning of this hadith, briefly, is that the zakah threshold for gold and silver is judged according to the weight standard of the people of Makkah, which was formalized in the time of Abd al-Malik ibn Marwan when coinage was standardized. Thus, the nisab on silver was two hundred dirhams, and other dirhams in different lands are compared against that standard even if their local weights differ.","As for matters like expiations, the charity of breaking the fast, maintenance amounts, and similar rulings, these are judged according to the measuring standard of the people of Madinah, which is the sa‘. The sa‘ of the people of Madinah differs from the sa‘ of the people of Iraq. The Madinan sa‘ equals five and one-third Iraqi ratls, while the Iraqi sa‘ equals eight ratls.","As for ordinary transactions, the customary local measure of the people of that land is followed. But when the matter concerns Sacred Law and its rulings, then the sa‘ of the people of Madinah is the standard."]},"intro":{"ar":["ومعنى الحديث باختصار أن إخراج الزكاة من الذهب والفضة ينظر إلى ميزان أهل مكة الذي عُدل في عهد عبد الملك بن مروان لما أراد ضرب الدنانير والدراهم، فكان النصاب الذي تجب فيه الزكاة مائتي درهم، وعلى هذا يقاس جميع الدراهم في البلدان المختلفة، وإن كانت أوزانها تختلف من بلد إلى بلد.","وأما ما يتعلق بوجوب الكفارات، وإخراج صدقة الفطر، وتقدير النفقات، وما في معناه، فينظر إلى مكيال أهل المدينة، وهو ما يسمى بالصاع. وصاع أهل المدينة يختلف عن صاع أهل العراق، فصاع أهل المدينة خمسة أرطال وثلث بالعراقي، وصاع أهل العراق ثمانية أرطال.","وأما في المعاملات فيحمل على الصاع المتعارف عند أهل بلده، وإذا كان الأمر يتعلق بالشريعة وأحكامها فهو صاع أهل المدينة."],"en":["The meaning of this hadith, briefly, is that the zakah threshold for gold and silver is judged according to the weight standard of the people of Makkah, which was formalized in the time of Abd al-Malik ibn Marwan when coinage was standardized. Thus, the nisab on silver was two hundred dirhams, and other dirhams in different lands are compared against that standard even if their local weights differ.","As for matters like expiations, the charity of breaking the fast, maintenance amounts, and similar rulings, these are judged according to the measuring standard of the people of Madinah, which is the sa‘. The sa‘ of the people of Madinah differs from the sa‘ of the people of Iraq. The Madinan sa‘ equals five and one-third Iraqi ratls, while the Iraqi sa‘ equals eight ratls.","As for ordinary transactions, the customary local measure of the people of that land is followed. But when the matter concerns Sacred Law and its rulings, then the sa‘ of the people of Madinah is the standard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3340)، والنسائي (4594، 2521)، والبيهقي (7717)، وعبد بن حميد (803)."},{"num":5439,"demo":false,"sanad":"","matn":["عن حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا ـ أَوْ قَالَ: حَتَّى يَتَفَرَّقَا ـ فَإِنْ صَدَقَا، وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَتَمَا، وَكَذَبَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا."],"takhrij":"متفق عليه: رواه البخاري في البيوع (279)، ومسلم في البيوع (1532: 47) كلاهما من طريق شعبة، عن قتادة، عن صالح أبي الخليل، عن عبد الله بن الحارث، عن الحكيم بن حزام قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2079) and Muslim (1532:47).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Hakim ibn Hizam said: The Messenger of Allah ﷺ said: “The buyer and seller retain the choice so long as they have not separated — or he said: until they separate. If they are truthful and clear, their sale will be blessed for them. But if they conceal and lie, the blessing of their sale will be erased.”"]},"intro":{"ar":["فقه الباب: يستفاد من هذه الأحاديث بأن المراد بالتفرق هو التفرق بالأبدان، كما فهمه ابن عمر، وابن عباس، وغيرهما."],"en":["Understanding of this section: These hadiths indicate that the intended meaning of separation is physical separation of the bodies, as understood by Ibn Umar, Ibn Abbas, and others."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (279)، ومسلم (1532: 47)."},{"num":5440,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُتَبَايِعَانِ كُلُّ وَاحِدٍ مِنْهُمَا بِالْخِيَارِ عَلَى صَاحِبِهِ مَا لَمْ يَتَفَرَّقَا، إِلاَّ بَيْعَ الْخِيَارِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (79) عن نافع، عن عبد الله بن عمر فذكره. ورواه البخاري في البيوع (2111)، ومسلم في البيوع (1531: 43) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (79), al-Bukhari (2111), and Muslim (1531:43).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Umar narrated that the Messenger of Allah ﷺ said: “The two parties to a sale each retain the option against the other as long as they have not separated, except in a sale with an agreed option.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (79) والبخاري (2111)، ومسلم (1531: 43)."},{"num":5441,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: إِذَا تَبَايَعَ الرَّجُلاَنِ فَكُلُّ وَاحِدٍ مِنْهُمَا بِالْخِيَارِ، مَا لَمْ يَتَفَرَّقَا، وَكَانَا جَمِيعًا، أَوْ يُخَيِّرُ أَحَدُهُمَا الآخَرَ، فَتَبَايَعَا عَلَى ذَلِكَ، فَقَدْ وَجَبَ الْبَيْعُ، وَإِنْ تَفَرَّقَا بَعْدَ أَنْ يَتَبَايَعَا، وَلَمْ يَتْرُكْ وَاحِدٌ مِنْهُمَا الْبَيْعَ، فَقَدْ وَجَبَ الْبَيْعُ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2112)، ومسلم في البيوع (1531: 44) كلاهما مـن طريق الليث (وهو ابن سعد)، عـن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2112) and Muslim (1531:44). Muslim also narrated it (1531:45) through another route and added: Nafi‘ said: Ibn Umar, when he sold to a man and wanted not to revoke the sale, would stand up, walk a short distance, then return to him.","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “When two men conduct a sale, each of them retains the option as long as they have not separated while they are together, unless one of them gives the other the choice and they transact on that basis, in which case the sale becomes binding. And if they separate after the sale and neither of them has cancelled it, then the sale becomes binding.”"]},"buhuth":{"en":["This indicates that Ibn Umar understood “separation” to mean physical separation of bodies, not merely separation in speech."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2112)، ومسلم (1531: 44)."},{"num":5442,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا، أَوْ يَقُولُ أَحَدُهُمَا لِصَاحِبِهِ: اخْتَرْ. وَرُبَّمَا قَالَ: أَوْ يَكُونُ بَيْعَ خِيَارٍ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2109) ومسلم في البيوع (1531/000) كلاهما من حديث حماد بن زيد، حدثنا أيوب، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2109) and Muslim (1531:47).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ said: “The buyer and seller retain the choice as long as they have not separated, unless one of them says to the other: Choose, or it is a sale with an agreed option.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2109) ومسلم (47 :1531)."},{"num":5443,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بِعْتُ مِنْ أَمِيرِ الْمُؤْمِنِينَ عُثْمَانَ مَالاً بِالْوَادِي بِمَالٍ لَهُ بِخَيْبَرَ، فَلَمَّا تَبَايَعْنَا رَجَعْتُ عَلَى عَقِبِي حَتَّى خَرَجْتُ مِنْ بَيْتِهِ، خَشْيَةَ أَنْ يُرَادَّنِي الْبَيْعَ، وَكَانَتِ السُّنَّةُ أَنَّ الْمُتَبَايِعَيْنِ بِالْخِيَارِ حَتَّى يَتَفَرَّقَا.","قَالَ عَبْدُ اللَّهِ: فَلَمَّا وَجَبَ بَيْعِي وَبَيْعُهُ رَأَيْتُ أَنِّي قَدْ غَبَنْتُهُ بِأَنِّي سُقْتُهُ إِلَى أَرْضِ ثَمُودٍ بِثَلاَثِ لَيَالٍ، وَسَاقَنِي إِلَى الْمَدِينَةِ بِثَلاَثِ لَيَالٍ."],"takhrij":"صحيح: علقه البخاري في البيوع (2116)، فقال: وقال الليث: حدثني عبد الرحمن بن خالد، عن ابن شهاب، عن سالم بن عبد الله، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic according to the standard of al-Bukhari. Ibn Hajar said: al-Isma‘ili connected its chain, and al-Bayhaqi narrated it (5/371).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Umar said: I sold to the Commander of the Believers Uthman ibn Affan, may Allah be pleased with him, some property in the valley in exchange for property of his in Khaybar. When we completed the sale, I walked backward until I exited his house, fearing that he might wish to revoke the sale, because the established practice was that the two parties to a sale retained the option until they physically separated.","Abdullah said: When my sale and his sale became binding, I thought that I had actually gotten the better of him, because I had led him to land in Thamud, three nights away, while he had led me to Madinah, three nights away."]},"buhuth":{"en":["The word “property” here means land or real estate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: وصله الإسماعيلي، والبيهقي (10449)."},{"num":5444,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ ابْتَاعَ بَيْعًا فَوَجَبَ لَهُ فَهُوَ فِيهِ بِالْخِيَارِ عَلَى صَاحِبِهِ مَا لَمْ يُفَارِقْهُ، إِنْ شَاءَ أَخَذَ، وَإِنْ شَاءَ تَرَكَ، فَإِنْ فَارَقَهُ فَلَا خِيَارَ لَهُ."],"takhrij":"حسن: رواه ابن حبان (4914، 4915)، والحاكم (2/14)، وعنه البيهقي (5/270) كلهم من حديث أبي سعيد حفص بن غيلان، حدثنا سليمان بن موسى، عن عطاء بن أبي رباح، عن ابن عباس، وعن نافع، عن ابن عمر فذكراه.","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4914, 4915), al-Hakim (2/14), and al-Bayhaqi (5/270).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Abbas and Ibn Umar narrated from the Prophet ﷺ that he said: “Whoever purchases something and the deal is concluded for him still retains the option against the other party so long as he has not parted from him. If he wishes, he may take it, and if he wishes, he may leave it. But once he parts from him, he no longer has that option.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (4915، 4914)، والحاكم (2/14)، والبيهقي (5/270)."},{"num":5445,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُتَبَايِعَانِ بِالْخِيَارِ مَا لَمْ يَفْتَرِقَا إِلاَّ أَنْ تَكُونَ صَفْقَةَ خِيَارٍ، وَلاَ يَحِلُّ لَهُ أَنْ يُفَارِقَ صَاحِبَهُ خَشْيَةَ أَنْ يَسْتَقِيلَهُ."],"takhrij":"حسن: رواه أبو داود (3456)، والترمذي (1247)، والنسائي (4482)، وأحمد (6721) كلهم من طرق عن ابن عجلان، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو بن العاص فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3456), al-Tirmidhi (1247), who graded it Hasan, al-Nasa’i (4482), and Ahmad (6721).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As narrated that the Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated, unless it is a sale with an agreed option. And it is not lawful for one of them to part from the other out of fear that he may ask to revoke the sale.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3456)، والترمذي (1247) وحسنه، والنسائي (4482)، وأحمد (6721)."},{"num":5446,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا."],"takhrij":"صحيح: رواه ابن ماجه (2183) من طرق عن عبد الصمد قال: حدثنا شعبة، عن قتادة، عن الحسن، عن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2183), Ahmad (20241), al-Nasa’i (4481–4482), and al-Bayhaqi (5/271).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2183) وأحمد (20241)، والنسائي (4481-4482)، والبيهقي (10448)."},{"num":5447,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الأَسْلَمِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا."],"takhrij":"صحيح: رواه أبو داود (3457)، وابن ماجه (2182)، وأحمد (19813) كلهم من حديث حماد بن زيد، عن جميل بن مرة، عن أبي الوضيء، عن أبي برزة الأسلمي، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3457), Ibn Majah (2182), and Ahmad (19813).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Barzah narrated that the Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated.”"]},"buhuth":{"en":["Abu Dawud also mentioned a story: We were on a military expedition and stopped at a camp. One of our companions sold a horse for a slave. They remained for the rest of that day and night. When morning came and departure time arrived, the seller stood to saddle his horse and regretted the sale. He came to the man and demanded the sale be undone, but the man refused to return it. So he said: Let Abu Barzah, a companion of the Prophet ﷺ, judge between us. They came to Abu Barzah in one corner of the camp and told him the story. He said: Are you both satisfied that I judge between you with the judgment of the Messenger of Allah ﷺ? Then he mentioned this hadith. Its chain is authentic."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3457)، وابن ماجه (2182)، وأحمد (19813)."},{"num":5448,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيَّرَ أَعْرَابِيًّا بَعْدَ الْبَيْعِ."],"takhrij":"حسن: رواه الترمذي (1249)، وابن ماجه (2184)، والحاكم (581)، وعنه البيهقي (10443) كلهم من حديث ابن وهب، أنا ابن جريج، أن أبا الزبير المكي حدثه عن جابر فذكره، واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1249), Ibn Majah (2184), and al-Hakim (2/48–49). This is the wording of al-Tirmidhi.","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Prophet ﷺ gave a Bedouin the choice after the sale."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1249)، وابن ماجه (2184)، والحاكم (581)، واللفظ للترمذي."},{"num":5449,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَفْتَرِقَنَّ اثْنَانِ إِلاَّ عَنْ تَرَاضٍ."],"takhrij":"حسن: رواه أبو داود (3458)، والترمذي (1248)، والبيهقي (10446) من حديث يحيى بن أيوب قال: كان أبو زرعة إذا بايع رجلا خيَّره. قال: ثم يقول: خيرني. ويقول: سمعت أبا هريرة يقول. فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3458), al-Tirmidhi (1248), and al-Bayhaqi (5/271).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Two people should not part except upon mutual satisfaction.”"]},"buhuth":{"en":["Understanding of this section: These hadiths indicate that the intended meaning of separation is physical separation of the bodies, as understood by Ibn Umar, Ibn Abbas, and others."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3458)، والترمذي (1248)، والبيهقي (10446)."},{"num":5450,"demo":false,"sanad":"","matn":["عن عَبْدِ الْمَجِيدِ بن وَهْبٍ قَالَ: قَالَ لِي الْعَدَّاءُ بْنُ خَالِدِ بْنِ هَوْذَةَ: أَلاَ أُقْرِئُكَ كِتَابًا كَتَبَهُ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ! قَالَ: قُلْتُ: بَلَى. فَأَخْرَجَ لِي كِتَابًا: هَذَا مَا اشْتَرَى الْعَدَّاءُ بْنُ خَالِدِ بْنِ هَوْذَةَ مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، اشْتَرَى مِنْهُ عَبْدًا أَوْ أَمَةً، لاَ دَاءَ، وَلاَ غَائِلَةَ، وَلاَ خِبْثَةَ، بَيْعَ الْمُسْلِمِ الْمُسْلِمَ."],"takhrij":"حسن: رواه الترمذي (1216)، وابن ماجه (2251)، والبيهقي (5/327) كلهم من طريق عباد بن ليث صاحب الكرابيسي قال: حدثنا عبدالمجيد بن وهب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في البيع على البراءة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1216), Ibn Majah (2251), and al-Bayhaqi (5/327).","chapter_en":"What has come regarding sale on disclaimer","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abd al-Majid ibn Wahb said: Al-‘Adda’ ibn Khalid ibn Hawdhah said to me: Shall I read to you a document that the Messenger of Allah ﷺ wrote for me? I said: Yes. So he brought out a document for me which read: “This is what al-‘Adda’ ibn Khalid ibn Hawdhah purchased from Muhammad, the Messenger of Allah ﷺ. He purchased from him a male slave or a female slave, free of disease, free of concealed defect, and free of bad conduct — the sale of one Muslim to another Muslim.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1216)، وابن ماجه (2251)، والبيهقي (5/327)."},{"num":5451,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَكُنْتُ عَلَى بَكْرٍ صَعْبٍ لِعُمَرَ، فَكَانَ يَغْلِبُنِي، فَيَتَقَدَّمُ أَمَامَ الْقَوْمِ، فَيَزْجُرُهُ عُمَرُ وَيَرُدُّهُ، ثُمَّ يَتَقَدَّمُ فَيَزْجُرُهُ عُمَرُ وَيَرُدُّهُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعُمَرَ: بِعْنِيهِ قَالَ: هُوَ لَكَ يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِعْنِيهِ فَبَاعَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُوَ لَكَ يَا عَبْدَ اللَّهِ بْنَ عُمَرَ، تَصْنَعُ بِهِ مَا شِئْتَ."],"takhrij":"صحيح: رواه البخاري في البيوع (2115)، فقال: وقال الحميدي: حدثنا سفيـان (هو ابن عيينة)، حـدثنا عمرو (هو ابن دينـار)، عن ابن عمر فذكره. ورواه في الهبة (2610) موصولا، فقال: حدثنا عبد الله بن محمد، حدثنا ابن عيينة به نحوه.","grade":"صحيح","chapter_ar":"باب إذا اشترى شيئاً فوهبه من ساعته قبل أن يتفرق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2115) and (2610).","chapter_en":"If someone buys something, then gifts it immediately before the two parties separate","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Ibn Umar said: We were with the Prophet ﷺ on a journey, and I was riding a difficult young camel that belonged to Umar. It kept overpowering me and moving ahead of the people, so Umar would scold it and bring it back. Then it would go forward again, and Umar would scold it and bring it back again. So the Prophet ﷺ said to Umar: “Sell it to me.” Umar said: It is yours, O Messenger of Allah ﷺ. But the Messenger of Allah ﷺ said: “Sell it to me.” So he sold it to the Messenger of Allah ﷺ. Then the Prophet ﷺ said: “It is yours, O Abdullah ibn Umar. Do with it whatever you wish.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2115، 2610)."},{"num":5452,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بَنِي النَّجَّارِ، ثَامِنُونِي بِحَائِطِكُمْ. وَفِيهِ خِرَبٌ وَنَخْلٌ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2106)، ومسلم في المساجد 524: 9) من طريق عبدالوارث بن سعيد، عن أبي التياح الضَبعي، حدثنا أنس بن مالك. فذكره. واللفظ للبخاري، وهو عند مسلم في سياق أطول.","grade":"متفق عليه","chapter_ar":"باب صاحب السلعة أحق بالتثمين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2106) and Muslim (524:9). The wording is that of al-Bukhari.","chapter_en":"The owner of the merchandise has the greater right to set the price","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Anas said: The Prophet ﷺ said: “O Banu al-Najjar, name a price for your garden,” and in it were ruined areas and date-palms."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2106)، ومسلم (524:9). واللفظ للبخاري."},{"num":5453,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ عَائِشَةَ -رَضِيَ اللَّهِ عَنْهَا- سَاوَمَتْ بَرِيرَةَ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الصَّلاَةِ، فَلَمَّا جَاءَ قَالَتْ: إِنَّهُمْ أَبَوْا أَنْ يَبِيعُوهَا إِلاَّ أَنْ يَشْتَرِطُوا الْوَلاَءَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ. قُلْتُ لِنَافِعٍ: حُرًّا كَانَ زَوْجُهَا أَوْ عَبْدًا؟ فَقَالَ: مَا يُدْرِينِي."],"takhrij":"صحيح: رواه البخاري في البيوع (2156) عن حسان بن أبي عباد، حدثنا همام قال: سمعت نافعا يحدث عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب البيع والشراء مع النساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2156).","chapter_en":"Buying and selling with women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Ibn Umar narrated that Aisha, may Allah be pleased with her, bargained for Barirah. Then the Prophet ﷺ went out for prayer, and when he returned she said: They refused to sell her unless they stipulated the right of wala’. So the Prophet ﷺ said: “The right of wala’ belongs only to the one who frees.” I said to Nafi‘: Was her husband free or a slave? He said: How would I know?"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2156)."},{"num":5454,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ مُشْعَانٌّ طَوِيلٌ بِغَنَمٍ يَسُوقُهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَيْعًا أَمْ عَطِيَّةً أَوْ قَالَ أَمْ هِبَةً. قَالَ: لاَ، بَلْ بَيْعٌ. فَاشْتَرَى مِنْهُ شَاةً."],"takhrij":"صحيح: رواه البخاري في البيوع (2216) عن أبي النعمان، حدثنا معتمر بن سليمان، عن أبيه، عن أبي عثمان، عن عبد الرحمن بن أبي بكر.","grade":"صحيح","chapter_ar":"باب البيع والشراء مع المشركين، وأهل الحرب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2216).","chapter_en":"Buying and selling with polytheists and people at war","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abd al-Rahman ibn Abi Bakr said: We were with the Prophet ﷺ when a tall, disheveled polytheist came driving some sheep. The Prophet ﷺ said: “Is it for sale, or a gift — or did he say — or a donation?” He said: No, rather it is a sale. So he bought a sheep from him."]},"buhuth":{"en":["The word “mush‘an” means tall and disheveled in hair.","Ibn Battal said: Dealing with disbelievers is permissible, except selling them what the people of war would use against the Muslims."]},"intro":{"ar":["قوله:  مُشعان  أي طويل شعث الرأس.","قال ابن بطال: معاملة الكفار جائزة إلا بيع ما يستعين به أهل الحرب على المسلمين."],"en":["The word “mush‘an” means tall and disheveled in hair.","Ibn Battal said: Dealing with disbelievers is permissible, except selling them what the people of war would use against the Muslims."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2216)."},{"num":5455,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَجُلاً أَعْتَقَ غُلاَمًا لَهُ عَنْ دُبُرٍ، فَاحْتَاجَ، فَأَخَذَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَنْ يَشْتَرِيهِ مِنِّي؟ فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللَّهِ بِكَذَا وَكَذَا، فَدَفَعَهُ إِلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2141) من طريق الحسين المكتب، عن عطاء بن أبي رباح، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب بيع المدبر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2141) and Muslim (997).","chapter_en":"Selling a slave who was declared to be freed after the owner’s death","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a man declared his slave to be freed after his death, but then he fell into need. So the Prophet ﷺ took him and said: “Who will buy him from me?” Nu‘aym ibn Abdullah bought him for such-and-such an amount, and the Prophet ﷺ handed him over to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2141)، ومسلم (997)."},{"num":5456,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا زَنَتِ الأَمَةُ فَتَبَيَّنَ زِنَاهَا فَلْيَجْلِدْهَا وَلاَ يُثَرّب، ثُمَّ إِنْ زَنَتْ فَلْيَجْلِدْهَا وَلاَ يُثَرّب، ثُمَّ إِنْ زَنَتِ الثَّالِثَةَ فَلْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2152)، ومسلم في الحدود (1703) كلاهما من طريق الليث، حدثني سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب بيع الأمة الزانية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2152) and Muslim (1703).","chapter_en":"Selling a slave-woman who commits fornication","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “If a slave-woman commits fornication and her fornication becomes clear, then let her be flogged and not rebuked. Then if she commits fornication again, let her be flogged and not rebuked. Then if she commits fornication a third time, let her be sold, even for a rope of hair.”"]},"buhuth":{"en":["The phrase “then let her be sold” means while making her defect known, because concealing defects is not allowed according to the general evidence."]},"intro":{"ar":["وقوله:  فليبعها  أي مع بيان عيبها؛ لأن كتمان العيوب لا يجوز من عموم الأدلة."],"en":["The phrase “then let her be sold” means while making her defect known, because concealing defects is not allowed according to the general evidence."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2152)، ومسلم (1703)."},{"num":5457,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الأَمَةِ إِذَا زَنَتْ، وَلَمْ تُحْصِنْ؟ قَالَ: إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا، ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ بِضَفِيرٍ.","قَالَ ابْنُ شِهَابٍ الزهري: \"لَا أَدْرِي أَبَعْدَ الثَّالِثَةِ، أَوِ الرَّابِعَةِ\"."],"takhrij":"متفق عليه: رواه مالك في الحدود (14) عن ابن شهاب، عن عبيدالله بن عتبة بن مسعود، عن أبي هريرة، وزيد بن خالد الجهني فذكراه.","grade":"متفق عليه","chapter_ar":"باب بيع الأمة الزانية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (2154), and Muslim (1704).","chapter_en":"Selling a slave-woman who commits fornication","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani narrated that the Messenger of Allah ﷺ was asked about a slave-woman if she committed fornication before being married. He said: “If she commits fornication, then flog her. Then if she commits fornication, flog her. Then if she commits fornication, flog her. Then sell her, even for a braided rope.” Ibn Shihab al-Zuhri said: I do not know whether that was after the third or the fourth time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14) والبخاري (2154)، ومسلم (1704)."},{"num":5458,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: إِنَّ خَيَّاطًا دَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ صَنَعَهُ. قَالَ أَنَسُ: فَذَهَبْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى ذَلِكَ الطَّعَامِ، فَقَرَّبَ إليّ خُبْزًا مِنْ شَعِيرٍ وَمَرَقًا فِيهِ دُبَّاءٌ.","قَالَ أَنَسٌ: فَرَأَيْتُ النبي صلى الله عليه وسلم يَتَتَبَّعُ الدُّبَّاءَ مِنْ حَوْلِ الْقَصْعَةِ، فَلَمْ أَزَلْ أُحِبُّ الدُّبَّاءَ بَعْدَ ذَلِكَ الْيَوْمِ."],"takhrij":"متفق عليه: رواه مالك في النكاح (51) عن إسحاق بن عبد الله بن أبي طلحة، أنه سمع أنس بن مالك يقول فذكره. ورواه البخاري في البيوع (2092)، ومسلم في الأشربة (2041) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الخياطة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (51), al-Bukhari (2092), and Muslim (2041).","chapter_en":"What has come regarding the profession of tailoring","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: A tailor invited the Messenger of Allah ﷺ to food he had prepared. Anas said: I went with the Messenger of Allah ﷺ to that meal. He presented to him barley bread and broth containing gourd and dried meat.","Anas said: I saw the Prophet ﷺ picking out the gourd from around the dish, and I have loved gourd ever since that day."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (51) والبخاري (2092)، ومسلم (2041)."},{"num":5459,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ بِبُرْدَةٍ. ـ قَالَ: أَتَدْرُونَ مَا الْبُرْدَةُ؟ فَقِيلَ لَهُ: نَعَمْ، هِيَ الشَّمْلَةُ، مَنْسُوجٌ فِي حَاشِيَتِهَا. ـ قَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي نَسَجْتُ هَذِهِ بِيَدِي أَكْسُوكَهَا. فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا. فَخَرَجَ إِلَيْنَا، وَإِنَّهَا إِزَارُهُ. فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللَّهِ، اكْسُنِيهَا، فَقَالَ: نَعَمْ. فَجَلَسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَجْلِسِ، ثُمَّ رَجَعَ، فَطَوَاهَا، ثُمَّ أَرْسَلَ بِهَا إِلَيْهِ. فَقَالَ لَهُ الْقَوْمُ: مَا أَحْسَنْتَ، سَأَلْتَهَا إِيَّاهُ، لَقَدْ عَلِمْتَ أَنَّهُ لاَ يَرُدُّ سَائِلاً. فَقَالَ الرَّجُلُ: وَاللَّهِ مَا سَأَلْتُهُ إِلاَّ لِتَكُونَ كَفَنِي يَوْمَ أَمُوتُ. قَالَ سَهْلٌ: فَكَانَتْ كَفَنَهُ."],"takhrij":"صحيح: رواه البخاري في البيوع (2093) عن يحيى بن بكير، حدثنا يعقوب بن عبد الرحمن، عن أبي حازم قال: سمعت سهل بن سعد قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النساجة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2093).","chapter_en":"What has come regarding the profession of weaving","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Sahl ibn Saʿd reported: A woman brought a mantle. He said, “Do you know what a burdah is?” They replied, “Yes, it is a wrap woven with a border.” She said: “O Messenger of Allah ﷺ, I wove this with my own hands so that I could clothe you with it.” The Prophet ﷺ took it because he was in need of it, and later came out to us wearing it as his lower garment. A man among the people said: “O Messenger of Allah ﷺ, give it to me to wear.” He replied: “Yes.” The Prophet ﷺ remained seated in the gathering for a while, then returned, folded the garment, and sent it to the man. The people said to him: “You did not do well. You asked him for it even though you knew that he never turns away anyone who asks him.” The man replied: “By Allah, I only asked him for it so that it might be my shroud on the day I die.” Sahl said: And it became his shroud."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2093)."},{"num":5460,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ، قَالَ: أَتَى رِجَالٌ إِلَى سَهْلِ بْنِ سَعْدٍ يَسْأَلُونَهُ عَنِ الْمِنْبَرِ، فَقَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى فُلاَنَةَ ـ امْرَأَةٍ قَدْ سَمَّاهَا سَهْلٌ: ـ أَنْ مُرِي غُلاَمَكِ النَّجَّارَ، يَعْمَلُ لِي أَعْوَادًا، أَجْلِسُ عَلَيْهِنَّ إِذَا كَلَّمْتُ النَّاسَ. فَأَمَرَتْهُ يَعْمَلُهَا مِنْ طَرْفَاءِ الْغَابَةِ، ثُمَّ جَاءَ بِهَا، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهَا، فَأَمَرَ بِهَا، فَوُضِعَتْ، فَجَلَسَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2094)، ومسلم في المساجد (544) كلاهما عن قتيبة، عن عبد العزيز (وهو ابن أبي حازم)، عن أبي حازم. والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2094) and Muslim (544). This is the wording of al-Bukhārī.","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abū Ḥāzim reported: Some men came to Sahl ibn Saʿd asking him about the pulpit. He said: The Messenger of Allah ﷺ sent word to a certain woman, whom Sahl named: “Tell your carpenter servant to make some pieces of wood for me upon which I can sit when I address the people.” She instructed him to do so, and he made it from tamarisk wood from al-Ghābah. He then brought it, and she sent it to the Messenger of Allah ﷺ. He ordered that it be placed in position, and he sat upon it."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2094)، ومسلم (544)، والسياق للبخاري."},{"num":5461,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ امْرَأَةً مِنَ الأَنْصَارِ قَالَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، أَلاَ أَجْعَلُ لَكَ شَيْئًا تَقْعُدُ عَلَيْهِ، فَإِنَّ لِي غُلاَمًا نَجَّارًا. قَالَ: إِنْ شِئْتِ. قَالَ: فَعَمِلَتْ لَهُ الْمِنْبَرَ، فَلَمَّا."],"takhrij":"صحيح: رواه البخاري في البيوع (2095) عن خلاد بن يحيى، حدثنا عبدالواحد بن أيمن، عن أبيه، عن جابر. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2095).","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a woman from the Ansar said to the Messenger of Allah ﷺ: O Messenger of Allah ﷺ, shall I make something for you to sit upon, for I have a servant who is a carpenter? He said: “If you wish.” So she made the pulpit for him…"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2095)."},{"num":5462,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  كَانَ زَكَرِيَّاءُ نَجَّارًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (2379) عن هداب بن خالد، حدثنا حماد بن سلمة، عن ثابت، عن أبي رافع، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2379).","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Zakariyya was a carpenter.”"]}},"tuhfa":{},"full":1,"rep":[8469],"tks":"صحيح: رواه مسلم (2379)."},{"num":5463,"demo":false,"sanad":"","matn":["عَنْ خَبَّابٍ، قَالَ: كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ، وَكَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ، فَأَتَيْتُهُ أَتَقَاضَاهُ. قَالَ: لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ: لاَ أَكْفُرُ حَتَّى يُمِيتَكَ اللَّهُ، ثُمَّ تُبْعَثَ. قَالَ: دَعْنِي حَتَّى أَمُوتَ وَأُبْعَثَ، فَسَأُوتَى مَالاً وَوَلَدًا فَأَقْضِيَكَ، فَنَزَلَتْ: ﴿أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا﴾ [سورة مريم: 77، 78]."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2091)، ومسلم في صفات المنافقين (2795) كلاهما من طريق سليمان الأعمش، عن أبي الضحى، عن مسروق، عن خباب فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الحدادة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2091) and Muslim (2795).","chapter_en":"What has come regarding the profession of blacksmithing","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Khabbab said: I was a blacksmith in the time of ignorance, and al-‘As ibn Wa’il owed me a debt. I came to him to demand it. He said: I will not pay you until you disbelieve in Muhammad. So I said: I will not disbelieve until Allah causes you to die and then resurrects you. He said: Leave me until I die and am resurrected, and then I will be given wealth and children, and I will repay you. Then this was revealed: “Have you seen the one who disbelieved in Our signs and said: I will surely be given wealth and children? Has he looked into the unseen, or has he taken a covenant with the Most Merciful?” [Surat Maryam, 77–78]"]},"buhuth":{"en":["The phrase “I was a qayn” means: I was a blacksmith. Ibn Durayd said: the original meaning of qayn is blacksmith, then it later came to be used among the Arabs for any craftsman of metalwork. Al-Zajjaj said: a qayn is one who repairs spearheads, and also a blacksmith."]},"intro":{"ar":["قوله:  كنت قيناً  قال ابن دريد: أصل القين الحداد، ثم صار كل صائغ عند العرب قيناً. وقال الزجاج: القين الذي يصلح الأسنة، والقين أيضاً الحداد."],"en":["The phrase “I was a qayn” means: I was a blacksmith. Ibn Durayd said: the original meaning of qayn is blacksmith, then it later came to be used among the Arabs for any craftsman of metalwork. Al-Zajjaj said: a qayn is one who repairs spearheads, and also a blacksmith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2091)، ومسلم (2795)."},{"num":5464,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَثَلُ الْجَلِيسِ الصَّالِحِ وَالْجَلِيسِ السَّوْءِ كَمَثَلِ صَاحِبِ الْمِسْكِ وَكِيرِ الْحَدَّادِ، لاَ يَعْدَمُكَ مِنْ صَاحِبِ الْمِسْكِ: إِمَّا تَشْتَرِيهِ، أَوْ تَجِدُ رِيحَهُ. وَكِيرُ الْحَدَّادِ يُحْرِقُ بَدَنَكَ أَوْ ثَوْبَكَ، أَوْ تَجِدُ مِنْهُ رِيحًا خَبِيثَةً."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2101)، ومسلم في البر والصلة (2628) كلاهما من طريق بُريد بن عبد الله (هو ابن أبي بردة بن أبي موسى الأشعري)، عن جده أبي بردة بن أبي موسى الأشعري، عن أبي موسى الأشعري فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في العطارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2101) and Muslim (2628).","chapter_en":"What has come regarding the perfume trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “The example of a righteous companion and an evil companion is like the seller of musk and the blacksmith’s bellows. From the seller of musk, you will at least not miss one of these: either you buy from him, or you enjoy his fragrance. But the blacksmith’s bellows may burn your body or your clothes, or you will find from it a foul smell.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2101)، ومسلم (2628)."},{"num":5465,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ قَالَ: كَانَتْ لِي شَارِفٌ مِنْ نَصِيبِي مِنَ الْمَغْنَمِ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَانِي شَارِفًا مِنَ الْخُمْسِ، فَلَمَّا أَرَدْتُ أَنْ أَبْتَنِيَ بِفَاطِمَةَ ـ عَلَيْهَا السَّلاَمُ ـ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاعَدْتُ رَجُلاً صَوَّاغًا مِنْ بَنِي قَيْنُقَاعَ أَنْ يَرْتَحِلَ مَعِي فَنَأْتِيَ بِإِذْخِرٍ أَرَدْتُ أَنْ أَبِيعَهُ مِنَ الصَّوَّاغِينَ، وَأَسْتَعِينَ بِهِ فِي وَلِيمَةِ عُرُسِي."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2089)، ومسلم في الأشربة (1979)، كلاهما من طريق عبد الله بن وهب، حدثني يونس بن يزيد، عن ابن شهاب، أخبرني، علي بن حسين بن علي، أن حسين بن علي أخبره، أن عليا قال. فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الصياغة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2089) and Muslim (1979).","chapter_en":"What has come regarding the profession of goldsmithing","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Ali ibn Abi Talib said: I had a she-camel from my share of the war booty, and the Prophet ﷺ had also given me a she-camel from the khums. When I intended to marry Fatimah, the daughter of the Messenger of Allah ﷺ, I made an arrangement with a goldsmith from Banu Qaynuqa‘ to travel with me so that we could bring idhkhir grass. I intended to sell it to the goldsmiths and use the proceeds to help with the wedding feast of my marriage."]},"buhuth":{"en":["The phrase “a goldsmith” means one whose trade is working jewelry from silver, gold, and the like."]},"intro":{"ar":["قوله:  رجلاً صواغاً  وفي مسلم:  ومعي صائغ . والصائغ من حرفته الصياغة، وهي عمل الحلي من فضة وذهب ونحوهما."],"en":["The phrase “a goldsmith” means one whose trade is working jewelry from silver, gold, and the like."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2089)، ومسلم (1979)."},{"num":5466,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ قَالَ: احْتَجَمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، حجمه أَبُو طَيْبَةَ فَأَمَرَ لَهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَاعٍ مِنْ تَمْرٍ، وَأَمَرَ أَهْلَهُ أَنْ يُخَفِّفُوا عَنْهُ مِنْ خَرَاجِهِ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (26) عن حميد الطويل، عن أنس.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الحجامة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (26), al-Bukhari (2102), and Muslim (1577:64).","chapter_en":"What has come regarding the profession of cupping","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ underwent cupping, and Abu Taybah performed the cupping for him. So the Messenger of Allah ﷺ ordered that he be given one sa‘ of dates, and he ordered his masters to reduce the amount of tax or earnings they required from him."]},"buhuth":{"en":["Muslim also narrated it (1577:62) through another route from Humayd, who said: Anas ibn Malik was asked about the earnings of the cupper, and he said: The Messenger of Allah ﷺ underwent cupping, and Abu Taybah cupped him. He ordered that he be given two sa‘s of food, spoke to his masters, and they reduced his dues. He also said: “Among the best treatments you use is cupping,” or “it is among the best of your remedies.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (26) والبخاري (2102) ومسلم (64:1577)."},{"num":5467,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: احْتَجَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَعْطَى الَّذِي حَجَمَهُ، وَلَوْ كَانَ حَرَامًا لَمْ يُعْطِهِ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2103) من طريق عكرمة، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الحجامة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2103) and Muslim (1202:65).","chapter_en":"What has come regarding the profession of cupping","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ underwent cupping and gave payment to the one who cupped him. If it had been unlawful, he would not have paid him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2103)، ومسلم (65:1202)."},{"num":5468,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  بَيْنَمَا ثَلَاثَةُ نَفَرٍ يَتَمَشَّوْنَ أَخَذَهُمُ الْمَطَرُ، فَأَوَوْا إِلَى غَارٍ فِي جَبَلٍ، فَانْحَطَّتْ عَلَى فَمِ غَارِهِمْ صَخْرَةٌ مِنَ الْجَبَلِ، فَانْطَبَقَتْ عَلَيْهِمْ، فَقَالَ بَعْضُهُمْ لِبَعْضٍ: انْظُرُوا أَعْمَالًا عَمِلْتُمُوهَا صَالِحَةً لِلهِ، فَادْعُوا اللَّهَ تَعَالَى بِهَا، لَعَلَّ اللَّهَ يَفْرُجُهَا عَنْكُمْ. فَقَالَ أَحَدُهُمُ: اللَّهُمَّ إِنَّهُ كَانَ لِي وَالِدَانِ شَيْخَانِ كَبِيرَانِ، وَامْرَأَتِي، وَلِي صِبْيَةٌ صِغَارٌ أَرْعَى عَلَيْهِمْ، فَإِذَا أَرَحْتُ عَلَيْهِمْ حَلَبْتُ، فَبَدَأْتُ بِوَالِدَيَّ، فَسَقَيْتُهُمَا قَبْلَ بَنِيَّ، وَأَنَّهُ نَأَى بِي ذَاتَ يَوْمٍ الشَّجَرُ، فَلَمْ آتِ حَتَّى أَمْسَيْتُ، فَوَجَدْتُهُمَا قَدْ نَامَا، فَحَلَبْتُ كَمَا كُنْتُ أَحْلُبُ، فَجِئْتُ بِالْحِلَابِ، فَقُمْتُ عِنْدَ رُءُوسِهِمَا أَكْرَهُ أَنْ أُوقِظَهُمَا مِنْ نَوْمِهِمَا، وَأَكْرَهُ أَنْ أَسْقِيَ الصِّبْيَةَ قَبْلَهُمَا، وَالصِّبْيَةُ يَتَضَاغَوْنَ عِنْدَ قَدَمَيَّ، فَلَمْ يَزَلْ ذَلِكَ دَأْبِي وَدَأْبَهُمْ حَتَّى طَلَعَ الْفَجْرُ، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مِنْهَا فُرْجَةً نَرَى مِنْهَا السَّمَاءَ، فَفَرَجَ اللَّهُ مِنْهَا فُرْجَةً، فَرَأَوْا مِنْهَا السَّمَاءَ. وَقَالَ الْآخَرُ: اللَّهُمَّ إِنَّهُ كَانَتْ لِيَ ابْنَةُ عَمٍّ أَحْبَبْتُهَا كَأَشَدِّ مَا يُحِبُّ الرِّجَالُ النِّسَاءَ، وَطَلَبْتُ إِلَيْهَا نَفْسَهَا فَأَبَتْ حَتَّى آتِيَهَا بِمِائَةِ دِينَارٍ فَتَعِبْتُ حَتَّى جَمَعْتُ مِائَةَ دِينَارٍ، فَجِئْتُهَا بِهَا، فَلَمَّا وَقَعْتُ بَيْنَ رِجْلَيْهَا قَالَتْ: يَا عَبْدَ اللَّهِ اتَّقِ اللَّهَ، وَلَا تَفْتَحِ الْخَاتَمَ إِلَّا بِحَقِّهِ، فَقُمْتُ عَنْهَا، فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مِنْهَا فُرْجَةً، فَفَرَجَ لَهُمْ. وَقَالَ الْآخَرُ: اللَّهُمَّ إِنِّي كُنْتُ اسْتَأْجَرْتُ أَجِيرًا بِفَرَقِ أَرُزٍّ، فَلَمَّا قَضَى عَمَلَهُ قَالَ: أَعْطِنِي حَقِّي فَعَرَضْتُ عَلَيْهِ فَرَقَهُ فَرَغِبَ عَنْهُ، فَلَمْ أَزَلْ أَزْرَعُهُ حَتَّى جَمَعْتُ مِنْهُ بَقَرًا وَرِعَاءَهَا، فَجَاءَنِي فَقَالَ: اتَّقِ اللَّهَ، وَلَا تَظْلِمْنِي حَقِّي قُلْتُ: اذْهَبْ إِلَى تِلْكَ الْبَقَرِ وَرِعَائِهَا فَخُذْهَا فَقَالَ: اتَّقِ اللَّهَ، وَلَا تَسْتَهْزِئْ بِي فَقُلْتُ: إِنِّي لَا أَسْتَهْزِئُ بِكَ خُذْ ذَلِكَ الْبَقَرَ وَرِعَاءَهَا فَأَخَذَهُ، فَذَهَبَ بِهِ فَإِنْ كُنْتَ تَعْلَمُ أَنِّي فَعَلْتُ ذَلِكَ ابْتِغَاءَ وَجْهِكَ فَافْرُجْ لَنَا مَا بَقِيَ، فَفَرَجَ اللَّهُ مَا بَقِيَ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2215)، ومسلم في الذكر (2743) كلاهما من حديث موسى بن عقبة، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب من اتجر بمال غيره فرضي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2215) and Muslim (2743).","chapter_en":"One who invested another person’s property and grew it for him","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Abdullah ibn Umar narrated from the Messenger of Allah ﷺ that he said: “Three men were walking when rain overtook them, so they took shelter in a cave in a mountain. Then a rock fell from the mountain over the mouth of their cave and sealed them in. They said to one another: Look to righteous deeds that you did for Allah and call upon Allah by means of them, perhaps Allah will relieve you from this. One of them said: O Allah, I had elderly parents, a wife, and small children. I used to graze for them, and when I returned I would milk the animals and begin with my parents, giving them drink before my children. One day the trees kept me far away, so I did not return until evening. I found them asleep, so I milked as I used to milk and came with the milk vessel and stood by their heads, disliking to wake them from sleep and disliking to give the children drink before them, while the children were crying at my feet. That remained my state and theirs until dawn broke. If You know that I did that seeking Your Face, then open for us an opening through which we can see the sky. So Allah opened for them an opening through which they saw the sky. Another said: O Allah, I had a female cousin whom I loved as intensely as a man can love a woman. I sought her for myself, but she refused until I brought her one hundred dinars. I worked hard until I gathered one hundred dinars, then I brought them to her. When I sat between her legs, she said: O servant of Allah, fear Allah and do not break the seal except by its right. So I stood up and left her. If You know that I did that seeking Your Face, then open for us from it an opening. So He opened for them further. Another said: O Allah, I hired a laborer for a measure of rice. When he finished his work, he said: Give me my due. I offered him his measure, but he declined it. I continued investing it until I gathered from it cattle and their shepherds. Then he came back to me and said: Fear Allah and do not wrong me regarding my right. I said: Go to those cattle and their shepherds and take them. He said: Fear Allah and do not mock me. I said: I am not mocking you. Take those cattle and their shepherds. So he took them and went away. If You know that I did that seeking Your Face, then relieve for us what remains. So Allah relieved what remained.”"]}},"tuhfa":{},"full":1,"rep":[8286,10968],"tks":"متفق عليه: رواه البخاري (2215)، ومسلم (2743)."},{"num":5469,"demo":false,"sanad":"","matn":["عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِيهِ قَالَ:  مَرَرْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَوْمٍ عَلَى رُءُوسِ النَّخْلِ، فَقَالَ: مَا يَصْنَعُ هَؤُلَاءِ؟ فَقَالُوا: يُلَقِّحُونَهُ، يَجْعَلُونَ الذَّكَرَ فِي الْأُنْثَى فَيَلْقَحُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَظُنُّ يُغْنِي ذَلِكَ شَيْئًا. قَالَ: فَأُخْبِرُوا بِذَلِكَ فَتَرَكُوهُ، فَأُخْبِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، فَقَالَ: إِنْ كَانَ يَنْفَعُهُمْ ذَلِكَ فَلْيَصْنَعُوهُ؛ فَإِنِّي إِنَّمَا ظَنَنْتُ ظَنًّا، فَلَا تُؤَاخِذُونِي بِالظَّنِّ، وَلَكِنْ إِذَا حَدَّثْتُكُمْ عَنِ اللَّهِ شَيْئًا فَخُذُوا بِهِ؛ فَإِنِّي لَنْ أَكْذِبَ عَلَى اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2361) من طرق عن أبي عوانة، عن سماك، عن موسى بن طلحة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2361).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Musa ibn Talhah narrated from his father, who said: I passed with the Messenger of Allah ﷺ by some people at the tops of date-palms. He said: “What are these people doing?” They said: They are pollinating them, placing the male into the female so it becomes pollinated. The Messenger of Allah ﷺ said: “I do not think that will help at all.” They were informed of that and so they stopped doing it. Then the Messenger of Allah ﷺ was informed of that, and he said: “If it benefits them, then let them do it. I only made an assumption, so do not take me to task over an assumption. But when I tell you something from Allah, then take it, for I will never lie about Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"rep":[15662],"tks":"صحيح: رواه مسلم (2361)."},{"num":5470,"demo":false,"sanad":"","matn":["عن رَافِعِ بن خَدِيجٍ قَالَ:  قَدِمَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وَهُمْ يَأْبُرُونَ النَّخْلَ. - يَقُولُونَ: يُلَقِّحُونَ النَّخْلَ. - فَقَالَ: مَا تَصْنَعُونَ؟ قَالُوا: كُنَّا نَصْنَعُهُ. قَالَ: لَعَلَّكُمْ لَوْ لَمْ تَفْعَلُوا كَانَ خَيْرًا. فَتَرَكُوهُ، فَنَفَضَتْ، أَوْ فَنَقَصَتْ، قَالَ: فَذَكَرُوا ذَلِكَ لَهُ، فَقَالَ: إِنَّمَا أَنَا بَشَرٌ، إِذَا أَمَرْتُكُمْ بِشَيْءٍ مِنْ دِينِكُمْ فَخُذُوا بِهِ، وَإِذَا أَمَرْتُكُمْ بِشَيْءٍ مِنْ رَأْيِي فَإِنَّمَا أَنَا بَشَرٌ. قَالَ عِكْرِمَةُ: أَوْ نَحْوَ هَذَا."],"takhrij":"صحيح: رواه مسلم في كتاب الفضائل (2362) من طرق عن النضر ابن محمد، حدثنا عكرمة (وهو ابن عمار)، حدثنا أبو النجاشي، حدثني رافع بن خديج. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2362).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: The Prophet of Allah ﷺ came to Madinah while they were fertilizing the date-palms — meaning pollinating them. He said: “What are you doing?” They said: We have always done it. He said: “Perhaps if you did not do it, it might be better.” So they left it, and the crop fell off, or decreased. They mentioned that to him, and he said: “I am only a human being. If I command you regarding something of your religion, then take it. But if I command you regarding something from my own opinion, then I am only a human being.” Ikrimah said: Or words similar to this."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2362)."},{"num":5471,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، وأنس أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَوْمٍ يُلَقِّحُونَ، فَقَالَ: لَوْ لَمْ يَفْعَلُوا لَصَلَُحَ قَالَ: فَخَرَجَ شِيصًا، فَمَرَّ بِهِمْ، فَقَالَ: مَا لِنَخْلِكُمْ؟ قَالُوا: قُلْتَ كَذَا وَكَذَا. قَالَ: أَنْتُمْ أَعْلَمُ بِأَمْرِ دُنْيَاكُمْ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2363) من طرق عن أسود بن عامر، حدثنا حماد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة، وعن ثابت، عن أنس. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2363).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Aisha and Anas narrated that the Prophet ﷺ passed by people pollinating date-palms and said: “If they did not do this, it might turn out well.” Then the fruit came out inferior. Later he passed by them and said: “What happened to your palms?” They said: You said such-and-such. He said: “You are more knowledgeable about the matters of your worldly life.”"]},"buhuth":{"en":["The word “shaysan” means poor-quality dates which, when dried, become inferior dry dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2363)."},{"num":5472,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ بَاعَ نَخْلاً قَدْ أُبِّرَتْ، فَثَمَرُهَا لِلْبَائِعِ، إِلاَّ أَنْ يَشْتَرِطَ الْمُبْتَاعُ."],"takhrij":"متفق عليه: رواه مالك في البيوع (9) عن نافع، عن ابن عمر.","grade":"متفق عليه","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (2204), and Muslim (1543:77).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “Whoever sells date-palms after they have been pollinated, then their fruit belongs to the seller unless the buyer makes it a condition.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9) والبخاري (2204)، ومسلم (77 :1543)."},{"num":5473,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنِ ابْتَاعَ نَخْلاً بَعْدَ أَنْ تُؤَبَّرَ فَثَمَرَتُهَا لِلْبَائِعِ، إِلاَّ أَنْ يَشْتَرِطَ الْمُبْتَاعُ، وَمَنِ ابْتَاعَ عَبْدًا وَلَهُ مَالٌ فَمَالُهُ لِلَّذِي بَاعَهُ إِلاَّ أَنْ يَشْتَرِطَ الْمُبْتَاعُ."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2379)، ومسلم في البيوع (1543: 80) كلاهما من طريق الليث، عن ابن شهاب الزهري، عن سالم، عن أبيه عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2379) and Muslim (1543:80).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ say: “Whoever purchases date-palms after they have been pollinated, then their fruit belongs to the one who sold them unless the buyer makes it a condition. And whoever purchases a slave, then his wealth belongs to the one who sold him unless the buyer makes it a condition.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2379)، ومسلم (1543: 80)."},{"num":5474,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، وجابر أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ ابْتَاعَ عَبْدًا وَلَهُ مَالٌ فَلَهُ مَالُهُ، وَعَلَيْهِ دَيْنُهُ إِلَاّ أَنْ يَشْتَرِطَ الْمُبْتَاعُ، وَمَنْ أبرَّ نَخْلًا فَبَاعَهُ بَعْدَ تَأْبِيرِهِ فَلَهُ ثَمَرُهُ إِلَاّ أَنْ يَشْتَرِطَ الْمُبْتَاعُ."],"takhrij":"حسن: رواه ابن حبان (9424)، والبيهقي (11004) كلاهما من حديث سليمان بن موسى، عن نافع، عن ابن عمر، وعطاء، عن جابر. فذكره.","grade":"حسن","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4924) and al-Bayhaqi (5/325–326).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar and Jabir narrated that the Messenger of Allah ﷺ said: “Whoever buys a slave who has wealth, then his wealth belongs to the seller unless the buyer makes it a condition. And whoever pollinates date-palms and then sells them after pollination, then their fruit belongs to him unless the buyer makes it a condition.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (9424)، والبيهقي (11004)."},{"num":5475,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اشْتَرَى نَخْلًا بَعْدَمَا أُبِّرَتْ، وَلَمْ يَشْتَرِطْ ثَمَرَهَا فَلَا شَيْءَ لَهُ، وَمَنِ اشْتَرَى عَبْدًا، وَلَمْ يَشْتَرِطْ مَالَهُ فَلَا شَيْءَ لَهُ."],"takhrij":"صحيح: رواه علي بن الجعد (2875)، ومن طريقه ابن حبان (4921) عن أبي يعلى، عنه، عن ابن أبي ذئب، عن ابن شهاب، عن سالم بن عبد الله، عن ابن عمر. فذكره.","grade":"صحيح","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ali ibn al-Ja‘d (2875) and Ibn Hibban (4921).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “Whoever buys date-palms after they have been pollinated and does not stipulate their fruit, then he has no right to it. And whoever buys a slave and does not stipulate his wealth, then he has no right to it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه علي بن الجعد (2875)، وابن حبان (4921)."},{"num":5476,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَقَالَ مُسْلِمًا أَقَالَهُ اللَّهُ عَثْرَتَهُ. يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه أبو داود (3460)، وابن ماجه (2199)، وعبد الله بن أحمد (7431)، وصحّحه ابن حبان (5030)، والحاكم (2291) كلهم من طريق الأعمش، عن أبي صالح، عن أبي هريرة. فذكره.","grade":"صحيح","chapter_ar":"باب فضل الإقالة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3460), Ibn Majah (2199), and authenticated by Ibn Hibban (5030).","chapter_en":"The virtue of canceling a sale by mutual agreement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever releases a Muslim from a sale, Allah will relieve his slip.” In another narration: “on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3460)، وابن ماجه (2199)، وصححه ابن حبان (5030)."},{"num":5477,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْخَرَاجُ بِالضَّمَانِ."],"takhrij":"حسن: رواه الشافعي في مسنده (1203) قال: أخبرني من لا أتهم عن ابن أبي ذئب، عن مخلد بن خفاف قال: ابتعت غلاما، فاستغللته، ثم ظهرت منه على عيب، فخاصمت فيه إلى عمر بن عبد العزيز، فقضى لي برده، وقضى علي برد غلته، فأتيت عروة، فأخبرته، فقال: أروح إليه العشية، فأخبره أن عائشة أخبرتني أن رسول الله صلى الله عليه وسلم قضى في مثل هذا أن الخراج بالضمان. فعجلت إلى عمر، فأخبرته ما أخبرني عروة، عن عائشة، عن النبي صلى الله عليه وسلم، فقال عمر بن عبد العزيز: \"فما أيسر علي من قضاء قضيته، والله يعلم أني لم أرد فيه إلا الحق، فبلغتني فيه سنة عن رسول الله صلى الله عليه وسلم، فأرد قضاء عمر، وأنفذ سنة رسول الله صلى الله عليه وسلم\". فراح إليه عروة، فقضى لي أن آخذ الخراج من الذي قضى به علي له.","grade":"حسن","chapter_ar":"باب الخراج بالضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Shafi‘i in his Musnad (1203), Abu Dawud (3508), al-Nasa’i (4502), al-Tirmidhi (1285), Ibn Majah (2442), and authenticated by Ibn Hibban (4928). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Benefit belongs to the one who bears liability","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Aisha said: The Messenger of Allah ﷺ said: “Profit goes with liability.”"]},"buhuth":{"en":["The meaning of the hadith is that if the sold item is something that produces yield or benefit, then the owner of the principal asset — the one who bears its liability — is entitled to its revenue because he bears the risk of the principal. So if a man buys land and uses it, or livestock and it produces offspring, or an animal and he rides it, or a slave and he employs him, then later finds a defect in it, he may return the principal item, and nothing is due from him for the benefit he enjoyed. That is because if it had perished during the period between the contract and rescission, it would have been under the liability of the buyer, so the yield rightly belongs to him. This was explained by al-Khattabi."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الشافعي في مسنده (1203)، وأبو داود (3508)، والنسائي (4502)، والترمذي (1285)، وابن ماجه (2442)، وصححه ابن حبان (4928)، قال الترمذي: حسن صحيح."},{"num":5478,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ، عَنْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا اخْتَلَفَ الْبَيِّعَانِ، وَلَيْسَ بَيْنَهُمَا بَيِّنَةٌ فَهُوَ مَا يَقُولُ رَبُّ السِّلْعَةِ، أَوْ يَتَتَارَكَانِ."],"takhrij":"حسن: رواه أبو داود (3511)، والنسائي (4652)، والحاكم (2293)، والبيهقي (5/332) كلهم من طريق أبي عميس، عن عبد الرحمن بن قيس بن محمد بن الأشعث، عن أبيه، عن جده أن عبد الله بن مسعود باع للأشعث بن قيس رقيقا من رقيق الخمس بعشرين ألف درهم، فأرسل عبد الله إليه في ثمنهم، فقال: إنما أخذتهم بعشرة آلاف، فقال عبدالله : إن شئت حدثتك بحديث سمعته من رسول الله صلى الله عليه وسلم، سمعته يقول. فذكر الحديث.","grade":"حسن","chapter_ar":"باب البيعان يختلفان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3511), al-Nasa’i (4652), al-Hakim (2/45), and al-Bayhaqi (5/332).","chapter_en":"When the seller and buyer disagree","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":33,"content":{"translation":{"en":["Abdullah ibn Mas‘ud narrated from the Messenger of Allah ﷺ that he said: “If the two parties in a sale disagree, and neither has evidence, then the statement is according to the owner of the merchandise, or they cancel the sale.”"]},"buhuth":{"en":["The apparent meaning of the hadith indicates that if the seller and buyer disagree regarding a matter related to the contract, then the seller’s statement is accepted, or the buyer is given the choice between taking the item at the price claimed by the seller or leaving it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3511)، والنسائي (4652)، والحاكم (2293)، والبيهقي (5/332)."},{"num":5479,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَيُّمَا امْرَأَةٍ زَوَّجَهَا وَلِيَّانِ فَهِيَ لِلأَوَّلِ مِنْهُمَا. وَمَنْ بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلأَوَّلِ مِنْهُمَا."],"takhrij":"صحيح: رواه الترمذي (1110) عن قتيبة، حدثنا غندر، حدثنا سعيد بن أبي عروبة، عن قتادة، عن الحسن، عن سمرة بن جندب. فذكره.","grade":"صحيح","chapter_ar":"باب إذا باع المجيزان فهو للأول","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1110), who said: A Hasan hadith, and by Ahmad (20085) and Ibn Majah (2190).","chapter_en":"If something is sold twice, it belongs to the first purchaser","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":37,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Messenger of Allah ﷺ said: “Any woman whom two guardians marry off, she belongs to the first of the two. And whoever sells something to two men, it belongs to the first of them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1110) قال الترمذي: حديث حسن. وأحمد (20085)، وابن ماجه (2190)."},{"num":5480,"demo":false,"sanad":"","matn":["عن أبي بكر -في قصة الهجرة- أنه رضي الله عنه مرَّ على راعي غنم يسوق غنمه إلى الصخرة، فسأله: لمن أنت يا غلام؟ قال: لرجل من قريش سماه، فعرفه، فقال: هل في غنمك لبن؟ قال: نعم. فقال: هل أنت حالب لنا؟ قال: نعم. فحلب له، فأتى به رسول الله صلى الله عليه وسلم، فشرب منه."],"takhrij":"صحيح: رواه البخاري في الفضائل (3652) عن عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، عن البراء، عن أبي بكر في أثناء قصة الهجرة.","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3652).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Abu Bakr, in the story of the migration, passed by a shepherd driving his sheep toward the rock. He asked: Whose servant are you, boy? He said: I belong to a man from Quraysh, naming him, and Abu Bakr recognized him. He said: Is there milk among your sheep? He said: Yes. He said: Will you milk for us? He said: Yes. So he milked for him and brought it to the Messenger of Allah ﷺ, and he drank from it."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3652)."},{"num":5481,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أَتَى أَحَدُكُمْ عَلَى مَاشِيَةٍ، فَإِنْ كَانَ فِيهَا صَاحِبُهَا فَلْيَسْتَأْذِنْهُ، فَإِنْ أَذِنَ لَهُ فَلْيَحْتَلِبْ وَلْيَشْرَبْ. وَلاَ يَحْمِلْ وَإِنْ لَمْ يَكُنْ فِيهَا أَحَدٌ فَلْيُصَوِّتْ ثَلاَثًا فَإِنْ أَجَابَهُ أَحَدٌ فَلْيَسْتَأْذِنْهُ، فَإِنْ لَمْ يُجِبْهُ أَحَدٌ فَلْيَحْتَلِبْ وَلْيَشْرَبْ، وَلاَ يَحْمِلْ."],"takhrij":"صحيح: رواه أبو داود (2619)، والترمذي (1296) كلاهما من حديث عبد الأعلى، عن سعيد، عن قتادة، عن الحسن، عـن سمرة بن جندب. فذكره.","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2619), and al-Tirmidhi (1296), who said: Hasan Gharib.","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “If one of you comes upon livestock, and its owner is present, then let him seek his permission. If he permits him, let him milk and drink. If no one is there, then let him call out three times. If someone answers him, let him seek permission. If no one answers him, let him milk and drink, but he must not carry any away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2619)، والترمذي (1296) وقال الترمذي: حسن غريب."},{"num":5482,"demo":false,"sanad":"","matn":["عَنْ عَبَّادِ بْنِ شُرَحْبِيلَ، قَالَ: أَصَابَتْنِي سَنَةٌ، فَدَخَلْتُ حَائِطًا مِنْ حِيطَانِ الْمَدِينَةِ، فَفَرَكْتُ سُنْبُلاً، فَأَكَلْتُ، وَحَمَلْتُ فِي ثَوْبِي، فَجَاءَ صَاحِبُهُ، فَضَرَبَنِي، وَأَخَذَ ثَوْبِي، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ: مَا عَلَّمْتَ إِذْ كَانَ جَاهِلاً، وَلاَ أَطْعَمْتَ إِذْ كَانَ جَائِعًا. أَوْ قَالَ: سَاغِبًا. وَأَمَرَهُ فَرَدَّ عَلَىَّ ثَوْبِي، وَأَعْطَانِي وَسْقًا، أَوْ نِصْفَ وَسْقٍ مِنْ طَعَامٍ."],"takhrij":"صحيح: رواه أبو داود (2630)، والنسائي (5409)، وابن ماجه (2298)، وأحمد (17521)، وصحّحه الحاكم (4/133) كلهم من طريق أبي بشر جعفر بن إياس أبي وحشية قال: سمعت عباد بن شرحبيل. فذكره.","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2630), al-Nasa’i (5409), Ibn Majah (2298), and Ahmad (17521).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["‘Abbad ibn Sharhabil said: A year of hardship struck me, so I entered one of the gardens of Madinah and rubbed an ear of grain, ate from it, and carried some in my garment. Then the owner came, struck me, and took my garment. So I went to the Messenger of Allah ﷺ, and he said to him: “You neither taught him when he was ignorant, nor fed him when he was hungry” — or he said — “starving.” He ordered him to return my garment to me, and he gave me a wasq, or half a wasq, of food."]},"buhuth":{"en":["The word “saghiban” means hungry."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2630)، والنسائي (5409)، وابن ماجه (2298)، وأحمد (17521)."},{"num":5483,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أَتَيْتَ عَلَى رَاعٍ فَنَادِهِ ثَلاَثَ مِرَارٍ فَإِنْ أَجَابَكَ وَإِلاَّ فَاشْرَبْ فِي غَيْرِ أَنْ تُفْسِدَ، وَإِذَا أَتَيْتَ عَلَى حَائِطِ بُسْتَانٍ فَنَادِ صَاحِبَ الْبُسْتَانِ ثَلاَثَ مَرَّاتٍ، فَإِنْ أَجَابَكَ وَإِلاَّ فَكُلْ فِي أَنْ لاَ تُفْسِدَ."],"takhrij":"صحيح: رواه ابن ماجه (2300) –واللفظ له-، وأحمد (11159)، وصحّحه ابن حبان (5281)، والحاكم (7180) كلهم من طريق يزيد بن هارون قال: أنبأنا الجريري، عن أبي نضرة، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2300), and this is his wording; also by Aḥmad (11159), and authenticated by Ibn Ḥibbān (5281).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Prophet ﷺ said: “If you come upon a shepherd, call out three times. If he answers you, then proceed accordingly; otherwise, drink without causing damage. And if you come upon a walled garden, call its owner three times. If he answers you, then proceed accordingly; otherwise, eat without causing damage.”"]},"buhuth":{"en":["They additionally narrated:","“Hospitality is for three days, and whatever exceeds that is charity.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2300) واللفظ له، وأحمد (11159)، وصححه ابن حبان (5281)."},{"num":5484,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ، فَقَالَ: مَنْ أَصَابَ مِنْهُ مِنْ ذِي حَاجَةٍ غَيْرَ مُتَّخِذٍ خُبْنَةً فَلاَ شَىْءَ عَلَيْهِ."],"takhrij":"حسن: رواه أبو داود (1710)، والنسائي (4958)، والترمذي (1289) كلهم عن قتيبة، حدثنا الليث، عن ابن عجلان، عن عمرو بن شعيب بإسناده. واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1710), al-Nasa’i (4958), and al-Tirmidhi (1289), who graded it Hasan. The wording is that of al-Tirmidhi.","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, narrated that the Messenger of Allah ﷺ was asked about hanging dates, and he said: “Whoever takes from them out of need, without gathering any into his garment, then there is nothing against him.”"]},"buhuth":{"en":["The word “khubnah” means that he should not put anything into his garment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1710)، والنسائي (4958)، والترمذي (1289) وحسنه. واللفظ للترمذي."},{"num":5485,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ امْرِئٍ بِغَيْرِ إِذْنِهِ، أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ فَتُكْسَرَ خِزَانَتُهُ، فَيُنْتَقَلَ طَعَامُهُ، فَإِنَّمَا تَخْزُنُ لَهُمْ ضُرُوعُ مَوَاشِيهِمْ أَطْعِمَاتِهِمْ، فَلاَ يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلاَّ بِإِذْنِهِ."],"takhrij":"متفق عليه: رواه مـالك في الاستئذان (17) عن نافـع، عـن عبد الله بن عمر قال: فذكره. ورواه البخاري في اللقطة (2435)، ومسلم في اللقطة (1726) كلاهما من حديث مالك به.","grade":"متفق عليه","chapter_ar":"باب النهي عن حلب ماشية الغير بغير إذنه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (17), al-Bukhārī (2435), and Muslim (1726).","chapter_en":"The prohibition of milking another person’s livestock without permission","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":39,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported that the Messenger of Allah ﷺ said: “None of you should milk another person’s livestock without his permission. Would one of you like someone to come to his storeroom, break open his store, and carry away his food? The udders of their livestock are what store their food for them. Therefore, no one should milk another person’s livestock except with his permission.”"]}},"tuhfa":{},"full":1,"rep":[5957],"tks":"متفق عليه: رواه مالك (17)، والبخاري (2435)، ومسلم (1726)."},{"num":5486,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هَانِئٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: اتَّخِذِي غَنَمًا؛ فَإِنَّ فِيهَا بَرَكَةً."],"takhrij":"صحيح: رواه ابن ماجه (2304)، وأحمد (27381) كلاهما من حديث هشام بن عروة، عن أبيه عروة بن الزبير، عن أم هانئ فذكرته.","grade":"صحيح","chapter_ar":"باب استحباب التجارة بالغنم وغيرها من المواشي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2304) and Ahmad (23781).","chapter_en":"Recommendation to trade in sheep and other livestock","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":40,"content":{"translation":{"en":["Umm Hani’ narrated that the Prophet ﷺ said to her: “Keep sheep, for there is blessing in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2304)، وأحمد (27381)."},{"num":5487,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ الْبَارِقِيِّ، يَرْفَعُهُ قَالَ: الإِبِلُ عِزٌّ لأَهْلِهَا، وَالْغَنَمُ بَرَكَةٌ، وَالْخَيْرُ مَعْقُودٌ فِي نَوَاصِي الْخَيْلِ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه ابن ماجه (2305) عن محمد بن عبد الله بن نمير قال: حدثنا عبد الله بن إدريس، عن حصين، عن عامر، عن عروة البارقي فذكره.","grade":"صحيح","chapter_ar":"باب استحباب التجارة بالغنم وغيرها من المواشي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2305), Ibn Abi ‘Asim in al-Ahad wa al-Mathani (4/362), and al-Tabarani in al-Kabir (17/156).","chapter_en":"Recommendation to trade in sheep and other livestock","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":40,"content":{"translation":{"en":["‘Urwah al-Bariqi narrated it as a raised report: “Camels are honor for their people, sheep are blessing, and goodness is tied to the forelocks of horses until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2305)، وابن أبي عاصم في الآحاد والمثاني (4/362)، والطبراني في الكبير (17/156)."},{"num":5488,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَوْبَانِ قِطْرِيَّانِ غَلِيظَانِ، فَكَانَ إِذَا قَعَدَ فَعَرِقَ ثَقُلاَ عَلَيْهِ، فَقَدِمَ بَزٌّ مِنَ الشَّامِ لِفُلاَنٍ الْيَهُودِيِّ. فَقُلْتُ: لَوْ بَعَثْتَ إِلَيْهِ، فَاشْتَرَيْتَ مِنْهُ ثَوْبَيْنِ إِلَى الْمَيْسَرَةِ. فَأَرْسَلَ إِلَيْهِ، فَقَالَ: قَدْ عَلِمْتُ مَا يُرِيدُ، إِنَّمَا يُرِيدُ أَنْ يَذْهَبَ بِمَالِي أَوْ بِدَرَاهِمِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَذَبَ، قَدْ عَلِمَ أَنِّي مِنْ أَتْقَاهُمْ لِلَّهِ وَآدَاهُمْ لِلأَمَانَةِ."],"takhrij":"صحيح: رواه الترمذي (1213)، والنسائي (4628)، وصحّحه الحاكم (2/23-24)، كلهم من حديث يزيد بن زريع، عن عمارة بن أبي حفصة، عن عكرمة، عن عائشة فذكرته. قال الترمذي: \"حسن غريب صحيح\".","grade":"صحيح","chapter_ar":"باب الشراء إلى أجل معلوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1213), al-Nasa’i (4628), and authenticated by al-Hakim (2/23–24).","chapter_en":"Buying on deferred payment to a known term","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":41,"content":{"translation":{"en":["Aisha said: The Messenger of Allah ﷺ had two thick Qatari garments, and when he sat and perspired, they weighed heavily on him. Then some cloth from Syria arrived for a certain Jewish man, so I said: If only you would send to him and buy from him two garments on deferred payment until ease comes. So he sent to him, and the man said: I know what he wants; he only wants to take away my property — or my money. So the Messenger of Allah ﷺ said: “He has lied. He certainly knows that I am the most Allah-fearing of them and the most faithful in fulfilling trusts.”"]},"buhuth":{"en":["The phrase “until ease comes” means to a known term at which payment becomes manageable. Otherwise, an unknown term invalidates the sale."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1213)، والنسائي (4628)، وصححه الحاكم (2/23-24)."},{"num":5489,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ:كَانَ بِالْمَدِينَةِ فَزَعٌ، فَاسْتَعَارَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَسًا مِنْ أَبِي طَلْحَةَ يُقَالُ لَهُ: الْمَنْدُوبُ، فَرَكِبَ، فَلَمَّا رَجَعَ قَالَ: مَا رَأَيْنَا مِنْ شَيْءٍ، وإنا وَجَدْنَاهُ لَبَحْرًا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2627)، ومسلم في الرؤيا (2307) كلاهما من حديث شعبة، عن قتادة قال: سمعت أنسا يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2627) and Muslim (2307).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Anas ibn Malik said: There was an alarm in Madinah, so the Prophet ﷺ borrowed a horse from Abu Talhah called al-Mandub and rode it. When he returned, he said: “We did not see anything, and we found it to be like a sea,” meaning very swift."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2627)، ومسلم (2307)."},{"num":5490,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْعَارِيَةُ مُؤَدَّاةٌ، وَالْمِنْحَةُ مَرْدُودَةٌ."],"takhrij":"حسن: رواه ابن ماجه (2399) عن هشام بن عمار وعبدالرحمن بن إبراهيم الدمشقيان قالا: حدثنا محمد بن شعيب، عن عبدالرحمن بن يزيد، عن سعيد بن أبي سعيد، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2399).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Anas said: I heard the Messenger of Allah ﷺ say: “A borrowed item is to be returned, and a manihah (an animal lent for its milk) is to be returned.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2399)."},{"num":5491,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْعَارِيَةُ مؤدّاةٌ، والمِنْحَةُ مَرْدُودَةٌ."],"takhrij":"حسن: رواه ابن ماجه (2398)، والترمذي (1265)، وأبو داود (3565)، وأحمد (22294) كلهم من حديث إسماعيل بن عياش قال: حدثني شرحبيل بن مسلم قال: سمعت أبا أمامة فذكره. واللفظ لابن ماجه.","grade":"حسن","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2398), al-Tirmidhi (1265), Abu Dawud (3565), and Ahmad (22294). The wording is that of Ibn Majah.","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ say: “A borrowed item is to be returned, and a manihah (an animal lent for its milk) is to be returned.”"]},"buhuth":{"en":["The wording in Abu Dawud is: “Allah, Mighty and Majestic, has given every person with a right his due right, so there is no bequest for an heir, and a woman must not spend anything from her house except with her husband’s permission.” It was said: O Messenger of Allah ﷺ, not even food? He said: “That is the best of our wealth.” Then he said: “A borrowed item is to be returned, a manihah (an animal lent for its milk) is to be returned, a debt is to be paid, and the guarantor is liable.” Al-Tirmidhi said: Hasan Gharib."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2398)، والترمذي (1265)، وأبو داود (3565)، وأحمد (22294) واللفظ لابن ماجه."},{"num":5492,"demo":false,"sanad":"","matn":["عنْ سَمُرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلَى الْيَدِ مَا أَخَذَتْ حَتَّى تُؤَدِّيَ."],"takhrij":"صحيح: رواه أبو داود (3561)، والترمذي (1266)، وابن ماجه (2400)، والحاكم (2302)، والبيهقي (11482)، والقضاعي في مسند الشهاب (1/189) كلهم من حديث الحسن، عن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3561), and al-Tirmidhi (1266), who said: Hasan Sahih.","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “The hand is responsible for what it takes until it returns it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3561)، والترمذي (1266)، قال الترمذي: حسن صحيح."},{"num":5493,"demo":false,"sanad":"","matn":["عَنْ يَعْلَى بْنِ أُمَيَّةَ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَتَتْكَ رُسُلِي فَأَعْطِهِمْ ثَلاَثِينَ دِرْعًا، وَثَلاَثِينَ بَعِيرًا. قَالَ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَعَارِيَةً مَضْمُونَةً، أَوْ عَارِيَةً مُؤَدَّاةً؟ قَالَ: بَلْ عَارِيَةً مُؤَدَّاةً."],"takhrij":"صحيح: رواه أبو داود (3566)، وأحمد (17950)، والدارقطني (3/39)، وصحّحه ابن حبان (4720) كلهم من حديث همام، عن قتادة، عن عطاء، عن صفوان بن يعلى بن أمية، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3566), Ahmad (17950), al-Daraqutni (3/39), and authenticated by Ibn Hibban (4720).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Ya‘la ibn Umayyah said: The Messenger of Allah ﷺ said to me: “When my messengers come to you, give them thirty coats of armor and thirty camels.” I said: O Messenger of Allah ﷺ, is it a guaranteed loan or a borrowed item to be returned? He said: “Rather, it is a borrowed item to be returned.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3566)، وأحمد (17950)، والدارقطني (3/39)، وصححه ابن حبان (4720)."},{"num":5494,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَارَ إِلَى حُنَيْنٍ، فَذَكَرَ الْحَدِيثَ. وَفِيهِ: ثُمَّ بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى صَفْوَانَ بْنِ أُمَيَّةَ فَسَأَلَهُ أَدْرَاعًا عِنْدَهُ، مِائَةَ دِرْعٍ وَمَا يُصْلِحُهَا مِنْ عُدَّتِهَا، فَقَالَ: أَغَصْبًا يَا مُحَمَّدُ؟ فَقَالَ: بَلْ عَارِيَةٌ مَضْمُونَةٌ حَتَّى نُؤَدِّيَهَا عَلَيْكَ."],"takhrij":"حسن: رواه الحاكم (4369)، وعنه البيهقي (11477) من طريق ابن إسحاق قال: حدثني عاصم بن عمر بن قتادة، عن عبد الرحمن بن جابر، عن أبيه جابر بن عبد الله فذكره. قال الحاكم: \"صحيح الإسناد\".","grade":"حسن","chapter_ar":"باب ما جاء في تضمين العارية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (3/48–49) and al-Bayhaqi (6/89).","chapter_en":"What has come regarding liability for borrowed items","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":43,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Messenger of Allah ﷺ marched to Hunayn. In the hadith it states: Then the Messenger of Allah ﷺ sent to Safwan ibn Umayyah and asked him for one hundred coats of armor that he had, along with their equipment. Safwan said: Is this by force, O Muhammad? He said: “Rather, it is a guaranteed loan until we return it to you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7938,9213],"tks":"حسن: رواه الحاكم (4369)، والبيهقي (11477)."},{"num":5495,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ تَغْلِبَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يَفْشُوَ الْمَالُ وَيَكْثُرَ، وَتَفْشُوَ التِّجَارَةُ، وَيَظْهَرَ الْعِلْمُ، وَيَبِيعَ الرَّجُلُ الْبَيْعَ، فَيَقُولَ: لاَ حَتَّى أَسْتَأْمِرَ تَاجِرَ بَنِي فُلاَنٍ، وَيُلْتَمَسَ فِي الْحَىِّ الْعَظِيمِ الْكَاتِبُ فَلاَ يُوجَدُ."],"takhrij":"صحيح: رواه النسائي (4456)، والحاكم (2/7)، والخطابي في غريب الحديث (1/405) كلهم من حديث وهب بن جرير قال: حدثني أبي، عن يونس، عن الحسن، عن عمرو بن تغلب فذكره. واللفظ للنسائي.","grade":"صحيح","chapter_ar":"باب من أشراط الساعة كثرة المال وفشو التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4456) and al-Hakim (2/7). The wording is that of al-Nasa’i.","chapter_en":"Among the signs of the Hour are abundance of wealth and the spread of trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["‘Amr ibn Taghlib said: The Messenger of Allah ﷺ said: “Among the signs of the Hour are that wealth will become widespread and abundant, trade will become widespread, knowledge will appear, a man will make a sale and then say: No, not until I consult the merchant of Banu so-and-so, and in a large tribe a scribe will be sought but not found.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15928],"tks":"صحيح: رواه النسائي (4456)، والحاكم (2/7). واللفظ للنسائي."},{"num":5496,"demo":false,"sanad":"","matn":["عَنْ طَارِقٍ قَالَ: كُنَّا عِنْدَ عَبْدِ اللَّهِ جُلُوسًا، فَجَاءَ آذِنُهُ، فَقَالَ: قَدْ قَامَتِ الصَّلاَةُ، فَقَامَ وَقُمْنَا مَعَهُ، فَدَخَلْنَا الْمَسْجِدَ، فَرَأَى النَّاسَ رُكُوعًا فِي مُقَدَّمِ الْمَسْجِدِ، فَكَبَّرَ وَرَكَعَ، وَمَشَيْنَا وَفَعَلْنَا مِثْلَ مَا فَعَلَ، فَمَرَّ رَجُلٌ مُسْرِعٌ فَقَالَ: عَلَيْكُمُ السَّلاَمُ يَا أَبَا عَبْدِ الرَّحْمَنِ، فَقَالَ: صَدَقَ اللَّهُ، وَبَلَّغَ رَسُولُهُ، فَلَمَّا صَلَّيْنَا رَجَعَ، فَوَلَجَ عَلَى أَهْلِهِ، وَجَلَسْنَا فِي مَكَانِنَا نَنْتَظِرُهُ حَتَّى يَخْرُجَ، فَقَالَ بَعْضُنَا لِبَعْضٍ: أَيُّكُمْ يَسْأَلُهُ؟ قَالَ طَارِقٌ: أَنَا أَسْأَلُهُ، فَسَأَلَهُ، فَقَالَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَ يَدَيِ السَّاعَةِ: تَسْلِيمُ الْخَاصَّةِ، وَفُشُوُّ التِّجَارَةِ حَتَّى تُعِينَ الْمَرْأَةُ زَوْجَهَا عَلَى التِّجَارَةِ، وَقَطْعُ الأَرْحَامِ، وَفُشُوُّ الْقَلَمِ، وَظُهُورُ الشَّهَادَةِ بِالزُّورِ، وَكِتْمَانُ شَهَادَةِ الْحَقِّ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (1049)، وأحمد (3982)، والطحاوي في مشكله (1590)، والحاكم (8378) كلهم من طريق بشير بن سلمان، عن سيار أبي الحكم، عن طارق بن شهاب فذكره.","grade":"حسن","chapter_ar":"باب من أشراط الساعة كثرة المال وفشو التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhari in al-Adab al-Mufrad (1049), Ahmad (3982), and al-Tahawi in Mushkil al-Athar (1590).","chapter_en":"Among the signs of the Hour are abundance of wealth and the spread of trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Tariq ibn Shihab said: We were sitting with Abdullah when his caller came and said: The prayer has begun. So he stood, and we stood with him. We entered the mosque, and he saw the people already bowing in the front of the mosque, so he said the opening takbir and bowed, and we walked and did as he did. Then a man passed by hurriedly and said: Peace be upon you, O Abu Abd al-Rahman. He replied: Allah has spoken the truth, and His Messenger conveyed it. When we had prayed, he returned and entered upon his family, and we sat in our place waiting for him to come out. Some of us said to one another: Which of you will ask him? Tariq said: I will ask him. So he asked him, and he said: From the Prophet ﷺ: “Before the Hour there will be greetings given only to select people, trade will become widespread to the point that a woman helps her husband in trade, family ties will be cut, writing will become widespread, false testimony will appear, and true testimony will be concealed.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15927],"tks":"حسن: رواه البخاري في الأدب المفرد (1049)، وأحمد (3982)، والطحاوي في مشكله (1590)."},{"num":5497,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَهُمْ يُسْلِفُونَ فِي الثِّمَارِ السَّنَةَ وَالسَّنَتَيْنِ، فَقَالَ: مَنْ أَسْلَفَ فِي تَمْرٍ فَلْيُسْلِفْ فِي كَيْلٍ مَعْلُومٍ، وَوَزْنٍ مَعْلُومٍ، إِلَى أَجَلٍ مَعْلُومٍ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2240)، ومسلم في المساقاة (1604: 127) كلاهما من طريق سفيان بن عيينة، أخبرنا ابن أبي نجيح، عن عبد الله بن كثير، عن أبي المنهال، عن ابن عباس فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2240) and Muslim (1604:127). The wording is that of Muslim.","chapter_en":"Forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ came to Madinah while they used to pay in advance for fruits one year and two years ahead. So he said: “Whoever pays in advance for fruit, let him pay in advance for a known measure, a known weight, and a known term.”"]},"buhuth":{"en":["The word salaf is the Hijazi term, while salam is the Iraqi term. In transactions, salaf has two meanings:","The first is a loan in which the lender takes no benefit, and the borrower must return it as he received it.","The second is the well-known forward sale, which is paying present money in exchange for a specified item owed in liability. The expressions saliftu, aslaftu, and aslamtu are all used with the same meaning.","The phrase “for fruit” appears in most of the manuscripts in this broad form. Al-Nawawi said this wording is more general.","The hadith proves the permissibility of forward sale in food, clothing, and other kinds of merchandise whose type and description are known."]},"intro":{"ar":["قال اللّٰه تعالى: { يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ } [البقرة: ٢٨٢].","قال ابن عباس: أشهد أن السلف المضمون إلى أجل مسمى قد أحله اللّٰه في كتابه، وأذن فيه. ثم قرأ هذه الآية. أخرجه عبد الرزاق (١٤٠٦٤)."],"en":["Allah the Exalted said: “O you who believe, when you contract a debt for a fixed term, write it down.” [Al-Baqarah: 282]","Ibn Abbas said: I bear witness that guaranteed forward sale to a fixed term has been made lawful by Allah in His Book and permitted by Him. Then he recited this verse. Narrated by Abd al-Razzaq (14064)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2240)، ومسلم (1604: 127). واللفظ لمسلم."},{"num":5498,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْبَخْتَرِيِّ، قَالَ: سَأَلْتُ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا عَنِ السَّلَمِ، فِي النَّخْلِ، فَقَالَ: نُهِيَ عَنْ بَيْعِ النَّخْلِ، حَتَّى يَصْلُحَ، وَعَنْ بَيْعِ الْوَرِقِ، نَسَاءً بِنَاجِزٍ. وَسَأَلْتُ ابْنَ عَبَّاسٍ عَنِ السَّلَمِ، فِي النَّخْلِ، فَقَالَ نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ النَّخْلِ حَتَّى يُؤْكَلَ مِنْهُ، أَوْ يَأْكُلَ مِنْهُ، وَحَتَّى يُوزَنَ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2247-2248)، ومسلم في البيوع (1537) كلاهما من طـريق شعبة، عن عمرو، عـن أبي البختري قال فذكره. واللفظ للبخاري، وعند مسلم \"عن بيع\" بدل \"عن السلم\".","grade":"متفق عليه","chapter_ar":"باب السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2247–2248) and Muslim (1537). The wording is that of al-Bukhari.","chapter_en":"Forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu al-Bakhtari said: I asked Ibn Umar, may Allah be pleased with them both, about forward sale involving date-palms, and he said: He forbade selling date-palms until they become sound, and he forbade selling silver for gold on credit. And I asked Ibn Abbas about forward sale involving date-palms, and he said: The Prophet ﷺ forbade selling date-palms until one can eat from them and until they are weighed."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2248-2247)، ومسلم (1537). واللفظ للبخاري."},{"num":5499,"demo":false,"sanad":"","matn":["عن محمد بن أَبِي المجالد قَالَ: بَعَثَنِي عَبْدُ اللَّهِ بْنُ شَدَّادٍ، وَأَبُو بُرْدَةَ إِلَى عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى، رَضِيَ اللَّهُ عَنْهُمَا فَقَالاَ: سَلْهُ هَلْ كَانَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسْلِفُونَ فِي الْحِنْطَةِ؟ قَالَ عَبْدُ اللَّهِ كُنَّا نُسْلِفُ نَبِيطَ أَهْلِ الشَّأْمِ فِي الْحِنْطَةِ، وَالشَّعِيرِ، وَالزَّيْتِ، فِي كَيْلٍ مَعْلُومٍ، إِلَى أَجَلٍ مَعْلُومٍ. قُلْتُ: إِلَى مَنْ كَانَ أَصْلُهُ عِنْدَهُ؟ قَالَ: مَا كُنَّا نَسْأَلُهُمْ عَنْ ذَلِكَ. ثُمَّ بَعَثَانِي إِلَى عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى، فَسَأَلْتُهُ، فَقَالَ: كَانَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسْلِفُونَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ نَسْأَلْهُمْ أَلَهُمْ حَرْثٌ أَمْ لاَ."],"takhrij":"صحيح: رواه البخاري في السلم (2244-2245) عن موسى بن إسماعيل، حدثنا عبدالواحد، حدثنا الشيباني، حدثنا محمد بن أبي المجالد فذكره.","grade":"صحيح","chapter_ar":"باب السلم إلى من ليس عنده أصل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2244–2245).","chapter_en":"Forward sale to one who does not presently possess the source goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Muhammad ibn Abi al-Mujalid said: Abdullah ibn Shaddad and Abu Burdah sent me to Abdullah ibn Abi Awfa and said: Ask him whether the Companions of the Prophet ﷺ used to engage in forward sale for wheat during the lifetime of the Prophet ﷺ. Abdullah said: We used to make forward contracts with the Nabateans of Syria for wheat, barley, and oil in a known measure to a known term. I said: With people who had the goods with them? He said: We did not ask them about that. Then they sent me to Abd al-Rahman ibn Abza, and I asked him, and he said: The Companions of the Prophet ﷺ used to engage in forward sale during the time of the Prophet ﷺ, and we did not ask them whether they had crops or not."]},"buhuth":{"en":["In another narration in al-Bukhari: “During the time of the Prophet ﷺ, Abu Bakr, and Umar, for wheat, barley, raisins, and dates.” In Musnad Ahmad: “Even when it was not with them, or when we did not see it with them.”","From the phrase “We did not ask them about that,” it is understood that forward sale is permissible in general merchandise, whether agricultural or otherwise, so long as the required conditions are met, such as clear description, type, term, and similar details, in order to prevent dispute.","The word Nabit is also said as Nabat. They were a people of Arab origin who mixed with the non-Arabs and the Romans, so their lineages became mixed and their language became corrupted. Those who mixed with the Romans settled in the rural lands of Syria, and they became farmers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2245-2244)."},{"num":5500,"demo":false,"sanad":"","matn":["عن الأعمش قَالَ: تَذَاكَرْنَا عِنْدَ إِبْرَاهِيمَ الرَّهْنَ فِي السَّلَفِ، فَقَالَ: حَدَّثَنِي الأَسْوَدُ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اشْتَرَى مِنْ يَهُودِيٍّ طَعَامًا إِلَى أَجَلٍ مَعْلُومٍ، وَارْتَهَنَ مِنْهُ دِرْعًا مِنْ حَدِيدٍ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2252)، ومسلم في المساقاة (1603: 126) من طريق عبدالواحد بن زياد، حدثنا الأعمش قال فذكره.","grade":"متفق عليه","chapter_ar":"باب الرهن في السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2252) and Muslim (1603:126). The wording is al-Bukhari’s.","chapter_en":"Collateral in a forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Al-A‘mash said: We were discussing collateral in forward transactions in the presence of Ibrahim, and he said: Al-Aswad narrated to me from Aisha that the Prophet ﷺ bought food from a Jew on a fixed term and gave him a coat of armor made of iron as collateral."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2252)، ومسلم (1603: 126). واللفظ للبخاري."},{"num":5501,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ:  كَانَ أَهْلُ الْجَاهِلِيَّةِ يَتَبَايَعُونَ لَحْمَ الْجَزُورِ إِلَى حَبَلِ الْحَبَلَةِ، وَحَبَلُ الْحَبَلَةِ: أَنْ تُنْتَجَ النَّاقَةُ، ثُمَّ تَحْمِلَ الَّتِي نُتِجَتْ، فَنَهَاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في السلم (2256) من طريق جويرية، ومسلم في البيوع (1514: 6) من طريق عبيدالله، كلاهما عن نافع، عن ابن عمر قال فذكره. واللفظ لمسلم. ولفظ البخاري نحوه، وفيه التصريح بأن التفسير من نافع.","grade":"متفق عليه","chapter_ar":"باب عدم جواز السلم إلى أجل غير معلوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2256) and Muslim (1514:6). The wording is Muslim’s.","chapter_en":"The impermissibility of a forward sale with an unknown term","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar said: The people of the pre-Islamic period used to trade camel meat until “the pregnancy of the offspring’s offspring.” And “the pregnancy of the offspring’s offspring” means that the she-camel gives birth, then the one born from her becomes pregnant. So the Messenger of Allah ﷺ forbade that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2256)، ومسلم (1514: 6). واللفظ لمسلم."},{"num":5502,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالشُّفْعَةِ فِي كُلِّ مَا لَمْ يُقْسَمْ، فَإِذَا وَقَعَتِ الْحُدُودُ، وَصُرِّفَتِ الطُّرُقُ فَلاَ شُفْعَةَ."],"takhrij":"صحيح: رواه البخاري في الشفعة (2257) عن مسدد، حدثنا عبدالواحد، حدثنا معمر، عن الزهري، عن أبي سلمة بن عبد الرحمن، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2257).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Prophet ﷺ ruled that preemption applies in everything that has not been divided. But when the boundaries are fixed and the roads are laid out, then there is no preemption."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2257)."},{"num":5503,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ كَانَ لَهُ شَرِيكٌ فِي رَبْعَةٍ، أَوْ نَخْلٍ، فَلَيْسَ لَهُ أَنْ يَبِيعَ حَتَّى يُؤْذِنَ شَرِيكَهُ، فَإِنْ رَضِيَ أَخَذَ، وَإِنْ كَرِهَ تَرَكَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1608) من طرق عن زهير أبي خيثمة، عن أبي الزبير، عن جابر. وزهير هو ابن معاوية الجعفي أبو خيثمة.","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Whoever has a partner in a dwelling, or in date-palms, then he has no right to sell until he informs his partner. If he is pleased, he may take it, and if he dislikes it, he may leave it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1608)."},{"num":5504,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الشُّفْعَةُ فِي كُلِّ شِرْكٍ، فِي أَرْضٍ، أَوْ رَبْعٍ، أَوْ حَائِطٍ، لَا يَصْلُحُ أَنْ يَبِيعَ حَتَّى يَعْرِضَ عَلَى شَرِيكِهِ، فَيَأْخُذَ، أَوْ يَدَعَ، فَإِنْ أَبَى فَشَرِيكُهُ أَحَقُّ بِهِ حَتَّى يُؤْذِنَهُ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1608: 135) عـن أبي الطاهر، أخبرنا ابن وهب، عن ابن جريج، أن أبا الزبير أخبره أنه سمع جابرا يقول فذكره.","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608:135). In another narration with him: “The Messenger of Allah ﷺ ruled with preemption in every undivided partnership: a dwelling or a garden. It is not lawful for him to sell until he informs his partner. If he wishes, he takes it, and if he wishes, he leaves it. If he sells and did not inform him, then he is more entitled to it.”","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Preemption applies in every shared property, whether land, a dwelling, or a garden. It is not proper for one to sell until he offers it to his partner. He either takes it or leaves it. If he refuses, then his partner is more entitled to it until he informs him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1608: 135). وفي رواية عنده: (( قضى رسول الله ﷺ بالشفعة في كل شركة لم تقسم: ربعة أو حائط، لا يحل له أن يبيع حتى يؤذن شريكه، فإن شاء أخذ، وإن شاء ترك، فإذا باع ولم يؤذنه فهو أحق به ))."},{"num":5505,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَتْ لَهُ نَخْلٌ، أَوْ أَرْضٌ فَلاَ يَبِيعُهَا حَتَّى يَعْرِضَهَا عَلَى شَرِيكِهِ."],"takhrij":"صحيح: رواه النسائي (4700)، وابن ماجه (2492)، وأحمد (14292) كلهم من طريق سفيان بن عيينة، عن أبي الزبير، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4700), Ibn Majah (2492), and Ahmad (14292).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Whoever has date-palms or land, let him not sell it until he offers it to his partner.”"]},"buhuth":{"en":["Abd al-Razzaq (14403) also narrated it and added: “If he wishes, he takes it, and if he wishes, he leaves it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4700)، وابن ماجه (2492)، وأحمد (14292)."},{"num":5506,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَضَى بِالشُّفْعَةِ فِيمَا لَمْ يُقْسَمْ، فَإِذَا وَقَعَتِ الْحُدُودُ، فَلَا شُفْعَةَ."],"takhrij":"صحيح: رواه ابن ماجه (2497) عن محمد بن يحيى، وعبد الرحمن بن عمر، حدثنا أبو عاصم قال: حدثنا مالك بن أنس، عن الزهري، عن سعيد بن المسيب، وأبي سلمة بن عبد الرحمن، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2497) and Ibn Hibban in his Sahih (5185).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ ruled with preemption in what has not been divided, and when the boundaries are fixed, then there is no preemption."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2497)، وابن حبان في صحيحه (5185)."},{"num":5507,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الشَّرِيدِ، قَالَ: وَقَفْتُ عَلَى سَعْدِ بْنِ أَبِي وَقَّاصٍ، فَجَاءَ الْمِسْوَرُ بْنُ مَخْرَمَةَ، فَوَضَعَ يَدَهُ عَلَى إِحْدَى مَنْكِبَىَّ إِذْ جَاءَ أَبُو رَافِعٍ مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا سَعْدُ، ابْتَعْ مِنِّي بَيْتَىَّ فِي دَارِكَ. فَقَالَ سَعْدٌ: وَاللَّهِ مَا أَبْتَاعُهُمَا. فَقَالَ الْمِسْوَرُ: وَاللَّهِ، لَتَبْتَاعَنَّهُمَا. فَقَالَ سَعْدٌ: وَاللَّهِ لاَ أَزِيدُكَ عَلَى أَرْبَعَةِ آلاَفٍ، مُنَجَّمَةٍ أَوْ مُقَطَّعَةٍ. قَالَ أَبُو رَافِعٍ: لَقَدْ أُعْطِيتُ بِهَا خَمْسَمِائَةِ دِينَارٍ، وَلَوْلاَ أَنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْجَارُ أَحَقُّ بِسَقَبِهِ. مَا أَعْطَيْتُكَهَا بِأَرْبَعَةِ آلاَفٍ، وَأَنَا أُعْطَى بِهَا خَمْسَمِائَةِ دِينَارٍ. فَأَعْطَاهَا إِيَّاهُ."],"takhrij":"صحيح: رواه البخاري في الشفعة (2258) عن المكي بن إبراهيم، أخبرنا ابن جريج، أخبرني إبراهيم بن ميسرة، عن عمرو بن الشريد قال فذكره.","grade":"صحيح","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2258).","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Amr ibn al-Sharid said: I was standing with Sa‘d ibn Abi Waqqas when al-Miswar ibn Makhramah came and placed his hand on one of my shoulders. Then Abu Rafi‘, the freed slave of the Prophet ﷺ, came and said: O Sa‘d, buy my two houses in your courtyard from me. Sa‘d said: By Allah, I will not buy them. Al-Miswar said: By Allah, you will buy them. Sa‘d said: By Allah, I will not give you more than four thousand in installments. Abu Rafi‘ said: I was offered five hundred dinars for them, and had I not heard the Prophet ﷺ say, “The neighbor is more entitled to his adjoining property,” I would not have given them to you for four thousand while I was being offered five hundred dinars. So he gave them to him."]},"buhuth":{"en":["The wording “munajjaman or muqatta‘an” reflects uncertainty from the narrator. Both indicate payment deferred in known portions."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2258)."},{"num":5508,"demo":false,"sanad":"","matn":["عن الشريد بن سُوَيْدٍ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ، أَرْضٌ لَيْسَ فِيهَا لأَحَدٍ قِسْمٌ، وَلاَ شِرْكٌ إِلاَّ الْجِوَارُ. قَالَ: الْجَارُ أَحَقُّ بِسَقَبِهِ."],"takhrij":"حسن: رواه النسائي (4703)، وابن ماجه (2496)، وأحمد (19461) كلهم من حديث حسين المعلم، عن عمرو بن شعيب، عن عمرو بن الشريد بن سويد، عن أبيه الشريد بن سويد فذكره.","grade":"حسن","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4703), Ibn Majah (2496), and Ahmad (19461).","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Al-Sharid ibn Suwayd said: I said: O Messenger of Allah ﷺ, there is land in which no one has any share or partnership except neighboring rights. He said: “The neighbor is more entitled to his adjoining property.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4703)، وابن ماجه (2496)، وأحمد (19461)."},{"num":5509,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَارُ الدَّارِ أَحَقُّ بِدَارِ الْجَارِ أَوِ الأَرْضِ."],"takhrij":"صحيح: رواه أبو داود (3517)، والترمذي (1368)، وابن الجارود (644)، وأحمد (20088) كلهم من طريق قتادة، عن الحسن، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3517), al-Tirmidhi (1368), Ibn al-Jarud (644), and Ahmad (20088). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Samurah ibn Jundub narrated from the Prophet ﷺ that he said: “The neighbor of a house has more right to the house of his neighbor, or the land.”"]},"buhuth":{"en":["The word saqab means nearness or adjacency, and it is pronounced with either the letter sin or sad.","Al-Shafi‘i said: His statement, “The neighbor is more entitled to his adjoining property,” carries only two possible meanings: either he intended preemption for every neighbor, or he intended some neighbors and not others. Since it is established from the Messenger of Allah ﷺ that there is no preemption in property that has been divided, this indicates that preemption is for the neighboring co-owner who has not yet divided the property, not for the separate neighbor whose property is already distinct."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3517)، والترمذي (1368)، وابن الجارود (644)، وأحمد (20088)."},{"num":5510,"demo":false,"sanad":"","matn":["عن أَبِي مُوسَى الأشعري رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْخَازِنُ الأَمِينُ الَّذِي يُؤَدِّي مَا أُمِرَ بِهِ طَيِّبَةً نَفْسُهُ أَحَدُ الْمُتَصَدِّقَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الإجارة (2260)، ومسلم في الزكاة (1023) من طريق بُريد أبي بردة قال: أخبرني أبو بردة، عن أبيه أبي موسى الأشعري قال فذكره.","grade":"متفق عليه","chapter_ar":"باب استئجار الرجل الصالح الأمين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2260) and Muslim (1023).","chapter_en":"Hiring a righteous and trustworthy person","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī reported that the Prophet ﷺ said: “The trustworthy treasurer who carries out what he has been commanded to do with a willing heart is one of those who give charity.”"]},"buhuth":{"en":["Benefit: Al-Kirmānī said that the inclusion of this hadith in the chapter on hiring indicates that the keeper of another person’s wealth is like an employee of the owner of that wealth."]},"intro":{"ar":["قال الله تعالى: { قَالَتْ إِحْدَاهُمَا يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ } [القصص: ٢٦]."],"en":["Allah the Exalted said: “One of the two women said: O my father, hire him. Indeed, the best one you can hire is the strong and trustworthy one.” [Al-Qasas: 26]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2260)، ومسلم (1023)."},{"num":5511,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَعَثَ اللَّهُ نَبِيًّا إِلاَّ رَعَى الْغَنَمَ. فَقَالَ أَصْحَابُهُ: وَأَنْتَ؟ فَقَالَ: نَعَمْ، كُنْتُ أَرْعَاهَا عَلَى قَرَارِيطَ لأَهْلِ مَكَّةَ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2262) عن أحمد بن محمد المكي، حدثنا عمرو بن يحيى، عن جده (وهو سعيد بن عمرو بن سعيد بن العاص الأموي) عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الاستئجار على الرضاعة، وسقي الماء، ورعي الغنم، وغيرها من الخدمات","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2262).","chapter_en":"Hiring for breastfeeding, drawing water, shepherding sheep, and other services","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Allah did not send any prophet except that he shepherded sheep.” His companions said: Even you? He said: “Yes, I used to shepherd them for the people of Makkah for a few qirats.”"]},"intro":{"ar":["قال الله تعالى: { فَجَاءَتْهُ إِحْدَاهُمَا تَمْشِي عَلَى اسْتِحْيَاءٍ قَالَتْ إِنَّ أَبِي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا } [القصص: ٢٥].\\n\\nوقال الله تعالى: { فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ } [الطلاق: ٦].\\n\\nوقال تعالى: { فَانْطَلَقَا حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَنْ يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ فَأَقَامَهُ قَالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا } [الكهف: ٧٧]."],"en":["Allah the Exalted said: “Then one of the two women came to him, walking modestly. She said: Indeed, my father invites you so that he may reward you for having watered for us.” [Al-Qasas: 25]\\n\\nAnd Allah the Exalted said: “Then if they breastfeed for you, give them their wages.” [Al-Talaq: 6]\\n\\nAnd He said: “So they went on until, when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. Then they found there a wall about to collapse, so he restored it. He said: If you wished, you could have taken payment for it.” [Al-Kahf: 77]"]}},"tuhfa":{},"full":1,"rep":[5410],"tks":"صحيح: رواه البخاري (2262)."},{"num":5512,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ اللَّهُ تَعَالَى: ثَلاَثَةٌ أَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ: رَجُلٌ أَعْطَى بِي ثُمَّ غَدَرَ، وَرَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ، وَرَجُلٌ اسْتَأْجَرَ أَجِيرًا فَاسْتَوْفَى مِنْهُ وَلَمْ يُعْطِهِ أَجْرَهُ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2270) عن يوسف بن محمد قال: حدثني يحيى بن سليم، عن إسماعيل بن أمية، عن سعيد بن أبي سعيد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من منع الأجير أجره، والأمر بتعجيل إعطائه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2270).","chapter_en":"Warning against withholding a worker’s wages and the command to pay promptly","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Allah the Exalted said: There are three whose opponent I will be on the Day of Resurrection: a man who gave his pledge by Me and then betrayed it, a man who sold a free person and consumed his price, and a man who hired a laborer, fully took his work from him, and did not give him his wages.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2270)."},{"num":5513,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطِ الْأَجِيرَ أَجْرَهُ قَبْلَ أَنْ يَجِفَّ عَرَقُهُ."],"takhrij":"حسن: رواه الطحاوي في مشكله (3014)، وابن عدي في الكامل (1702) والبيهقي في الكبرى (11659)، والصغرى (2133) بتحقيقي كلهم من طريق محمد بن عمار المؤذن، عن المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من منع الأجير أجره، والأمر بتعجيل إعطائه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Mushkil al-Athar (4/142), Ibn ‘Adi in al-Kamil (6/2235), and al-Bayhaqi in al-Kubra (6/121).","chapter_en":"Warning against withholding a worker’s wages and the command to pay promptly","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Give the worker his wages before his sweat dries.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في مشكله (3014)، وابن عدي في الكامل (1702)، والبيهقي في الكبرى (11659)."},{"num":5514,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا مَثَلُكُمْ وَالْيَهُودُ وَالنَّصَارَى كَرَجُلٍ اسْتَعْمَلَ عُمَّالاً، فَقَالَ: مَنْ يَعْمَلُ لِي إِلَى نِصْفِ النَّهَارِ عَلَى قِيرَاطٍ قِيرَاطٍ؟ فَعَمِلَتِ الْيَهُودُ عَلَى قِيرَاطٍ قِيرَاطٍ، ثُمَّ عَمِلَتِ النَّصَارَى عَلَى قِيرَاطٍ قِيرَاطٍ، ثُمَّ أَنْتُمُ الَّذِينَ تَعْمَلُونَ مِنْ صَلاَةِ الْعَصْرِ إِلَى مَغَارِبِ الشَّمْسِ عَلَى قِيرَاطَيْنِ قِيرَاطَيْنِ، فَغَضِبَتِ الْيَهُودُ وَالنَّصَارَى، وَقَالُوا: نَحْنُ أَكْثَرُ عَمَلاً وَأَقَلُّ عَطَاءً، قَالَ: هَلْ ظَلَمْتُكُمْ مِنْ حَقِّكُمْ شَيْئًا؟ قَالُوا: لاَ. فَقَالَ: فَذَلِكَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2269) عن إسماعيل بن أبي أويس قال: حدثني مالك، عن عبد الله بن دينار مولى عبد الله بن عمر، عن عبد الله بن عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب الإجارة على عمل لمدة نصف يوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2269).","chapter_en":"Hiring for work lasting half a day","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Umar ibn al-Khattab, may Allah be pleased with them both, narrated that the Messenger of Allah ﷺ said: “Your example and that of the Jews and Christians is like a man who hired workers and said: Who will work for me until midday for one qirat each? So the Jews worked for one qirat each. Then the Christians worked for one qirat each. Then you are the ones who work from the afternoon prayer until sunset for two qirats each. So the Jews and Christians became angry and said: We did more work and received less pay. He said: Have I wronged you in any of your due? They said: No. He said: That is My favor; I give it to whom I will.”"]}},"tuhfa":{},"full":1,"rep":[14683],"tks":"صحيح: رواه البخاري (2269)."},{"num":5515,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الْمُسْلِمِينَ وَالْيَهُودِ وَالنَّصَارَى كَمَثَلِ رَجُلٍ اسْتَأْجَرَ قَوْمًا يَعْمَلُونَ لَهُ عَمَلاً يَوْمًا إِلَى اللَّيْلِ عَلَى أَجْرٍ مَعْلُومٍ، فَعَمِلُوا لَهُ إِلَى نِصْفِ النَّهَارِ، فَقَالُوا لاَ حَاجَةَ لَنَا إِلَى أَجْرِكَ الَّذِي شَرَطْتَ لَنَا، وَمَا عَمِلْنَا بَاطِلٌ، فَقَالَ لَهُمْ: لاَ تَفْعَلُوا، أَكْمِلُوا بَقِيَّةَ عَمَلِكُمْ، وَخُذُوا أَجْرَكُمْ كَامِلاً، فَأَبَوْا، وَتَرَكُوا، وَاسْتَأْجَرَ أَجِيرَيْنِ بَعْدَهُمْ، فَقَالَ لَهُمَا أَكْمِلاَ بَقِيَّةَ يَوْمِكُمَا هَذَا، وَلَكُمَا الَّذِي شَرَطْتُ لَهُمْ مِنَ الأَجْرِ. فَعَمِلُوا حَتَّى إِذَا كَانَ حِينُ صَلاَةِ الْعَصْرِ قَالاَ لَكَ مَا عَمِلْنَا بَاطِلٌ، وَلَكَ الأَجْرُ الَّذِي جَعَلْتَ لَنَا فِيهِ. فَقَالَ لَهُمَا أَكْمِلاَ بَقِيَّةَ عَمَلِكُمَا، فَإِنَّ مَا بَقِيَ مِنَ النَّهَارِ شَىْءٌ يَسِيرٌ. فَأَبَيَا، وَاسْتَأْجَرَ قَوْمًا أَنْ يَعْمَلُوا لَهُ بَقِيَّةَ يَوْمِهِمْ، فَعَمِلُوا بَقِيَّةَ يَوْمِهِمْ حَتَّى غَابَتِ الشَّمْسُ، وَاسْتَكْمَلُوا أَجْرَ الْفَرِيقَيْنِ كِلَيْهِمَا، فَذَلِكَ مَثَلُهُمْ وَمَثَلُ مَا قَبِلُوا مِنْ هَذَا النُّورِ."],"takhrij":"صحيح: رواه البخاري في الإجارة (2271) عن محمد بن العلاء، حدثنا أبو أسامة، عن بُريد، عن أبي بردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب الإجارة على عمل لمدة يوم كامل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2271).","chapter_en":"Hiring for work lasting a full day","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Abu Musa narrated from the Prophet ﷺ that he said: “The example of the Muslims, Jews, and Christians is like a man who hired people to work for him for a day until nightfall for a known wage. They worked for him until midday, then said: We have no need for the wage you stipulated for us, and what we have done is worthless. He said to them: Do not do that. Complete the rest of your work and take your full wage. But they refused and left. Then he hired others after them and said to them: Complete the rest of this day, and you shall have the wage that I had stipulated for them. So they worked until the time of the afternoon prayer, then said: What we did is worthless for you, and you may keep the wage you assigned to us. He said to them: Complete the rest of your work, for what remains of the day is only a little. But they refused. Then he hired another people to work the remainder of the day, and they worked until the sun set, and they took the wages of both groups in full. That is their example and the example of what they accepted from this light.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2271)."},{"num":5516,"demo":false,"sanad":"","matn":["عَنْ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَيْشَ الْعُسْرَةِ، فَكَانَ مِنْ أَوْثَقِ أَعْمَالِي فِي نَفْسِي، فَكَانَ لِي أَجِيرٌ، فَقَاتَلَ إِنْسَانًا، فَعَضَّ أَحَدُهُمَا إِصْبَعَ صَاحِبِهِ، فَانْتَزَعَ إِصْبَعَهُ، فَأَنْدَرَ ثَنِيَّتَهُ، فَسَقَطَتْ، فَانْطَلَقَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَهْدَرَ ثَنِيَّتَهُ، وَقَالَ: أَفَيَدَعُ إِصْبَعَهُ فِي فِيكَ تَقْضَمُهَا ـ قَالَ: أَحْسِبُهُ قَالَ: ـ كَمَا يَقْضَمُ الْفَحْلُ."],"takhrij":"متفق عليه: رواه البخاري في الإجارة (2265)، ومسلم في القسامة (1674: 23) كلاهما من طريق ابن جريج قال: أخبرني عطاء، أخبرني صفوان بن يعلى بن أمية، عن أبيه. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الأجير في الغزو","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2265) and Muslim (1674:23). The wording is al-Bukhari’s.","chapter_en":"Taking an employee along in military expeditions","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Ya‘la ibn Umayyah said: I went out with the Prophet ﷺ in the Army of Hardship, and that was among the most dependable of my deeds in my own sight. I had an employee with me. He fought a man, and one of them bit the finger of the other. The man pulled his finger away, and the other man’s incisor tooth fell out. He went to the Prophet ﷺ, but he ruled the tooth loss as uncompensated and said: “Should he leave his finger in your mouth for you to chew on it — he said: I think he said — like a stallion bites?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2265)، ومسلم (1674: 23). واللفظ للبخاري."},{"num":5517,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قـــــالت: \"واستأجـــر رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَأَبُو بَكْرٍ رَجُلاً مِنْ بَنِي الدِّيلِ هَادِيًا خِرِّيتًا، وَهْوَ عَلَى دِينِ كُفَّارِ قُرَيْشٍ، فَدَفَعَا إِلَيْهِ رَاحِلَتَيْهِمَا، وَوَاعَدَاهُ غَارَ ثَوْرٍ بَعْدَ ثَلاَثِ لَيَالٍ، فأتاهما بِرَاحِلَتَيْهِمَا صُبْحَ ثَلاَثٍ\"."],"takhrij":"صحيح: رواه البخاري في الإجارة (2264) عن يحيى بن بكير، حدثنا الليث، عن عقيل، قـال ابن شهاب: فأخبرني عـروة بن الزبير أن عائشة قالت فذكرته.","grade":"صحيح","chapter_ar":"باب استئجار الكافر عند الحاجة إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2264).","chapter_en":"Hiring a disbeliever when there is need for him","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Aisha, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ and Abu Bakr hired a man from Banu al-Dil as a guide who was highly skilled in navigation, while he was still upon the religion of the disbelievers of Quraysh. They entrusted their two riding animals to him and arranged to meet him at the Cave of Thawr after three nights. He came to them with their riding animals on the morning of the third day."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2264)."},{"num":5518,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ -رَضِيَ اللَّهِ عَنْهُ- قَالَ: انْطَلَقَ نَفَرٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفْرَةٍ سَافَرُوهَا حَتَّى نَزَلُوا عَلَى حي مِنْ أَحْيَاءِ الْعَرَبِ، فَاسْتَضَافُوهُمْ، فَأَبَوْا أَنْ يُضَيِّفُوهُمْ، فَلُدِغَ سَيِّدُ ذَلِكَ الحي، فَسَعَوْا لَهُ بِكُلِّ شيء، لاَ يَنْفَعُهُ شيء. فَقَالَ بَعْضُهُمْ: لَوْ أَتَيْتُمْ هَؤُلاَءِ الرَّهْطَ الَّذِينَ نَزَلُوا لَعَلَّهُ أَنْ يَكُونَ عِنْدَ بَعْضِهِمْ شيء، فَأَتَوْهُمْ، فَقَالُوا: يَا أَيُّهَا الرَّهْطُ، إِنَّ سَيِّدَنَا لُدغ، وَسَعَيْنَا لَهُ بِكُلِّ شيء لاَ يَنْفَعُهُ، فَهَلْ عِنْدَ أَحَدٍ مِنْكُمْ مِنْ شَيْءٍ؟ فَقَالَ بَعْضُهُمْ: نَعَمْ، وَاللَّهِ إِنِّي لأَرْقِي، وَلَكِنْ وَاللَّهِ لَقَدِ اسْتَضَفْنَاكُمْ فَلَمْ تُضِيِّفُونَا، فَمَا أَنَا بِرَاقٍ لَكُمْ حَتَّى تَجْعَلُوا لَنَا جُعْلاً. فَصَالَحُوهُمْ عَلَى قَطِيعٍ مِنَ الْغَنَمِ، فَانْطَلَقَ يَتْفِلُ عَلَيْهِ وَيَقْرَأُ: ﴿ ﭖ ﭗ ﭘ ﭙ﴾ فَكَأَنَّمَا نُشِطَ مِنْ عِقَالٍ، فَانْطَلَقَ يَمْشِي وَمَا بِهِ قَلَبَة. قَالَ: فَأَوْفَوْهُمْ جُعْلَهُمُ الَّذِي صَالَحُوهُمْ عَلَيْهِ. فَقَالَ بَعْضُهُمُ: اقْسِمُوا. فَقَالَ الَّذِي رَقَى: لاَ تَفْعَلُوا حَتَّى نَأْتِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَنَذْكُرَ لَهُ الَّذِي كَانَ، فَنَنْظُرَ مَا يَأْمُرُنَا، فَقَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَذَكَرُوا لَهُ، فَقَالَ: وَمَا يُدْرِيكَ أَنَّهَا رُقْيَةٌ. ثُمَّ قَالَ: قَدْ أَصَبْتُمُ، اقْسِمُوا، وَاضْرِبُوا لِي مَعَكُمْ سَهْمًا فَضَحِكَ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"متفق عليه: رواه البخاري في الإجارة (2276)، ومسلم في السلام (2201: 65) من طريق أبي بحر (هو جعفر بن أبي وحشية)، عن أبي المتوكل (هو الناجي)، عن أبي سعيد الخدري قال فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2276) and Muslim (2201:65). The wording is al-Bukhari’s.","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: A group of the Companions of the Prophet ﷺ set out on a journey until they came to one of the Arab tribes. They asked them for hospitality, but they refused to host them. Then the chief of that tribe was stung, and they tried everything for him, but nothing helped. Some of them said: Go to those people who have camped here; perhaps one of them has something. So they came to them and said: O people, our chief has been stung, and we have tried everything for him but nothing has benefited him. Does any one of you have anything? One of them said: Yes, by Allah, I do healing recitation, but by Allah, we asked you for hospitality and you did not host us, so I will not recite for you unless you assign us a payment. So they agreed on a flock of sheep. Then he went and spat lightly while reciting: “All praise is for Allah, Lord of the worlds,” and it was as if the man had been released from a rope. He got up walking, and there was nothing wrong with him. They then gave them the payment they had agreed on. Some of them said: Divide it. But the one who recited said: Do not do that until we go to the Prophet ﷺ and mention to him what happened, then we will see what he commands us. So they came to the Messenger of Allah ﷺ and mentioned it to him. He said: “How did you know that it is a healing recitation?” Then he said: “You did right. Divide it, and give me a share with you.” Then the Prophet ﷺ laughed."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2276)، ومسلم (2201: 65). واللفظ للبخاري."},{"num":5519,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ نَفَرًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرُّوا بِمَاءٍ فِيهِمْ لَدِيغٌ -أَوْ سَلِيمٌ-، فَعَرَضَ لَهُمْ رَجُلٌ مِنْ أَهْلِ الْمَاءِ، فَقَالَ: هَلْ فِيكُمْ مِنْ رَاقٍ؛ إِنَّ فِي الْمَاءِ رَجُلاً لَدِيغًا -أَوْ سَلِيمًا-؟ فَانْطَلَقَ رَجُلٌ مِنْهُمْ، فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ عَلَى شَاءٍ، فَبَرَأَ، فَجَاءَ بِالشَّاءِ إِلَى أَصْحَابِهِ، فَكَرِهُوا ذَلِكَ، وَقَالُوا: أَخَذْتَ عَلَى كِتَابِ اللَّهِ أَجْرًا حَتَّى قَدِمُوا الْمَدِينَةَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَخَذَ عَلَى كِتَابِ اللَّهِ أَجْرًا؟ فَقَالَ عَلَيْهِ السلام: إِنَّ أَحَقَّ مَا أَخَذْتُمْ عَلَيْهِ أَجْرًا كِتَابُ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الطب (5737) عن سيدان بن مضارب أبي محمد الباهلي، حدثنا أبو معشر البصري – هو صدوق- يوسف بن يزيد البراء قـال: حدني عبيدالله بن الأخنس أبو مالك، عن ابن أبي مليكة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5737).","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Ibn Abbas narrated that a group of the Companions of the Messenger of Allah ﷺ passed by a place of water where there was a man who had been stung — or bitten by something poisonous. A man from the people of the water came to them and said: Is there anyone among you who can perform healing recitation? At the water there is a man who has been stung — or bitten. So one of them went and recited Surat al-Fatihah over him in exchange for a sheep, and the man recovered. He then came with the sheep to his companions, but they disliked that and said: You took payment for the Book of Allah. When they came to Madinah they said: O Messenger of Allah ﷺ, he took payment for the Book of Allah. So the Messenger of Allah ﷺ said: “The most rightful thing for which you may take payment is the Book of Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5737)."},{"num":5520,"demo":false,"sanad":"","matn":["عَنْ خَارِجَةَ بْنِ الصَّلْتِ، عَنْ عَمِّهِ، أَنَّهُ مَرَّ بِقَوْمٍ، فَأَتَوْهُ، فَقَالُوا: إِنَّكَ جِئْتَ مِنْ عِنْدِ هَذَا الرَّجُلِ بِخَيْرٍ، فَارْقِ لَنَا هَذَا الرَّجُلَ. فَأَتَوْهُ بِرَجُلٍ مَعْتُوهٍ فِي الْقُيُودِ، فَرَقَاهُ بِأُمِّ الْقُرْآنِ ثَلاَثَةَ أَيَّامٍ غُدْوَةً وَعَشِيَّةً، كُلَّمَا خَتَمَهَا جَمَعَ بُزَاقَهُ، ثُمَّ تَفَلَ فَكَأَنَّمَا أُنْشِطَ مِنْ عِقَالٍ، فَأَعْطُوهُ شَيْئًا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَهُ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلْ، فَلَعَمْرِي لَمَنْ أَكَلَ بِرُقْيَةٍ بَاطِلٍ لَقَدْ أَكَلْتَ بِرُقْيَةٍ حَقٍّ.","وفي رواية: فأعطوه مائة شاة."],"takhrij":"حسن: رواه أبو داود (3420، 3896، 3897، 3901)، وابن ماجه (6111)، وأحمد (21835)، وصحّحه ابن حبان (6110)، والحاكم (1/559-560) كلهم من طرق عن عامر الشعبي، عن خارجة بن الصلت، عن عمه فذكره.","grade":"حسن","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3901, 3897, 3896, 3420), Ibn Mājah (2156), and Aḥmad (21835), and authenticated by Ibn Ḥibbān (6110) and al-Ḥākim (1/559–560).","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Khārijah ibn al-Ṣalt narrated from his uncle that he passed by some people. They came to him and said: “You have come from this man with something good, so perform a healing recitation for this man.” They brought him a mentally afflicted man who was restrained in chains. He recited Umm al-Qurʾān over him for three days, morning and evening. Whenever he completed the recitation, he gathered his saliva and lightly blew upon him. The man then became as though he had been released from a restraint. They gave him something in payment, so he came to the Prophet ﷺ and mentioned it to him. The Prophet ﷺ said: “Eat it. By my life, there are those who consume wealth through false incantations, but you have earned through a true healing recitation.” In another narration:","“They gave him one hundred sheep.”"]},"buhuth":{"en":["The jurisprudence of this chapter: These hadiths establish the permissibility of taking payment for teaching the Qurʾān and of stipulating such payment. They also establish the permissibility of ruqyah with the Qurʾān, because recitation and ruqyah are lawful acts, and taking payment for them was permitted, just as a physician may take payment for treatment by word or deed.","There were three teachers in Madinah who taught children, and ʿUmar ibn al-Khaṭṭāb used to allocate fifteen dirhams each month to each of them. Narrated by Abū Bakr ibn Abī Shaybah (4/346, no. 2028)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11465],"tks":"حسن: رواه أبو داود (3901، 3897، 3896، 3420)، وابن ماجه (6111)، وأحمد (21835)، وصححه ابن حبان (6110)، والحاكم (1/559-560)."},{"num":5521,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُشْغَلُ، فَإِذَا قَدِمَ رَجُلٌ مُهَاجِرٌ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَفَعَهُ إِلَى رَجُلٍ مِنَّا يُعَلِّمُهُ الْقُرْآنَ، فَدَفَعَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا، فَكَانَ مَعِي فِي الْبَيْتِ، أُعَشِّيهِ عَشَاءَ أَهْلِ الْبَيْتِ، فَكُنْتُ أُقْرِئُهُ الْقُرْآنَ، فَانْصَرَفَ انْصِرَافَةً إِلَى أَهْلِهِ، فَرَأَى أَنَّ عَلَيْهِ حَقًّا، فَأَهْدَى إِلَيَّ قَوْسًا لَمْ أَرَ أَجْوَدَ مِنْهَا عُودًا، وَلَا أَحْسَنَ مِنْهَا عِطْفًا، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: مَا تَرَى يَا رَسُولَ اللَّهِ فِيهَا؟ قَالَ: جَمْرَةٌ بَيْنَ كَتِفَيْكَ تَقَلَّدْتَهَا، أَوْ تَعَلَّقْتَهَا."],"takhrij":"حسن: رواه أبو داود (3417)، وأحمد (22766)، والحاكم (5527) كلهم من طريق بشر بن عبد الله يعني ابن بشار السلمي قال: حدثني عبادة بن نسي، عن جنادة بن أبي أمية، عن عبادة بن الصامت قال. فذكره.","grade":"حسن","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan by corroboration: Narrated by Abu Dawud (3416, 3417), Ahmad (22766), and al-Hakim (3/356). The wording is Ahmad’s.","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Ubadah ibn al-Samit said: The Messenger of Allah ﷺ would be occupied, and when a migrant came to the Messenger of Allah ﷺ, he would hand him over to one of us to teach him the Quran. So the Messenger of Allah ﷺ entrusted a man to me, and he stayed with me in the house. I would feed him as the family of the house ate, and I would teach him the Quran. Then he returned to his family for a time and felt that he owed me something, so he gave me a bow as a gift. I had never seen a bow better in wood nor finer in curve than it. So I came to the Messenger of Allah ﷺ and said: What do you think of it, O Messenger of Allah ﷺ? He said: “It is a live coal between your shoulders that you have hung there,” or “that you have fastened there.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3416، 3417)، وأحمد (22766)، والحاكم (5527)، واللفظ لأحمد."},{"num":5522,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن شِبْلٍ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اقْرَءُوا الْقُرْآنَ، وَلَا تَغْلُوا فِيهِ، وَلَا تَجْفُوا عَنْهُ، وَلَا تَأْكُلُوا بِهِ، وَلَا تَسْتَكْثِرُوا بِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (15529) عن إسماعيل بن إبراهيم، عن هشام -يعني الدستوائي- قال: حدثني يحيى بن أبي كثير، عن أبي راشد الحبراني قال: قال عبد الرحمن بن شبل فذكره.","grade":"صحيح","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (15529) and al-Mustaghfiri in Fada’il al-Quran (5).","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abd al-Rahman ibn Shibl said: I heard the Messenger of Allah ﷺ say: “Recite the Quran, but do not go to excess concerning it, do not turn away from it, do not consume by means of it, and do not seek abundance through it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (15529)، والمستغفري في فضائل القرآن (5)."},{"num":5523,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَخَذَ قَوْسًا عَلَى تَعْلِيمِ الْقُرْآنِ قَلَّدَهُ اللهُ قَوْسًا مِنْ نَارٍ."],"takhrij":"حسن: رواه البيهقي (11685) من حديث عثمان بن سعيد الدارمي، ثنا عبد الرحمن بن يحيى بن إسماعيل بن عبيدالله، ثنا الوليد بن مسلم، ثنا سعيد بن عبد العزيز، عن إسماعيل بن عبيدالله، عن أم الدرداء، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (6/126).","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abu al-Darda narrated that the Messenger of Allah ﷺ said: “Whoever takes a bow as payment for teaching the Quran, Allah will collar him with a bow of fire.”"]},"buhuth":{"en":["The understanding of this chapter is that its hadiths indicate the dislike of taking payment for teaching the Quran.","The scholars differed regarding some situations and not others:","Among them were those who held that the dislike applies if payment is made a condition. Others said the dislike applies when the work is done purely for Allah’s sake as a religious service, so he should not take wages for it, because payment conflicts with that intention. But if he neither asked for nor stipulated payment, then it is permissible, as in the hadith of Ibn Abbas in the previous chapter. Others said that if there is no one among the Muslims to teach the Quran except one person, then he must teach them and should not take payment, because teaching them becomes a personal obligation on him. But if there are others besides him, then taking payment is permissible.","As for when this payment comes from the ruler, who oversees the interests of the community, then there is no dislike in that by agreement, because setting such wages helps in managing the affairs of the land. This has been the established practice from the Rightly Guided Caliphs until today."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (11685)."},{"num":5524,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا أَجْلَى الْيَهُودَ وَالنَّصَارَى مِنْ أَرْضِ الْحِجَازِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا ظَهَرَ عَلَى خَيْبَرَ أَرَادَ إِخْرَاجَ الْيَهُودِ مِنْهَا، وَكَانَتِ الأَرْضُ حِينَ ظَهَرَ عَلَيْهَا لِلَّهِ وَلِرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِلْمُسْلِمِينَ، وَأَرَادَ إِخْرَاجَ الْيَهُودِ، مِنْهَا، فَسَأَلَتِ الْيَهُودُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُقِرَّهُمْ بِهَا أَنْ يَكْفُوا عَمَلَهَا، وَلَهُمْ نِصْفُ الثَّمَرِ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نُقِرُّكُمْ بِهَا عَلَى ذَلِكَ مَا شِئْنَا. فَقَرُّوا بِهَا حَتَّى أَجْلاَهُمْ عُمَرُ إِلَى تَيْمَاءَ، وَأَرِيحَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2338) ومسلم في المساقاة (1551/6) كلاهما من حديث عبد الرزاق، أخبرنا ابن جريج، حدثني موسى بن عقبة، عن نافع، عن ابن عمر، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب يجوز للإمام فسخ المعاهدة مع الكفار إذا اشترط عليهم أنه يقرهم إلى متى شاء وهم قد رضوا بذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2338) and Muslim (1551:6).","chapter_en":"It is permissible for the ruler to terminate a treaty with disbelievers if he stipulated that he would let them remain only as long as he wished and they agreed to that","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Ibn Umar narrated that Umar ibn al-Khattab expelled the Jews and Christians from the land of the Hijaz. When the Messenger of Allah ﷺ gained victory over Khaybar, he wanted to expel the Jews from it. The land, when he gained control over it, belonged to Allah, His Messenger, and the Muslims. So he intended to remove the Jews from it, but the Jews asked the Messenger of Allah ﷺ to leave them there on the condition that they would do the labor on it and receive half of the produce. So the Messenger of Allah ﷺ said to them: “We will let you remain there upon that for as long as we wish.” So they remained there until Umar expelled them to Tayma and Ariha."]}},"tuhfa":{},"full":1,"rep":[5562,9047],"tks":"متفق عليه: رواه البخاري (2338)، ومسلم (1551/6)."},{"num":5525,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ ذَكَرَ رَجُلاً مِنْ بَنِي إِسْرَائِيلَ، سَأَلَ بَعْضَ بَنِي إِسْرَائِيلَ أَنْ يُسْلِفَهُ أَلْفَ دِينَارٍ، فَقَالَ: ائْتِنِي بِالشُّهَدَاءِ أُشْهِدُهُمْ. فَقَالَ: كَفَى بِاللَّهِ شَهِيدًا. قَالَ: فَأْتِنِي بِالْكَفِيلِ. قَالَ: كَفَى بِاللَّهِ كَفِيلاً. قَالَ: صَدَقْتَ. فَدَفَعَهَا إِلَيْهِ إِلَى أَجَلٍ مُسَمًّى، فَخَرَجَ فِي الْبَحْرِ، فَقَضَى حَاجَتَهُ، ثُمَّ الْتَمَسَ مَرْكَبًا يَرْكَبُهَا، يَقْدَمُ عَلَيْهِ لِلأَجَلِ الَّذِي أَجَّلَهُ، فَلَمْ يَجِدْ مَرْكَبًا، فَأَخَذَ خَشَبَةً، فَنَقَرَهَا، فَأَدْخَلَ فِيهَا أَلْفَ دِينَارٍ، وَصَحِيفَةً مِنْهُ إِلَى صَاحِبِهِ، ثُمَّ زَجَّجَ مَوْضِعَهَا، ثُمَّ أَتَى بِهَا إِلَى الْبَحْرِ، فَقَالَ: اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنِّي كُنْتُ تَسَلَّفْتُ فُلاَنًا أَلْفَ دِينَارٍ، فَسَأَلَنِي كَفِيلاً، فَقُلْتُ: كَفَى بِاللَّهِ كَفِيلاً، فَرَضِيَ بِكَ، وَسَأَلَنِي شَهِيدًا، فَقُلْتُ: كَفَى بِاللَّهِ شَهِيدًا، فَرَضِيَ بِكَ، وَأَنِّي جَهَدْتُ أَنْ أَجِدَ مَرْكَبًا، أَبْعَثُ إِلَيْهِ الَّذِي لَهُ فَلَمْ أَقْدِرْ، وَإِنِّي أَسْتَوْدِعُكَهَا. فَرَمَى بِهَا فِي الْبَحْرِ حَتَّى وَلَجَتْ فِيهِ، ثُمَّ انْصَرَفَ، وَهْوَ فِي ذَلِكَ يَلْتَمِسُ مَرْكَبًا، يَخْرُجُ إِلَى بَلَدِهِ، فَخَرَجَ الرَّجُلُ الَّذِي كَانَ أَسْلَفَهُ، يَنْظُرُ لَعَلَّ مَرْكَبًا قَدْ جَاءَ بِمَالِهِ، فَإِذَا بِالْخَشَبَةِ الَّتِي فِيهَا الْمَالُ، فَأَخَذَهَا لأَهْلِهِ حَطَبًا، فَلَمَّا نَشَرَهَا وَجَدَ الْمَالَ وَالصَّحِيفَةَ، ثُمَّ قَدِمَ الَّذِي كَانَ أَسْلَفَهُ، فَأَتَى بِالأَلْفِ دِينَارٍ، فَقَالَ: وَاللَّهِ مَا زِلْتُ جَاهِدًا فِي طَلَبِ مَرْكَبٍ لآتِيَكَ بِمَالِكَ، فَمَا وَجَدْتُ مَرْكَبًا قَبْلَ الَّذِي أَتَيْتُ فِيهِ. قَالَ: هَلْ كُنْتَ بَعَثْتَ إِلَىَّ بِشَىْءٍ؟ قَالَ: أُخْبِرُكَ أَنِّي لَمْ أَجِدْ مَرْكَبًا قَبْلَ الَّذِي جِئْتُ فِيهِ. قَالَ: فَإِنَّ اللَّهَ قَدْ أَدَّى عَنْكَ الَّذِي بَعَثْتَ فِي الْخَشَبَةِ، فَانْصَرِفْ بِالأَلْفِ الدِّينَارِ رَاشِدًا."],"takhrij":"صحيح: رواه البخاري في الكفالة (2291) معلقا مجزوما، فقال: وقال الليث، حدثني جعفر بن ربيعة، عن عبد الرحمن بن هرمز، عن أبي هريرة فذكره. هذا علقه البخاري، ووصله في آخره في رواية أبي ذر، وأبي الوقت، فقال: حدثني عبد الله بن صالح، حدثني الليث به.","grade":"صحيح","chapter_ar":"باب مشروعية الكفالة في القروض والديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2291).","chapter_en":"The legality of surety in loans and debts","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ that he mentioned a man from the Children of Israel who asked another man from the Children of Israel to lend him one thousand dinars. He said: Bring me witnesses so I may have them witness it. He said: Allah is sufficient as a witness. He said: Then bring me a guarantor. He said: Allah is sufficient as a guarantor. He said: You have spoken the truth. So he gave it to him for a fixed term. Then the borrower traveled by sea and fulfilled his need. Afterward he looked for a vessel on which he could travel to return the money by the appointed time, but he found none. So he took a piece of wood, hollowed it out, placed in it the one thousand dinars and a letter to its owner, then sealed it, brought it to the sea, and said: O Allah, You know that I borrowed one thousand dinars from so-and-so. He asked me for a guarantor and I said: Allah is sufficient as a guarantor, and he was satisfied with You. He asked me for a witness and I said: Allah is sufficient as a witness, and he was satisfied with You. I have tried hard to find a vessel to send him what belongs to him, but I could not, so I entrust it to You. Then he threw it into the sea until it entered it, and he went away, while still looking for a vessel to travel to his land. The man who had given the loan went out, hoping that a ship might have arrived with his money, and he found the piece of wood containing the money. He took it home as firewood. When he split it open, he found the money and the letter. Later, the borrower arrived carrying the one thousand dinars and said: By Allah, I kept striving to find a vessel to bring you your money, but I found none before the one by which I have now come. The lender said: Did you send me anything? He said: I am telling you that I found no vessel before the one by which I came. He said: Allah has delivered on your behalf what you sent in the wood, so return with your thousand dinars, rightly guided."]}},"tuhfa":{},"full":1,"rep":[8281],"tks":"صحيح: رواه البخاري (2291)."},{"num":5526,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَجُلاً، لَزِمَ غَرِيمًا لَهُ بِعَشْرَةِ دَنَانِيرَ، فَقَالَ: وَاللَّهِ لاَ أُفَارِقُكَ حَتَّى تَقْضِيَنِي، أَوْ تَأْتِيَنِي بِحَمِيلٍ، فَتَحَمَّلَ بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَاهُ بِقَدْرِ مَا وَعَدَهُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ أَيْنَ أَصَبْتَ هَذَا الذَّهَبَ. قَالَ: مِنْ مَعْدِنٍ. قَالَ: لاَ حَاجَةَ لَنَا فِيهَا، وَلَيْسَ فِيهَا خَيْرٌ. فَقَضَاهَا عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (3328)، وابن ماجه (2406)، وعبد بن حميد (596)، والحاكم (2161)، والبيهقي (11402) كلهم من طريق عبد العزيز بن محمد الدراوردي، عن عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس فذكره. واللفظ لأبي داود. وفي لفظ غيره: فقال له النبي صلى الله عليه وسلم: كم تستنظره؟ فقال: شهرا. فقال رسول الله صلى الله عليه وسلم: فأنا أحمل له.","grade":"حسن","chapter_ar":"باب مشروعية الكفالة في القروض والديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3328), Ibn Majah (2406), Abd ibn Humayd (596), and al-Hakim (2161). The wording is Abu Dawud’s. In another wording: the Prophet ﷺ said to him, “How long will you give him?” He said: One month. So the Messenger of Allah ﷺ said: “Then I will stand surety for him.”","chapter_en":"The legality of surety in loans and debts","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas narrated that a man pressed a debtor of his for ten dinars and said: By Allah, I will not leave you until you pay me or bring me a surety. Then the Prophet ﷺ guaranteed it for him. Later the debtor came with the amount he had promised, and the Prophet ﷺ said to him: “From where did you get this gold?” He said: From a mine. He said: “We have no need of it, and there is no good in it.” Then the Messenger of Allah ﷺ paid it off on his behalf."]},"buhuth":{"en":["His statement, “We have no need of it,” was because the Prophet ﷺ had guaranteed coined dinars that used to be brought to them from the Roman lands, since the first person to establish Islamic minting and strike dinars was Abd al-Malik ibn Marwan, as is well known. What the man brought was unminted gold, so the Prophet ﷺ refrained from accepting it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3328)، وابن ماجه (2406)، وعبد بن حميد (596)، والحاكم (2161)، واللفظ لأبي داود. وفي لفظ غيره: فقال له النبي ﷺ: (( كم تستنظره؟ )) فقال: شهرا. فقال رسول الله ﷺ: (( فأنا أحمل له ))."},{"num":5527,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِجَنَازَةٍ، لِيُصَلِّيَ عَلَيْهَا، فَقَالَ: هَلْ عَلَيْهِ مِنْ دَيْنٍ. قَالُوا: لاَ. فَصَلَّى عَلَيْهِ، ثُمَّ أُتِيَ بِجَنَازَةٍ أُخْرَى، فَقَالَ: هَلْ عَلَيْهِ مَنْ دَيْنٍ. قَالُوا: نَعَمْ. قَالَ: صَلُّوا عَلَى صَاحِبِكُمْ. قَالَ أَبُو قَتَادَةَ: عَلَىَّ دَيْنُهُ يَا رَسُولَ اللَّهِ. فَصَلَّى عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الكفالة (2295) عن أبي عاصم، عن يزيد بن أبي عبيد، عن سلمة بن الأكوع فذكره. سبق ذكره وما في معناه في الجنائز.","grade":"صحيح","chapter_ar":"باب ما جاء في الضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2295).","chapter_en":"What has come regarding guarantee","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ reported: A deceased person was brought to the Prophet ﷺ so that he might perform the funeral prayer over him. He asked: “Does he owe any debt?” They replied: “No.” So he prayed over him. Then another deceased person was brought. He asked: “Does he owe any debt?” They replied: “Yes.” He said: “Pray over your companion.” Abū Qatādah said: “O Messenger of Allah ﷺ, I will take responsibility for his debt.” So the Prophet ﷺ prayed over him."]},"intro":{"ar":["قال الله تعالى: { قَالُوا نَفْقِدُ صُوَاعَ الْمَلِكِ وَلِمَن جَاءَ بِهِ حِمْلُ بَعِيرٍ وَأَنَا بِهِ زَعِيمٌ } [يوسف: ٧٢].","والزعيم والحميل والكفيل بمعنى واحد، فالزعيم لغة أهل المدينة، والحميل لغة أهل مضر، والكفيل لغة أهل العراق، أي أن من تكفّل دينًا عن الغير عليه الغرم، وهو الضمان."],"en":["Allah the Exalted said: “They said: We have lost the king’s measuring cup, and whoever brings it shall have a camel-load, and I am a guarantor for it.” [Yusuf: 72]","The words guarantor, surety, and sponsor all carry one meaning. “Zaim” is the term used by the people of Madinah, “hamil” by the people of Mudar, and “kafil” by the people of Iraq. The meaning is that whoever takes responsibility for another person’s debt becomes liable for it. This is guarantee."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2295)."},{"num":5528,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الباهلي قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الزَّعِيمُ غَارِمٌ، وَالدَّيْنُ مَقْضِيٌّ."],"takhrij":"حسن: رواه أبو داود (3565)، والترمذي (1265)، وابن ماجه (2405)، والبيهقي (12405)، وأحمد (22294) كلهم من حديث إسماعيل بن عياش قـال: حدثني شرحبيل بن مسلم الخولاني قال: سمعت أبا أمامة يقول فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3565), al-Tirmidhi (1265), Ibn Majah (2405), al-Bayhaqi (6/172), and Ahmad (22294).","chapter_en":"What has come regarding guarantee","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Umamah al-Bahili said: I heard the Messenger of Allah ﷺ say: “The guarantor is liable, and the debt must be paid.”"]},"buhuth":{"en":["This is part of a long hadith whose portions are scattered throughout the books of Sunnah. Its full wording — as mentioned by Ahmad and others — is that the Prophet ﷺ gave a sermon during the Farewell Pilgrimage and said: “Allah has given every person with a right his due, so there is no bequest for an heir. The child belongs to the marriage bed, and the adulterer gets the stone, and their reckoning is with Allah. Whoever claims lineage to someone other than his father or attaches himself to other than his patrons, then upon him is the continuous curse of Allah until the Day of Resurrection. A woman must not spend anything from her house except with the permission of her husband.” It was said: O Messenger of Allah ﷺ, not even food? He said: “That is the best of our wealth.” Then he said: “A borrowed item must be returned, a granted loaned animal must be returned, the debt must be paid, and the guarantor is liable.” Al-Tirmidhi said: Hasan Gharib."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3565)، والترمذي (1265)، وابن ماجه (2405)، والبيهقي (12405)، وأحمد (22294)."},{"num":5529,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَطْلُ الْغَنِيِّ ظُلْمٌ، فَإِذَا أُتْبِعَ أَحَدُكُمْ عَلَى مَلِيٍّ فَلْيَتْبَعْ."],"takhrij":"متفق عليه: رواه مالك في البيوع (84) عن أبي الزناد، عن الأعرج، عن أبي هريرة به.","grade":"متفق عليه","chapter_ar":"باب قبول الحوالة إذا أحيل على مليء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (84), al-Bukhari (2287), and Muslim (1564).","chapter_en":"Accepting a transfer of debt when one is transferred to a solvent person","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “The delay of a wealthy person in paying is injustice, and if one of you is referred to a solvent person, then let him follow that transfer.”"]},"buhuth":{"en":["The phrase “the delay of a wealthy person” comes from a root meaning stretching or prolonging, such as when metal is stretched to make it longer. The intended meaning here is delaying payment of what is due without excuse. Its meaning is that if one of you is transferred to a solvent debtor, he should accept the transfer. Some scholars said that if a person is transferred to a solvent debtor and accepts the transfer, then the original debtor is cleared, and he cannot go back to the original debtor. This is the view of al-Shafi‘i, Ahmad, and Ishaq. Al-Tirmidhi mentioned this (1308)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5620],"tks":"متفق عليه: رواه مالك (84)، والبخاري (2287)، ومسلم (1564)."},{"num":5530,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَكَّلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحِفْظِ زَكَاةِ رَمَضَانَ، فَأَتَانِي آتٍ، فَجَعَلَ يَحْثُو مِنَ الطَّعَامِ، فَأَخَذْتُهُ، وَقُلْتُ: وَاللَّهِ لأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: إِنِّي مُحْتَاجٌ، وَعَلَىَّ عِيَالٌ، وَلِي حَاجَةٌ شَدِيدَةٌ. قَالَ: فَخَلَّيْتُ عَنْهُ، فَأَصْبَحْتُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا هُرَيْرَةَ، مَا فَعَلَ أَسِيرُكَ الْبَارِحَةَ. قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، شَكَا حَاجَةً شَدِيدَةً وَعِيَالاً، فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ. قَالَ: أَمَا إِنَّهُ قَدْ كَذَبَكَ، وَسَيَعُودُ. فَعَرَفْتُ أَنَّهُ سَيَعُودُ لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُ سَيَعُودُ. فَرَصَدْتُهُ، فَجَاءَ يَحْثُو مِنَ الطَّعَامِ، فَأَخَذْتُهُ، فَقُلْتُ لأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: دَعْنِي؛ فَإِنِّي مُحْتَاجٌ، وَعَلَىَّ عِيَالٌ، لاَ أَعُودُ، فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ، فَأَصْبَحْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا هُرَيْرَةَ، مَا فَعَلَ أَسِيرُكَ. قُلْتُ: يَا رَسُولَ اللَّهِ، شَكَا حَاجَةً شَدِيدَةً وَعِيَالاً، فَرَحِمْتُهُ، فَخَلَّيْتُ سَبِيلَهُ. قَالَ: أَمَا إِنَّهُ قَدْ كَذَبَكَ، وَسَيَعُودُ. فَرَصَدْتُهُ الثَّالِثَةَ، فَجَاءَ يَحْثُو مِنَ الطَّعَامِ، فَأَخَذْتُهُ، فَقُلْتُ: لأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهَذَا آخِرُ ثَلاَثِ مَرَّاتٍ أَنَّكَ تَزْعُمُ لاَ تَعُودُ، ثُمَّ تَعُودُ. قَالَ: دَعْنِي أُعَلِّمْكَ كَلِمَاتٍ يَنْفَعُكَ اللَّهُ بِهَا. قُلْتُ: مَا هُوَ؟ قَالَ: إِذَا أَوَيْتَ إِلَى فِرَاشِكَ، فَاقْرَأْ آيَةَ الْكُرْسِيِّ {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ} حَتَّى تَخْتِمَ الآيَةَ، فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ، وَلاَ يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ. فَخَلَّيْتُ سَبِيلَهُ، فَأَصْبَحْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا فَعَلَ أَسِيرُكَ الْبَارِحَةَ. قُلْتُ: يَا رَسُولَ اللَّهِ، زَعَمَ أَنَّهُ يُعَلِّمُنِي كَلِمَاتٍ، يَنْفَعُنِي اللَّهُ بِهَا، فَخَلَّيْتُ سَبِيلَهُ. قَالَ: مَا هِيَ. قُلْتُ: قَالَ لِي: إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ مِنْ أَوَّلِهَا حَتَّى تَخْتِمَ {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ} وَقَالَ لِي: لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ، وَلاَ يَقْرَبَكَ شَيْطَانٌ حَتَّى تُصْبِحَ، وَكَانُوا أَحْرَصَ شَىْءٍ عَلَى الْخَيْرِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ قَدْ صَدَقَكَ وَهُوَ كَذُوبٌ، تَعْلَمُ مَنْ تُخَاطِبُ مُنْذُ ثَلاَثِ لَيَالٍ يَا أَبَا هُرَيْرَةَ. قَالَ: لاَ. قَالَ: ذَاكَ شَيْطَانٌ."],"takhrij":"صحيح: رواه البخاري في الوكالة (2311) تعليقا قال: وقال عثمان بن الهيثم أبو عمرو، حدثنا عوف، عن محمد بن سيرين، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الوكالة على حفظ زكاة رمضان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2311) in suspended form, and connected by al-Nasa’i in al-Kubra (10729) and Ibn Khuzaymah (2424).","chapter_en":"Agency in guarding the Zakat of Ramadan","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ entrusted me with guarding the Zakat of Ramadan. Then someone came and began scooping up from the food, so I seized him and said: By Allah, I will take you to the Messenger of Allah ﷺ. He said: I am needy, I have dependents, and I am in severe need. So I let him go. In the morning the Prophet ﷺ said: “O Abu Hurayrah, what happened to your captive last night?” I said: O Messenger of Allah ﷺ, he complained of severe need and dependents, so I had mercy on him and let him go. He said: “Indeed, he lied to you, and he will return.” So I knew he would return because of the statement of the Messenger of Allah ﷺ that he would return. I lay in wait for him, and he came again scooping from the food, so I seized him and said: I will take you to the Messenger of Allah ﷺ. He said: Leave me, for I am needy and have dependents; I will not return. So I had mercy on him and let him go. In the morning the Messenger of Allah ﷺ said to me: “O Abu Hurayrah, what happened to your captive?” I said: O Messenger of Allah ﷺ, he complained of severe need and dependents, so I had mercy on him and let him go. He said: “Indeed, he lied to you, and he will return.” So I lay in wait for him a third time. He came scooping from the food, so I seized him and said: I will take you to the Messenger of Allah ﷺ, and this is the last of three times that you claim you will not return, yet you return. He said: Leave me, and I will teach you words by which Allah will benefit you. I said: What are they? He said: When you go to your bed, recite Ayat al-Kursi, “Allah, there is no god but Him, the Ever-Living, the Sustainer,” until you finish the verse. Then there will remain over you from Allah a guardian, and no devil will come near you until morning. So I let him go. In the morning the Messenger of Allah ﷺ said to me: “What happened to your captive last night?” I said: O Messenger of Allah ﷺ, he claimed that he would teach me words by which Allah would benefit me, so I let him go. He said: “What are they?” I said: He told me, when you go to your bed, recite Ayat al-Kursi from its beginning until you complete the verse, “Allah, there is no god but Him, the Ever-Living, the Sustainer.” And he told me: There will remain over you from Allah a guardian, and no devil will come near you until morning. And they were very eager for good. So the Prophet ﷺ said: “Indeed, he told you the truth though he is a great liar. Do you know whom you have been speaking to for the last three nights, O Abu Hurayrah?” He said: No. He said: “That was a devil.”"]},"intro":{"ar":["قال الله تعالى: { إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا } [سورة التوبة: ٦٠]."],"en":["Allah the Exalted said: “Charities are only for the poor, the needy, and those employed to collect and distribute them.” [Al-Tawbah: 60]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8237],"tks":"صحيح: رواه البخاري (2311) تعليقا، ووصله النسائي في الكبرى (10729)، وابن خزيمة (2424)."},{"num":5531,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُ دِينَارًا يَشْتَرِي بِهِ شَاةً، فَاشْتَرَى لَهُ بِهِ شَاتَيْنِ، فَبَاعَ إِحْدَاهُمَا بِدِينَارٍ، وَجَاءَهُ بِدِينَارٍ وَشَاةٍ، فَدَعَا لَهُ بِالْبَرَكَةِ فِي بَيْعِهِ، وَكَانَ لَوِ اشْتَرَى التُّرَابَ لَرَبِحَ فِيهِ."],"takhrij":"صحيح: رواه البخاري في المناقب (3642) عن علي بن عبد الله، أخبرنا سفيان، حدثنا شبيب بن غرقدة قال: سمعت الحي يحدثون عن عروة فذكره.","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3642).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Urwah al-Bariqi narrated that the Prophet ﷺ gave him one dinar to buy a sheep for him. So he bought two sheep with it, then sold one of them for one dinar, and came back to him with one dinar and one sheep. So he supplicated for blessing in his trade, and he would have made profit even if he had bought dust."]},"intro":{"ar":["قال الله تعالى: { فَابْعَثُوا أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِ إِلَى الْمَدِينَةِ فَلْيَنظُرْ أَيُّهَا أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ } [سورة الكهف: ١٩]."],"en":["Allah the Exalted said: “So send one of you with this silver coin of yours to the city, and let him look which food is purest, then let him bring you provision from it.” [Al-Kahf: 19]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9701],"tks":"صحيح: رواه البخاري (3642)."},{"num":5532,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَهُ يُحَدِّثُ، قَالَ: أَرَدْتُ الْخُرُوجَ إِلَى خَيْبَرَ، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَلَّمْتُ عَلَيْهِ، وَقُلْتُ لَهُ: إِنِّي أَرَدْتُ الْخُرُوجَ إِلَى خَيْبَرَ. فَقَالَ: إِذَا أَتَيْتَ وَكِيلِي فَخُذْ مِنْهُ خَمْسَةَ عَشَرَ وَسْقًا، فَإِنِ ابْتَغَى مِنْكَ آيَةً فَضَعْ يَدَكَ عَلَى تَرْقُوَتِهِ."],"takhrij":"صحيح: رواه أبو داود (3632)، وعنه البيهقي (11432)، والدارقطني (4304) عن عبيدالله بن سعد بن إبراهيم، ثنا عمي، ثنا أبي، عن أبي إسحاق، عن أبي نعيم وهب بن كيسان، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3632), and also by al-Bayhaqi (6/80) and al-Daraqutni (4/154).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn Abd Allah said: I wanted to go out to Khaybar, so I came to the Messenger of Allah ﷺ, greeted him, and said to him: I intend to go to Khaybar. He said: “When you come to my agent, take fifteen wasqs from him, and if he asks you for a sign, then place your hand on his collarbone.”"]},"buhuth":{"en":["His statement, “on his collarbone,” refers to the bone between the hollow of the throat and the shoulder. A person has two collarbones, one on each side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3632)، وعنه البيهقي (11432)، والدارقطني (4304)."},{"num":5533,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ الهوزني قَالَ: لَقِيتُ بِلاَلاً مُؤَذِّنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَلَبَ، فَقُلْتُ: يَا بِلاَلُ حَدِّثْنِي كَيْفَ كَانَتْ نَفَقَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَا كَانَ لَهُ شَىْءٌ. كُنْتُ أَنَا الَّذِي أَلِي ذَلِكَ مِنْهُ مُنْذُ بَعَثَهُ اللَّهُ إِلَى أَنْ تُوُفِّيَ، وَكَانَ إِذَا أَتَاهُ الإِنْسَانُ مُسْلِمًا فَرَآهُ عَارِيًا يَأْمُرُنِي، فَأَنْطَلِقُ فَأَسْتَقْرِضُ، فَأَشْتَرِي لَهُ الْبُرْدَةَ، فَأَكْسُوهُ، وَأُطْعِمُهُ حَتَّى اعْتَرَضَنِي رَجُلٌ مِنَ الْمُشْرِكِينَ، فَقَالَ: يَا بِلاَلُ، إِنَّ عِنْدِي سَعَةً فَلاَ تَسْتَقْرِضْ مِنْ أَحَدٍ إِلاَّ مِنِّي، فَفَعَلْتُ، فَلَمَّا أَنْ كَانَ ذَاتَ يَوْمٍ تَوَضَّأْتُ، ثُمَّ قُمْتُ لأُؤَذِّنَ بِالصَّلاَةِ، فَإِذَا الْمُشْرِكُ قَدْ أَقْبَلَ فِي عِصَابَةٍ مِنَ التُّجَّارِ، فَلَمَّا أَنْ رَآنِي قَالَ: يَا حَبَشِيُّ. قُلْتُ: يَا لَبَّاهُ. فَتَجَهَّمَنِي، وَقَالَ لِي قَوْلاً غَلِيظًا، وَقَالَ لِي: أَتَدْرِي كَمْ بَيْنَكَ وَبَيْنَ الشَّهْرِ؟ قَالَ: قُلْتُ: قَرِيبٌ. قَالَ: إِنَّمَا بَيْنَكَ وَبَيْنَهُ أَرْبَعٌ، فَآخُذُكَ بِالَّذِي عَلَيْكَ، فَأَرُدُّكَ تَرْعَى الْغَنَمَ كَمَا كُنْتَ قَبْلَ ذَلِكَ، فَأَخَذَ فِي نَفْسِي مَا يَأْخُذُ فِي أَنْفُسِ النَّاسِ حَتَّى إِذَا صَلَّيْتُ الْعَتَمَةَ رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِهِ، فَاسْتَأْذَنْتُ عَلَيْهِ، فَأَذِنَ لِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، بِأَبِي أَنْتَ وَأُمِّي إِنَّ الْمُشْرِكَ الَّذِي كُنْتُ أَتَدَيَّنُ مِنْهُ قَالَ لِي كَذَا وَكَذَا، وَلَيْسَ عِنْدَكَ مَا تَقْضِي عَنِّي وَلاَ عِنْدِي، وَهُوَ فَاضِحِي، فَأْذَنْ لِي أَنْ آبِقَ إِلَى بَعْضِ هَؤُلاَءِ الأَحْيَاءِ الَّذِينَ قَدْ أَسْلَمُوا حَتَّى يَرْزُقَ اللَّهُ رَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا يَقْضِي عَنِّي، فَخَرَجْتُ حَتَّى إِذَا أَتَيْتُ مَنْزِلِي، فَجَعَلْتُ سَيْفِي وَجِرَابِي وَنَعْلِي وَمِجَنِّي عِنْدَ رَأْسِي، حَتَّى إِذَا انْشَقَّ عَمُودُ الصُّبْحِ الأَوَّلِ أَرَدْتُ أَنْ أَنْطَلِقَ، فَإِذَا إِنْسَانٌ يَسْعَى يَدْعُو: يَا بِلاَلُ، أَجِبْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ حَتَّى أَتَيْتُهُ، فَإِذَا أَرْبَعُ رَكَائِبَ مُنَاخَاتٍ عَلَيْهِنَّ أَحْمَالُهُنَّ، فَاسْتَأْذَنْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبْشِرْ، فَقَدْ جَاءَكَ اللَّهُ بِقَضَائِكَ. ثُمَّ قَالَ: أَلَمْ تَرَ الرَّكَائِبَ الْمُنَاخَاتِ الأَرْبَعَ. فَقُلْتُ: بَلَى. فَقَالَ: إِنَّ لَكَ رِقَابَهُنَّ وَمَا عَلَيْهِنَّ، فَإِنَّ عَلَيْهِنَّ كِسْوَةً وَطَعَامًا أَهْدَاهُنَّ إِلَىَّ عَظِيمُ فَدَكَ، فَاقْبِضْهُنَّ، وَاقْضِ دَيْنَكَ. فَفَعَلْتُ. فَذَكَرَ الْحَدِيثَ. ثُمَّ انْطَلَقْتُ إِلَى الْمَسْجِدِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ فِي الْمَسْجِدِ، فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مَا فَعَلَ مَا قِبَلَكَ. قُلْتُ: قَدْ قَضَى اللَّهُ كُلَّ شَىْءٍ كَانَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَبْقَ شَىْءٌ. قَالَ: أَفَضَلَ شَىْءٌ. قُلْتُ: نَعَمْ. قَالَ: انْظُرْ أَنْ تُرِيحَنِي مِنْهُ، فَإِنِّي لَسْتُ بِدَاخِلٍ عَلَى أَحَدٍ مِنْ أَهْلِي حَتَّى تُرِيحَنِي مِنْهُ. فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَتَمَةَ دَعَانِي، فَقَالَ: مَا فَعَلَ الَّذِي قِبَلَكَ. قَالَ: قُلْتُ: هُوَ مَعِي لَمْ يَأْتِنَا أَحَدٌ. فَبَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، وَقَصَّ الْحَدِيثَ. حَتَّى إِذَا صَلَّى الْعَتَمَةَ - يَعْنِي مِنَ الْغَدِ - دَعَانِي قَالَ: مَا فَعَلَ الَّذِي قِبَلَكَ. قَالَ: قُلْتُ: قَدْ أَرَاحَكَ اللَّهُ مِنْهُ يَا رَسُولَ اللَّهِ. فَكَبَّرَ، وَحَمِدَ اللَّهَ شَفَقًا مِنْ أَنْ يُدْرِكَهُ الْمَوْتُ، وَعِنْدَهُ ذَلِكَ. ثُمَّ اتَّبَعْتُهُ حَتَّى إِذَا جَاءَ أَزْوَاجَهُ فَسَلَّمَ عَلَى امْرَأَةٍ امْرَأَةٍ، حَتَّى أَتَى مَبِيتَهُ. فَهَذَا الَّذِي سَأَلْتَنِي عَنْهُ."],"takhrij":"صحيح: رواه أبو داود (3055) عن أبي توبة الربيع بن نافع، حدثنا معاوية –يعني ابن سلام-، عن زيد أنه سمع أبا سلام قال: حدثني عبد الله الهوزني فذكره.","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3055), authenticated by Ibn Hibban (6351), and narrated by al-Bayhaqi (6/80).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abd Allah al-Hawzani said: I met Bilal, the caller to prayer of the Messenger of Allah ﷺ, in Aleppo, and I said: O Bilal, tell me how the spending of the Messenger of Allah ﷺ used to be. He said: He had nothing. I was the one in charge of that for him from the time Allah sent him until he passed away. Whenever a Muslim came to him and he saw him unclothed, he would command me, and I would go borrow something and buy a cloak for him, clothe him, and feed him. Then a man from the polytheists approached me and said: O Bilal, I have wealth, so do not borrow from anyone except me. So I did that. Then one day I made wudu and stood to call the prayer, and suddenly that polytheist came with a group of merchants. When he saw me he said: O Abyssinian. I said: At your service. He frowned at me, spoke harshly to me, and said: Do you know how much time remains between you and the month? I said: It is near. He said: Only four days remain, then I will seize you for what you owe and return you to herding sheep as you used to do before. That affected me the way such words affect people, until after I prayed the night prayer and the Messenger of Allah ﷺ returned to his family, I sought permission to enter upon him and he permitted me. I said: O Messenger of Allah ﷺ, may my father and mother be sacrificed for you, the polytheist from whom I used to borrow said this and this to me. Neither you nor I have what can pay off my debt, and he is going to disgrace me, so permit me to flee to one of these clans who have accepted Islam until Allah provides His Messenger ﷺ with what can settle my debt. I left until I reached my home and placed my sword, my bag, my sandals, and my shield by my head. Then when the first light of dawn broke, I intended to depart, but suddenly a man came running and calling: O Bilal, answer the Messenger of Allah ﷺ. So I went to him, and there were four kneeling camels loaded with goods. I sought permission to enter, and the Messenger of Allah ﷺ said to me: “Rejoice, for Allah has brought you what will settle your debt.” Then he said: “Did you not see the four loaded camels kneeling there?” I said: Yes. He said: “They, and what is on them, are for you, for they carry clothing and food gifted to me by the chief of Fadak, so take them and pay your debt.” So I did so. Then I went to the mosque and found the Messenger of Allah ﷺ sitting there. I greeted him and he said: “What happened to what was due from you?” I said: Allah has settled everything that was due from the Messenger of Allah ﷺ, and nothing remains. He said: “Is anything left over?” I said: Yes. He said: “See that you relieve me of it, for I will not enter upon any of my family until you relieve me of it.” Then after the Messenger of Allah ﷺ prayed the night prayer, he called me and said: “What happened to what remained with you?” I said: It is still with me; no one has come to us. So the Messenger of Allah ﷺ spent the night in the mosque. He continued the story and said: Then after he prayed the night prayer the next day, he called me and said: “What happened to what remained with you?” I said: Allah has relieved you of it, O Messenger of Allah ﷺ. So he said the takbir and praised Allah, fearing that death might reach him while that wealth was still with him. Then I followed him until he came to his wives, greeting each woman one by one, until he reached his sleeping place. This is what you asked me about."]},"buhuth":{"en":["His saying “yalabbah” means “here I am” or “at your service.” His saying “he frowned at me” means he met me with an unpleasant face. “My shield” comes from “mijan,” meaning a shield. And “shafaqan” here means fear."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3055)، وصححه ابن حبان (6351)، والبيهقي (11435)."},{"num":5534,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا، أَوْ يَزْرَعُ زَرْعًا، فَيَأْكُلُ مِنْهُ طَيْرٌ أَوْ إِنْسَانٌ أَوْ بَهِيمَةٌ، إِلاَّ كَانَ لَهُ بِهِ صَدَقَةٌ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2320)، ومسلم في المساقاة (1553: 12) كلاهما من طريق أبي عوانة، عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2320) and Muslim (1553:12).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “No Muslim plants a tree or sows a crop, and then a bird, a person, or an animal eats from it, except that it is counted for him as charity.”"]}},"tuhfa":{},"full":1,"rep":[13490],"tks":"متفق عليه: رواه البخاري (2320)، ومسلم (1553: 12)."},{"num":5535,"demo":false,"sanad":"","matn":["عن أنس أن النبي صلى الله عليه وسلم دخل نخلا لأم مبشر امرأة من الأنصار، فقال رسول الله صلى الله عليه وسلم: من غرس هذا النخل؟ أمسلم أم كافر؟. قالوا: مسلم. فقال: لا يغرس مسلم غرسا، فأكل منه إنسان أو طير أو دابة إلا كانت صدقة."],"takhrij":"متفق عليه: رواه مسلم في المساقاة (1553: 13) عن عبد بن حميد، حدثنا مسلم بن إبراهيم، حدثنا أبان بن يزيد، حدثنا قتادة، حدثنا أنس بن مالك فذكره. ورواه البخاري (2320)، وقال: قال لنا مسلم حدثنا أبان، حدثنا قتادة، حدثنا أنس، عن النبي صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1553:13) and al-Bukhari (2320).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ entered a date-palm grove belonging to Umm Mubashshir, a woman from the Ansar, and the Messenger of Allah ﷺ said: “Who planted these palm trees? Was it a Muslim or a disbeliever?” They said: A Muslim. He said: “No Muslim plants a tree, and then a person, a bird, or an animal eats from it, except that it is charity for him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مسلم (1553: 13)، والبخاري (2320)."},{"num":5536,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ قَامَتْ عَلَى أَحَدِكُمُ الْقِيَامَةُ، وَفِي يَدِهِ فَسِيلَةٌ فَلْيَغْرِسْهَا."],"takhrij":"حسن: رواه الإمام أحمد (12902) والبزار –كشف الأستار (1251) والبخاري في الأدب المفرد (479) كلهم من حديث حماد بن سلمة، عن هشام بن زيد بن أنس، عن أنس، فذكره. وإسناده صحيح.","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (12902), al-Bazzar in Kashf al-Astar (1251), and al-Bukhari in al-Adab al-Mufrad (479).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “If the Final Hour comes while one of you has a small palm shoot in his hand, then let him plant it.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه الإمام أحمد (12902)، والبزار - كشف الأستار (1251)، والبخاري في الأدب المفرد (479)."},{"num":5537,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أُمِّ مُبَشِّرٍ الْأَنْصَارِيَّةِ فِي نَخْلٍ لَهَا، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ غَرَسَ هَذَا النَّخْلَ؟ أَمُسْلِمٌ أَمْ كَافِرٌ؟ فَقَالَتْ: بَلْ مُسْلِمٌ، فَقَالَ: لَا يَغْرِسُ مُسْلِمٌ غَرْسًا، وَلَا يَزْرَعُ زَرْعًا، فَيَأْكُلَ مِنْهُ إِنْسَانٌ وَلَا دَابَّةٌ وَلَا شَيْءٌ، إِلَّا كَانَتْ لَهُ صَدَقَةٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1552: 8) من طرق عن الليث، عن أبي الزبير، عن جابر فذكره. وفي رواية عنده: عن ابن جريج قال: أخبرني أبو الزبير أنه سمع جابرا يقول فذكر الحديث.","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:8).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir narrated that the Prophet ﷺ entered upon Umm Mubashshir al-Ansariyyah in a grove of hers and said to her: “Who planted these palm trees? Was it a Muslim or a disbeliever?” She said: Rather, a Muslim. He said: “No Muslim plants a tree or sows a crop, and then a person, an animal, or anything else eats from it, except that it is charity for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1552: 8)."},{"num":5538,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أُمِّ مَعْبَدٍ حَائِطًا، فَقَالَ: يَا أُمَّ مَعْبَدٍ، مَنْ غَرَسَ هَذَا النَّخْلَ؟ أَمُسْلِمٌ، أَمْ كَافِرٌ؟. فَقَالَتْ: بَلْ مُسْلِمٌ، قَالَ: فَلَا يَغْرِسُ الْمُسْلِمُ غَرْسًا، فَيَأْكُلَ مِنْهُ إِنْسَانٌ، وَلَا دَابَّةٌ، وَلَا طَيْرٌ، إِلَّا كَانَ لَهُ صَدَقَةً إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1552: 10) عن أحمد بن سعيد بن إبراهيم، حدثنا روح بن عبادة، حدثنا زكريا بن إسحاق، أخبرني عمرو بن دينار، أنه سمع جابر بن عبد الله يقول فذكره.","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:10).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Prophet ﷺ entered a garden belonging to Umm Mabd and said: “O Umm Mabd, who planted these palm trees? Was it a Muslim or a disbeliever?” She said: Rather, a Muslim. He said: “No Muslim plants a tree, and then a person, an animal, or a bird eats from it, except that it will be charity for him until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1552: 10)."},{"num":5539,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا إِلَّا كَانَ مَا أُكِلَ مِنْهُ لَهُ صَدَقَةً، وَمَا سُرِقَ مِنْهُ لَهُ صَدَقَةٌ، وَمَا أَكَلَ السَّبُعُ مِنْهُ فَهُوَ لَهُ صَدَقَةٌ، وَمَا أَكَلَتِ الطَّيْرُ فَهُوَ لَهُ صَدَقَةٌ، وَلَا يَرْزَؤُهُ أَحَدٌ إِلَّا كَانَ لَهُ صَدَقَةٌ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1252: 7) عن ابن نمير، حدثنا أبي، حدثنا عبد الملك، عن عطاء، عن جابر قال فذكره.","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:7).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “No Muslim plants a tree except that whatever is eaten from it is charity for him, whatever is stolen from it is charity for him, whatever a wild beast eats from it is charity for him, whatever birds eat from it is charity for him, and no one diminishes it in any way except that it is charity for him.”"]}},"tuhfa":{},"full":1,"rep":[4157],"tks":"صحيح: رواه مسلم (7:1552)."},{"num":5540,"demo":false,"sanad":"","matn":["عَنْ السَّائِبِ بن خلاد قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ زَرَعَ زَرْعًا، فَأَكَلَ مِنْهُ الطَّيْرُ أَوِ الْعَافِيَةُ كَانَ لَهُ بِهِ صَدَقَةٌ."],"takhrij":"حسن: رواه الإمام أحمد (16558) عن وكيع قال: حدثنا أسامة بن زيد، عن المطلب بن عبد الله بن حنطب، عن خلاد بن السائب، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (16558).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Al-Sa’ib ibn Khallad said: The Messenger of Allah ﷺ said: “Whoever sows a crop, and birds or creatures seeking provision eat from it, it will be charity for him.”"]},"buhuth":{"en":["The word “al-afiyah” here means every creature that seeks provision."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16558)."},{"num":5541,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، أَنَّ رَجُلًا، مَرَّ بِهِ وَهُوَ يَغْرِسُ غَرْسًا بِدِمَشْقَ، فَقَالَ لَهُ: أَتَفْعَلُ هَذَا وَأَنْتَ صَاحِبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: لَا تَعْجَلْ عَلَيَّ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ غَرَسَ غَرْسًا لَمْ يَأْكُلْ مِنْهُ آدَمِيٌّ، وَلَا خَلْقٌ مِنْ خَلْقِ اللهِ عَزَّ وَجَلَّ إِلَّا كَانَ لَهُ صَدَقَةً."],"takhrij":"حسن: رواه أحمد (27506) عن على بن بحر حدثنا بقية قال: حدثنا ثابت بن عجلان قال: حدثني القاسم مولى بني يزيد، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27506).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu al-Darda said that a man passed by him while he was planting something in Damascus and said to him: Are you doing this while you are a Companion of the Messenger of Allah ﷺ? He said: Do not be hasty with me. I heard the Messenger of Allah ﷺ say: “Whoever plants a tree, and no human or any creature from Allah’s creation eats from it except that it is charity for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27506)."},{"num":5542,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ،، قَالَ ـ وَرَأَى سِكَّةً وَشَيْئًا مِنْ آلَةِ الْحَرْثِ، فَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ يَدْخُلُ هَذَا بَيْتَ قَوْمٍ إِلاَّ أُدْخِلَهُ الذُّلُّ. قَالَ أَبُو عَبْد اللَّهِ وَاسْمُ."],"takhrij":"صحيح: رواه البخاري في الحرث والمزارعة (2321) عن عبدالله بن يوسف، حدثنا عبد الله بن سالم الحمصي، حدثنا محمد بن زياد الألهاني، عن أبي أمامة الباهلي فذكره.","grade":"صحيح","chapter_ar":"باب الاقتصاد في الزراعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2321).","chapter_en":"Moderation in farming","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Abu Umamah al-Bahili said — when he saw a plowshare and some farming tools —: I heard the Prophet ﷺ say: “This does not enter the house of a people except that Allah causes humiliation to enter it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2321)."},{"num":5543,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ أَبِيهِ، قَالَ: قَالَ عُمَرُ: رَضِيَ اللَّهُ عَنْهُ لَوْلاَ آخِرُ الْمُسْلِمِينَ مَا فَتَحْتُ قَرْيَةً إِلاَّ قَسَمْتُهَا بَيْنَ أَهْلِهَا، كَمَا قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ."],"takhrij":"صحيح: رواه البخاري في الحرث والمزارعة (2334) عن صدقة، أخبرنا عبد الرحمن (هو ابن مهدي)، عن مالك، عن زيد بن أسلم به.","grade":"صحيح","chapter_ar":"باب تقسيم الإمام الأرض المفتوحة عنوة على الفاتحين للزراعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2334).","chapter_en":"The ruler’s distribution of land conquered by force among the conquerors for cultivation","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Aslam narrated from his father that Umar said: “Were it not for the later Muslims, I would not conquer any town except that I would divide it among those who conquered it, just as the Prophet ﷺ divided Khaybar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2334)."},{"num":5544,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ لِرِجَالٍ مِنَّا فُضُولُ أَرَضِينَ، فَقَالُوا: نُؤَاجِرُهَا بِالثُّلُثِ وَالرُّبُعِ وَالنِّصْفِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا أَوْ لِيَمْنَحْهَا أَخَاهُ، فَإِنْ أَبَى فَلْيُمْسِكْ أَرْضَهُ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2340، 2632)، ومسلم في البيوع (1536: 89) كلاهما من حديث الأوزاعي قال: حدثني عطاء، عن جابر فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2632, 2340) and Muslim (1536:89). The wording is al-Bukhari’s.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Jabir said: Some men among us had extra plots of land, and they said: We will lease them out for one-third, one-fourth, or one-half. So the Prophet ﷺ said: “Whoever has land should cultivate it himself or grant it to his brother. If he refuses, then let him keep his land.”"]},"buhuth":{"en":["In Muslim’s wording: “Whoever has surplus land should cultivate it or grant it to his brother. If he refuses, then let him keep his land.”","Here are the wordings narrated by Muslim in his Sahih:","“Whoever has land should gift it, or let it be cultivated.”","“Whoever has land should cultivate it or let his brother cultivate it, otherwise let him leave it.”","“Whoever has land should cultivate it. If he does not cultivate it, let him grant it to his brother. If he does not grant it to his brother, then let him keep it.”","“The Messenger of Allah ﷺ forbade selling produce for years ahead, for two or three years.”","“The Messenger of Allah ﷺ forbade muhaqalah, muzabanah, muagwamah, mukhabarah, and exception clauses, but permitted araya sales.”","“Whoever has land should cultivate it or let his brother cultivate it, and should not rent it out.”","“Whoever has land should cultivate it. If he cannot cultivate it and is unable to do so, then let him grant it to his Muslim brother, and not lease it to him.”","“Whoever has land should cultivate it, and if he does not cultivate it, then let his brother cultivate it.”","“The Messenger of Allah ﷺ forbade that land should have a rent or assigned share taken for it.”","“The Prophet ﷺ forbade renting out land.”","“Indeed the Prophet ﷺ forbade renting out land.”","“The Prophet ﷺ forbade selling for future years.”","“The Messenger of Allah ﷺ forbids muzabanah and muhaqalah.” Jabir said: Muzabanah is selling fresh fruit for dried dates, and muhaqalah is renting land.","“Whoever has land should cultivate it or let another man cultivate it.”","“The Prophet ﷺ forbade mukhabarah.”","The conclusion is that Jabir ibn Abd Allah’s hadith regarding the prohibition of renting out land is understood as discouragement, not strict prohibition, because gifting, lending, and granting land are not obligatory. But some narrators narrated by meaning, so their wordings differed, until some people thought it meant prohibition and narrated it with the wording: “Whoever does not abandon mukhabarah, then let him be warned of war from Allah and His Messenger.” Narrated by Abu Dawud (3406), and it is uncommon."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2632، 2340)، ومسلم (1536: 89)، واللفظ للبخاري."},{"num":5545,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا، أَوْ لِيَمْنَحْهَا أَخَاهُ، فَإِنْ أَبَى فَلْيُمْسِكْ أَرْضَهُ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2341)، ومسلم في البيوع (1544) كلاهما من طريق أبي توبة الربيع بن نافع، حدثنا معاوية، عن يحيى بن أبي كثير، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2341) and Muslim (1544).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever has land should cultivate it, or grant it to his brother. If he refuses, then let him keep his land.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2341)، ومسلم (1544)."},{"num":5546,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ."],"takhrij":"صحيح: رواه مسلم في البيوع (1545) عن قتيبة بن سعيد، حدثنا يعقوب (يعني ابن عبد الرحمن القاري)، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1545).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade muhaqalah and muzabanah."]}},"tuhfa":{},"full":1,"rep":[5739],"tks":"صحيح: رواه مسلم (1545)."},{"num":5547,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ  أَنَّ ابْنَ عُمَرَ كَانَ يُكْرِي مَزَارِعَهُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَفِي إِمَارَةِ أَبِي بَكْرٍ، وَعُمَرَ، وَعُثْمَانَ، وَصَدْرًا مِنْ خِلَافَةِ مُعَاوِيَةَ، حَتَّى بَلَغَهُ فِي آخِرِ خِلَافَةِ مُعَاوِيَةَ أَنَّ رَافِعَ بْنَ خَدِيجٍ يُحَدِّثُ فِيهَا بِنَهْيٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَخَلَ عَلَيْهِ وَأَنَا مَعَهُ، فَسَأَلَهُ، فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ كِرَاءِ الْمَزَارِعِ، فَتَرَكَهَا ابْنُ عُمَرَ بَعْدُ، وَكَانَ إِذَا سُئِلَ عَنْهَا بَعْدُ قَالَ: زَعَمَ رَافِعُ بْنُ خَدِيجٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (3343-3344)، ومسلم في البيوع (1547: 109) كلاهما من طريق أيوب، عن نافع به. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2344–2343) and Muslim (1547:109). The wording is Muslim’s.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi narrated that Ibn Umar used to lease out his farmlands during the time of the Messenger of Allah ﷺ, and during the rule of Abu Bakr, Umar, Uthman, and the early part of Muawiyah’s caliphate, until near the end of Muawiyah’s rule he learned that Rafi ibn Khadij was narrating concerning it a prohibition from the Prophet ﷺ. So he went to him — and I was with him — and asked him. He said: The Messenger of Allah ﷺ used to forbid leasing out farmlands. So Ibn Umar stopped doing it after that. Whenever he was asked about it later, he would say: Rafi ibn Khadij claimed that the Messenger of Allah ﷺ forbade it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3343-3344)، ومسلم (1547:109). واللفظ لمسلم."},{"num":5548,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ  أَنَّ ابْنَ عُمَرَ كَانَ يَأْجُرُ الْأَرْضَ، قَالَ: فَنُبِّئَ حَدِيثًا عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ: فَانْطَلَقَ بِي مَعَهُ إِلَيْهِ، قَالَ: فَذَكَرَ عَنْ بَعْضِ عُمُومَتِهِ، ذَكَرَ فِيهِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنْ كِرَاءِ الْأَرْضِ، قَالَ: فَتَرَكَهُ ابْنُ عُمَرَ، فَلَمْ يَأْجُرْهُ."],"takhrij":"صحيح: رواه مسلم (1547: 111) عن محمد بن المثنى، حدثنا حسين (يعني ابن حسن بن يسار)، حدثنا ابن عون، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1547:111). I say: His leaving it was out of caution and dislike, not because of absolute prohibition, and this is also the view of Ibn Abbas, as will come later.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi narrated that Ibn Umar used to lease out land. Then he was informed of a hadith from Rafi ibn Khadij. He said: So he took me with him to go to him. He then mentioned from some of his paternal uncles a report from the Prophet ﷺ that he forbade leasing land. So Ibn Umar left it and did not lease it out."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1547:111). قلت: تركه كان تنزيها، لا تحريما، وعليه قول ابن عباس، كما سيأتي."},{"num":5549,"demo":false,"sanad":"","matn":["عن سالم بن عَبْدِ اللَّهِ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ كَانَ يُكْرِي أَرَضِيهِ، حَتَّى بَلَغَهُ أَنَّ رَافِعَ بْنَ خَدِيجٍ الْأَنْصَارِيَّ كَانَ يَنْهَى عَنْ كِرَاءِ الْأَرْضِ، فَلَقِيَهُ عَبْدُ اللَّهِ، فَقَالَ: يَا ابْنَ خَدِيجٍ، مَاذَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كِرَاءِ الْأَرْضِ؟ قَالَ رَافِعُ بْنُ خَدِيجٍ لِعَبْدِ اللَّهِ: سَمِعْتُ عَمَّيَّ، وَكَانَا قَدْ شَهِدَا بَدْرًا، يُحَدِّثَانِ أَهْلَ الدَّارِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ كِرَاءِ الْأَرْضِ.","قَالَ عَبْدُ اللهِ: لَقَدْ كُنْتُ أَعْلَمُ فِي عَهْدِ رَسُولِ اللهِ صلى الله عليه وسلم أَنَّ الْأَرْضَ تُكْرَى، ثُمَّ خَشِيَ عَبْدُ اللهِ أَنْ يَكُونَ رَسُولُ اللهِ صلى الله عليه وسلم أَحْدَثَ فِي ذَلِكَ شَيْئًا لَمْ يَكُنْ عَلِمَهُ، فَتَرَكَ كِرَاءَ الْأَرْضِ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2345)، ومسلم (1547: 12) كلاهما من حديث الليث قال: حدثني عقيل بن خالد، عن ابن شهاب أنه قال: أخبرني سالم بن عبدالله فذكره. واللفظ لمسلم، ولفظ البخاري مختصر.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2345) and Muslim (1547/112). This is Muslim’s wording.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Sālim ibn ʿAbdullāh reported: ʿAbdullāh ibn ʿUmar used to lease out his lands until he learned that Rāfiʿ ibn Khadīj al-Anṣārī prohibited the leasing of land. ʿAbdullāh met him and asked: “O Ibn Khadīj, what do you narrate from the Messenger of Allah ﷺ concerning the leasing of land?” Rāfiʿ ibn Khadīj said to ʿAbdullāh: “I heard my two paternal uncles—both of whom had participated in Badr—telling the people of the household that the Messenger of Allah ﷺ prohibited leasing land.” ʿAbdullāh said: “I certainly knew during the lifetime of the Messenger of Allah ﷺ that land was leased.”","Then ʿAbdullāh feared that the Messenger of Allah ﷺ might subsequently have issued a ruling concerning it of which he had not been aware, so he stopped leasing land."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2345)، ومسلم (1547/112)، واللفظ لمسلم."},{"num":5550,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ قَالَ:  ذَهَبْتُ مَعَ ابْنِ عُمَرَ، إِلَى رَافِعِ بْنِ خَدِيجٍ حَتَّى أَتَاهُ بِالْبَلَاطِ، فَأَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ كِرَاءِ الْمَزَارِعِ."],"takhrij":"صحيح: رواه مسلم (1546: 110) عن ابن نمير، حدثنا أبي، حدثنا عبيدالله، عن نافع قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1546:110).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi said: I went with Ibn Umar to Rafi ibn Khadij until he came to him at al-Bilat, and he informed him that the Messenger of Allah ﷺ had forbidden leasing out farmlands."]},"buhuth":{"en":["Al-Bilat was a known place in Madinah paved with stones, near the mosque of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1546:110)."},{"num":5551,"demo":false,"sanad":"","matn":["عن ظُهير بن رَافِعٍ قَالَ: ظُهَيْرٌ لَقَدْ نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَمْرٍ كَانَ بِنَا رَافِقًا. قُلْتُ: مَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهْوَ حَقٌّ. قَالَ: دَعَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا تَصْنَعُونَ بِمَحَاقِلِكُمْ. قُلْتُ: نُؤَاجِرُهَا عَلَى الرُّبُعِ وَعَلَى الأَوْسُقِ مِنَ التَّمْرِ وَالشَّعِيرِ. قَالَ: لا تَفْعَلُوا، ازْرَعُوهَا، أَوْ أَزْرِعُوهَا، أَوْ أَمْسِكُوهَا. قَالَ رَافِعٌ: قُلْتُ: سَمْعًا وَطَاعَةً."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2339)، ومسلم في البيوع (1548: 114) كلاهما من طريق الأوزاعي، عن أبي النجاشي مولى رافع بن خديج، قال: سمعت رافع بن خديج بن رافع، عن عمه ظهير بن رافع، قال ظهير فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2339) and Muslim (1548:114). The wording is al-Bukhari’s.","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Zuhayr ibn Rafi said: The Messenger of Allah ﷺ forbade us from something that had been beneficial for us. I said: Whatever the Messenger of Allah ﷺ said is the truth. He said: The Messenger of Allah ﷺ called me and said, “What do you do with your cultivated lands?” I said: We lease them out for the produce by the watercourse, or for measured amounts of dates and barley. He said: “Do not do that. Cultivate them yourselves, let others cultivate them, or keep them unused.” Rafi said: I said: We hear and obey."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2339)، ومسلم (1548:114). واللفظ للبخاري."},{"num":5552,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ:  كُنَّا نُحَاقِلُ الْأَرْضَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنُكْرِيهَا بِالثُّلُثِ وَالرُّبُعِ وَالطَّعَامِ الْمُسَمَّى، فَجَاءَنَا ذَاتَ يَوْمٍ رَجُلٌ مِنْ عُمُومَتِي، فَقَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَمْرٍ كَانَ لَنَا نَافِعًا، وَطَوَاعِيَةُ اللهِ وَرَسُولِهِ أَنْفَعُ لَنَا، نَهَانَا أَنْ نُحَاقِلَ بِالْأَرْضِ، فَنُكْرِيَهَا عَلَى الثُّلُثِ وَالرُّبُعِ وَالطَّعَامِ الْمُسَمَّى، وَأَمَرَ رَبَّ الْأَرْضِ أَنْ يَزْرَعَهَا، أَوْ يُزْرِعَهَا، وَكَرِهَ كِرَاءَهَا وَمَا سِوَى ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في البيوع (1548: 113) من طريق إسماعيل بن علية، عن أيوب، عن يعلى بن حكيم، عن سليمان بن يسار، عن رافع بن خديج قال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1548:113).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Rafi ibn Khadij said: We used to practice crop-sharing with land during the time of the Messenger of Allah ﷺ, leasing it out for one-third, one-fourth, or specified food. Then one day a man from my paternal uncles came to us and said: The Messenger of Allah ﷺ forbade us from something that had been beneficial for us, but obedience to Allah and His Messenger is more beneficial for us. He forbade us from leasing land for one-third, one-fourth, or specified food, and he instructed the owner of the land to cultivate it himself or let it be cultivated, and he disliked leasing it out and other such arrangements."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1548:113)."},{"num":5553,"demo":false,"sanad":"","matn":["عَنْ أُسَيْدِ بْنِ ظُهَيْرٍ ابْنُ أَخِي رَافِعِ بْنِ خَدِيجٍ قَالَ: كَانَ أَحَدُنَا إِذَا اسْتَغْنَى عَنْ أَرْضِهِ أَعْطَاهَا بِالثُّلُثِ وَالرُّبُعِ وَالنِّصْفِ، وَيَشْتَرِطُ ثَلَاثَ جَدَاوِلَ وَالْقُصَارَةَ وَمَا يسَقَي الرَّبِيعُ، وَكَانَ الْعَيْشُ إِذْ ذَاكَ شَدِيدًا، وَكَانَ يُعْمَلُ فِيهَا بِالْحَدِيدِ وَمَا شَاءَ اللَّهُ، وَيُصِيبُ مِنْهَا مَنْفَعَةً، فَأَتَانَا رَافِعُ بْنُ خَدِيجٍ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَاكُمْ عَنْ أَمْرٍ كَانَ لَكُمْ نَافِعًا، وَطَاعَةُ اللهِ وَطَاعَةُ رسوله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْفَعُ لَكُمْ. إنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَاكُمْ عَنِ الْحَقْلِ، وَيَقُولُ: مَنْ اسْتَغْنَى عَنْ أَرْضِهِ فَلْيَمْنَحْهَا أَخَاهُ، أَوْ لِيَدَعْ. وَيَنْهَاكُمْ عَنِ الْمُزَابَنَةِ. وَالْمُزَابَنَةُ أَنْ يَكُونَ الرَّجُلُ لَهُ الْمَالُ الْعَظِيمُ مِنَ النَّخْلِ، فَيَأْتِيهِ الرَّجُلُ، فَيَقُولُ: قَدْ أَخَذْتُهُ بِكَذَا وَكَذَا وَسْقًا مِنْ تَمْرٍ."],"takhrij":"صحيح: رواه أحمد (15815) عن عبد الرزاق –وهو في مصنفه (14463)- عن سفيان، عن منصور، عن مجاهد، عن أبيه، عن ظهير فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15815), Abd al-Razzaq in his Musannaf (14463), and Ibn Majah (2460).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Usayd ibn Zuhayr, the nephew of Rafi ibn Khadij, said: One of us, if he had no need for his land, would give it out for one-third, one-fourth, or one-half, while stipulating three irrigation channels, the leftover gleanings, and what the spring waters irrigated. Life at that time was hard, and the land was worked with iron tools and whatever Allah willed, and some benefit would be gained from it. Then Rafi ibn Khadij came to us and said: The Messenger of Allah ﷺ forbids you from something that had been beneficial for you, but obedience to Allah and obedience to His Messenger ﷺ are more beneficial for you. The Prophet ﷺ forbids you from field-renting, and says: “Whoever has no need of his land, let him grant it to his brother or leave it.” And he forbids you from muzabanah. Muzabanah is that a man has a large amount of palm produce, and another man comes to him and says: I take it for such-and-such measured amount of dried dates."]},"buhuth":{"en":["His saying, “three irrigation channels,” means three allotted shares from the small water channels. A jadwal is a small stream, meaning portions of land near its edges.","The word “al-qusarah,” with a dammah, means what remains of grain in the ear and is not fully separated after threshing.","And “what the spring waters irrigate” refers to a small stream, meaning they would assign a piece of land irrigated by that spring flow."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15815)، وعبد الرزاق في مصنفه (14463)، وابن ماجه (2460)."},{"num":5554,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُزَابَنَةِ، وَالْمُحَاقَلَةِ. وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ. وَالْمُحَاقَلَةُ كِرَاءُ الأَرْضِ بِالْحِنْطَةِ."],"takhrij":"متفق عليه: رواه مالك في البيوع (24) عن داود بن الحصين، عن أبي سفيان مولى ابن أبي أحمد، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (2186), and Muslim (1546).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Abu Said al-Khudri narrated that the Messenger of Allah ﷺ forbade muzabanah and muhaqalah. Muzabanah is purchasing fruit on the trees in exchange for dried dates, and muhaqalah is renting land in exchange for wheat."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5735],"tks":"متفق عليه: رواه مالك (24)، والبخاري (2186)، ومسلم (1546)."},{"num":5555,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ أَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْمُحَاقَلَةِ، وَالْمُزَابَنَةِ، والمخابرة، والثنيا إِلاَّ أَنْ تعلم."],"takhrij":"حسن: رواه أبو داود (3405)، والترمذي (1290)، والنسائي (3911) كلهم من حديث عباد بن العوام قال: أخبرني سفيان بن حسين، عن يونس بن عبيد، عن عطاء، عن جابر فذكره. قال الترمذي: \"حديث حسن صحيح غريب من هذا الوجه من حديث يونس بن عبيد، عن عطاء، عن جابر\".","grade":"حسن","chapter_ar":"باب النهي عن الثنيا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3405), al-Tirmidhi (1290), and al-Nasa’i (3911). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The prohibition of making an unspecified exception in a sale","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Jabir narrated that the Messenger of Allah ﷺ forbade muhaqalah, muzabanah, mukhabarah, and thunya, unless it is known."]},"buhuth":{"en":["Thunya means an unspecified exception in the sale, because it leads to dispute. If it is known, then there is no problem, such as when someone sells the fruit of an orchard and excludes a known portion like one-third or one-fourth. That is permissible. But if he excludes an unknown portion, the sale becomes invalid because the sale then becomes uncertain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري (2346)."},{"num":5556,"demo":false,"sanad":"","matn":["عَنْ حَنْظَلَةَ بْنِ قَيْسٍ، عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ: حَدَّثَنِي عَمَّاىَ، أَنَّهُمْ كَانُوا يُكْرُونَ الأَرْضَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا يَنْبُتُ عَلَى الأَرْبِعَاءِ، أَوْ شَىْءٍ يَسْتَثْنِيهِ صَاحِبُ الأَرْضِ، فَنَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ. فَقُلْتُ لِرَافِعٍ فَكَيْفَ هِيَ بِالدِّينَارِ وَالدِّرْهَمِ فَقَالَ رَافِعٌ لَيْسَ بِهَا بَأْسٌ بِالدِّينَارِ وَالدِّرْهَمِ."],"takhrij":"صحيح: رواه البخاري في الحرث والمزارعة (2346) عن عمرو بن خالد، حدثنا الليث، عن ربيعة بن أبي عبد الرحمن، عن حنظلة بن قيس فذكره.","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2346).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Hanzalah ibn Qays narrated from Rafi ibn Khadij, who said: My two paternal uncles told me that they used to lease land during the time of the Prophet ﷺ in exchange for what grew on the small channels or for some portion that the landowner excluded for himself, and the Prophet ﷺ forbade that. I said to Rafi: What about leasing it for dinars and dirhams? Rafi said: There is no harm in that with dinars and dirhams."]},"buhuth":{"en":["The word “al-arbia” is the plural of “ربيع” here, meaning a small stream or irrigation channel."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (1)، ومسلم (1547:115)."},{"num":5557,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ كِرَاءِ الْمَزَارِعِ. قَالَ حَنْظَلَةُ: فَسَأَلْتُ رَافِعَ بْنَ خَدِيجٍ بِالذَّهَبِ وَالْوَرِقِ؟ فَقَالَ: أَمَّا بِالذَّهَبِ وَالْوَرِقِ فَلاَ بَأْسَ بِهِ."],"takhrij":"صحيح: رواه مالك في كراء الأرض (1) عن ربيعة بن أبي عبد الرحمن، عن حنظلة بن قيس الزرقي، عن رافع بن خديج قال فذكره.","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (1) and Muslim (1547:115).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Rafi ibn Khadij narrated that the Messenger of Allah ﷺ forbade leasing out farmlands. Hanzalah said: So I asked Rafi ibn Khadij about gold and silver. He said: As for gold and silver, there is no harm in that."]},"buhuth":{"en":["Muslim also narrated it (1547:116) through Hanzalah ibn Qays al-Ansari, who said: I asked Rafi ibn Khadij about leasing land for gold and silver, and he said: There is no harm in it. The people in the time of the Prophet ﷺ used to lease based on the portions by the water channels, the fronts of the irrigation streams, and selected parts of the crops, so one part would be ruined while another would remain safe, or one would remain safe while the other would be ruined. The people had no leasing except this kind, so that is why it was forbidden. But as for something fixed and guaranteed, there is no harm in it.","In another wording: The people used to lease farmlands in the time of the Messenger of Allah ﷺ by the portions near the water channels, what the spring waters irrigated, and some of the straw. So the Messenger of Allah ﷺ disliked leasing farmland in this way and forbade it. Rafi said: There is no harm in leasing it for dirhams and dinars.","Narrated by Imam Ahmad (15809).","The word “al-madhiyanat,” with the dhal pronounced with kasrah, means streams or water channels, and it is not originally Arabic. It refers to what grows along their edges for the landowner.","“And aqbal al-jadawil” means the beginnings and heads of the irrigation streams. Jadawil is the plural of jadwal, which means a small stream."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2327)."},{"num":5558,"demo":false,"sanad":"","matn":["عن رَافِعِ بن خَدِيجٍ قَالَ: كُنَّا أَكْثَرَ أَهْلِ الْمَدِينَةِ مُزْدَرَعًا، كُنَّا نُكْرِي الأَرْضَ بِالنَّاحِيَةِ مِنْهَا مُسَمًّى لِسَيِّدِ الأَرْضِ، قَالَ: فَمِمَّا يُصَابُ ذَلِكَ، وَتَسْلَمُ الأَرْضُ، وَمِمَّا يُصَابُ الأَرْضُ، وَيَسْلَمُ ذَلِكَ، فَنُهِينَا، وَأَمَّا الذَّهَبُ وَالْوَرِقُ فَلَمْ يَكُنْ يَوْمَئِذٍ."],"takhrij":"صحيح: رواه البخاري في الحرث والمزارعة (2327) عن محمد، أخبرنا عبد الله، أخبرنا يحيى بن سعيد، عن حنظلة بن قيس الأنصاري، سمع رافع بن خديج فذكره.","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2327).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Rafi ibn Khadij said: We were the people of Madinah with the most cultivated land. We used to lease land out with a certain portion of it specified for the owner of the land. Sometimes that specified portion would be damaged while the rest of the land remained safe, and sometimes the land would be damaged while that specified portion remained safe, so we were forbidden from that. As for renting land for gold and silver, that was not practiced then."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2327)، ومسلم (1547:117). وهذا لفظ مسلم. ولفظ البخاري: كنا أكثر أهل المدينة حقلا، وكان أحدنا يكري أرضه، فيقول: هذه القطعة لي، وهذه لك. فربما أخرجت هذه ولم تخرج هذه، فنهاهم النبي ﷺ."},{"num":5559,"demo":false,"sanad":"","matn":["عن رَافِعِ بن خَدِيجٍ يَقُولُ:  كُنَّا أَكْثَرَ الْأَنْصَارِ حَقْلًا، قَالَ: كُنَّا نُكْرِي الْأَرْضَ عَلَى أَنَّ لَنَا هَذِهِ وَلَهُمْ هَذِهِ، فَرُبَّمَا أَخْرَجَتْ هَذِهِ، وَلَمْ تُخْرِجْ هَذِهِ، فَنَهَانَا عَنْ ذَلِكَ، وَأَمَّا الْوَرِقُ فَلَمْ يَنْهَنَا."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2332)، ومسلم في البيوع (1547: 117) كلاهما من طريق سفيان بن عيينة، عن يحيى بن سعيد، عن حنظلة الزرقي أنه سمع رافع بن خديج يقول فذكره. وهذا لفظ مسلم.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2332) and Muslim (1547:117). This is the wording of Muslim. Al-Bukhari’s wording says: We were the people of Madinah with the most farmland, and one of us would lease his land saying: this plot is mine and that plot is yours. So sometimes this one would produce and the other would not, so the Prophet ﷺ forbade them from that.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Rafi ibn Khadij said: We were the Ansar with the most farmland. We used to lease out land on the basis that one section would be for us and another for them. Sometimes this section would produce while that one would not, so he forbade us from that. But as for silver money, he did not forbid us from it."]},"buhuth":{"en":["In another wording with him: Sometimes this one produced and the other did not, so we were forbidden from that, but we were not forbidden from silver currency.","His statement, “As for silver currency,” appears from all the narrations to be Rafi’s own legal understanding, because he understood that the reason for forbidding land rental was uncertainty, so when the uncertainty is removed, it becomes permissible."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2332)، ومسلم (1551). واللفظ للبخاري."},{"num":5560,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ قَالَ: عَامَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ بِشَطْرِ مَا يَخْرُجُ مِنْهَا مِنْ ثَمَرٍ أَوْ زَرْعٍ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2330)، ومسلم في المساقاة (1551) كلاهما من حديث يحيى (وهو القطان)، عن عبيدالله، أخبرني نافع، عن ابن عمر فذكره.واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2330) and Muslim (1551), both through Yahya al-Qattan, from Ubayd Allah, from Nafi, from Ibn Umar. The wording is al-Bukhari’s.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ made an agreement with the people of Khaybar for half of whatever came out of it of fruits or crops."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9045],"tks":"متفق عليه: رواه البخاري (2330)، ومسلم (1551:2). واللفظ لمسلم."},{"num":5561,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ:  أَعْطَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ بِشَطْرِ مَا يَخْرُجُ مِنْ ثَمَرٍ أَوْ زَرْعٍ، فَكَانَ يُعْطِي أَزْوَاجَهُ كُلَّ سَنَةٍ مِائَةَ وَسْقٍ: ثَمَانِينَ وَسْقًا مِنْ تَمْرٍ، وَعِشْرِينَ وَسْقًا مِنْ شَعِيرٍ. فَلَمَّا وَلِيَ عُمَرُ قَسَمَ خَيْبَرَ، خَيَّرَ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْطِعَ لَهُنَّ الْأَرْضَ وَالْمَاءَ، أَوْ يَضْمَنَ لَهُنَّ الْأَوْسَاقَ كُلَّ عَامٍ، فَاخْتَلَفْنَ، فَمِنْهُنَّ مَنِ اخْتَارَ الْأَرْضَ وَالْمَاءَ، وَمِنْهُنَّ مَنِ اخْتَارَ الْأَوْسَاقَ كُلَّ عَامٍ، فَكَانَتْ عَائِشَةُ وَحَفْصَةُ مِمَّنِ اخْتَارَتَا الْأَرْضَ وَالْمَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2328)، ومسلم في المساقاة (1551: 2) كلاهما من وجهين مختلفين عن عبيدالله، عن نافع، عن ابن عمر فذكره. واللفظ لمسلم، ولفظ البخاري نحوه، ولم يذكر حفصة.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2328) and Muslim (1551:2). The wording is Muslim’s.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ gave Khaybar on the basis of half of what came out of it in fruits or crops. He used to give his wives each year one hundred wasqs: eighty wasqs of dates and twenty wasqs of barley. Then when Umar took charge, he divided Khaybar and gave the wives of the Prophet ﷺ the choice between allotting to them land and water rights, or guaranteeing them fixed wasqs every year. They differed; some chose land and water, and some chose the yearly wasqs. Aishah and Hafsah were among those who chose land and water."]}},"tuhfa":{},"full":1,"rep":[9076],"tks":"متفق عليه: رواه البخاري (2328)، ومسلم (1551:6)."},{"num":5562,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا أَجْلَى الْيَهُودَ وَالنَّصَارَى مِنْ أَرْضِ الْحِجَازِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا ظَهَرَ عَلَى خَيْبَرَ أَرَادَ إِخْرَاجَ الْيَهُودِ مِنْهَا، وَكَانَتِ الأَرْضُ حِينَ ظَهَرَ عَلَيْهَا لِلَّهِ وَلِرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِلْمُسْلِمِينَ، وَأَرَادَ إِخْرَاجَ الْيَهُودِ، مِنْهَا، فَسَأَلَتِ الْيَهُودُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُقِرَّهُمْ بِهَا أَنْ يَكْفُوا عَمَلَهَا، وَلَهُمْ نِصْفُ الثَّمَرِ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نُقِرُّكُمْ بِهَا عَلَى ذَلِكَ مَا شِئْنَا. فَقَرُّوا بِهَا حَتَّى أَجْلاَهُمْ عُمَرُ إِلَى تَيْمَاءَ وَأَرِيحَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2338) ومسلم في المساقاة (1551: 6) كلاهما من حديث عبدالرزاق، أخبرنا ابن جريج، حدثني موسى بن عقبة، عن نافع، عن ابن عمر، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2338) and Muslim (1551:6).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn Umar narrated that Umar ibn al-Khattab expelled the Jews and Christians from the land of the Hijaz, and that when the Messenger of Allah ﷺ gained victory over Khaybar, he wanted to expel the Jews from it. The land, when he conquered it, belonged to Allah, His Messenger, and the Muslims. So he intended to expel the Jews from it, but the Jews asked the Messenger of Allah ﷺ to let them remain there on the condition that they would do its labor and have half the fruit. So the Messenger of Allah ﷺ said to them: “We will allow you to remain there on that basis as long as we wish.” So they remained there until Umar expelled them to Tayma and Ariha."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5524,9047],"tks":"متفق عليه: رواه مسلم (1551:4)."},{"num":5563,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قـال: لَمَّا افْتُتِحَتْ خَيْبَرُ سَأَلَتْ يَهُودُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقِرَّهُمْ فِيهَا عَلَى أَنْ يَعْمَلُوا عَلَى نِصْفِ مَا خَرَجَ مِنْهَا مِنْ الثمر والزرع، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُقِرُّكُمْ فِيهَا عَلَى ذَلِكَ مَا شِئْنَا. وَفِيهِ: وَكَانَ الثمر يُقْسَمُ عَلَى السُّهْمَانِ مِنْ نِصْفِ خَيْبَرَ، فَيَأْخُذُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخُمُسَ."],"takhrij":"صحيح: رواه مسلم في المساقاة (1551: 4) عن أبي الطاهر، حدثنا عبدالله بن وهب، أخبرني أسامة بن زيد، عن نافع، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1551:4).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abd Allah ibn Umar said: When Khaybar was conquered, the Jews asked the Messenger of Allah ﷺ to let them remain there on the condition that they would work it in return for half of whatever came out of it in fruits and crops. So the Messenger of Allah ﷺ said: “We will allow you to remain there on that basis as long as we wish.” And in it: The fruit used to be divided according to the allotted shares from half of Khaybar, and the Messenger of Allah ﷺ would take the one-fifth."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (3410)، وابن ماجه (1820)."},{"num":5564,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: افْتَتَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، وَاشْتَرَطَ أَنَّ لَهُ الأَرْضَ وَكُلَّ صَفْرَاءَ وَبَيْضَاءَ. قَالَ أَهْلُ خَيْبَرَ: نَحْنُ أَعْلَمُ بِالأَرْضِ مِنْكُمْ، فَأَعْطِنَاهَا عَلَى أَنَّ لَكُمْ نِصْفَ الثَّمَرَةِ، وَلَنَا نِصْفٌ. فَزَعَمَ أَنَّهُ أَعْطَاهُمْ عَلَى ذَلِكَ، فَلَمَّا كَانَ حِينَ يُصْرَمُ النَّخْلُ بَعَثَ إِلَيْهِمْ عَبْدَ اللَّهِ بْنَ رَوَاحَةَ، فَحَزَرَ عَلَيْهِمُ النَّخْلَ، وَهُوَ الَّذِي يُسَمِّيهِ أَهْلُ الْمَدِينَةِ الْخَرْصَ، فَقَالَ: فِي ذِهْ كَذَا وَكَذَا. قَالُوا: أَكْثَرْتَ عَلَيْنَا يَا ابْنَ رَوَاحَةَ. فَقَالَ: فَأَنَا أَلِي حَزْرَ النَّخْلِ، وَأُعْطِيكُمْ نِصْفَ الَّذِي قُلْتُ. قَالُوا: هَذَا الْحَقُّ، وَبِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، قَدْ رَضِينَا أَنْ نَأْخُذَهُ بِالَّذِي قُلْتَ."],"takhrij":"حسن: رواه أبو داود (3410)، وابن ماجه (1820) كلاهما من حديث عمر بن أيوب، عن جعفر بن برقان، عن ميمون بن مهران، عن مقسم، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3410) and Ibn Majah (1820).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ conquered Khaybar and stipulated that the land and all its gold and silver would belong to him. The people of Khaybar said: We know the land better than you do, so give it to us on the basis that you will have half the fruit and we will have half. He claimed that he gave it to them on that basis. Then when the time came for estimating the date harvest, he sent Abd Allah ibn Rawahah to them, and he estimated the palms for them — what the people of Madinah call khars. He said: This much and this much is in it. They said: You have estimated too much against us, O Ibn Rawahah. So he said: Then I will do the estimate and give you half of what I have said. They said: This is justice, and by this the heavens and the earth stand. We are satisfied to take it according to what you said."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري (2330)، ومسلم (121 :1550). واللفظ لمسلم."},{"num":5565,"demo":false,"sanad":"","matn":["عَنْ طَاوُسٍ، أَنَّهُ كَانَ يُخَابِرُ. قَالَ عَمْرٌو فَقُلْتُ لَهُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، لَوْ تَرَكْتَ هَذِهِ الْمُخَابَرَةَ؛ فَإِنَّهُمْ يَزْعُمُونَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الْمُخَابَرَةِ. فَقَالَ: أَىْ عَمْرُو، أَخْبَرَنِي أَعْلَمُهُمْ بِذَلِكَ يَعْنِي ابْنَ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  لَمْ يَنْهَ عَنْهَا، إِنَّمَا قَالَ: يَمْنَحُ أَحَدُكُمْ أَخَاهُ خَيْرٌ لَهُ مِنْ أَنْ يَأْخُذَ عَلَيْهَا خَرْجًا مَعْلُومًا."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2330)، ومسلم في البيوع (1550: 121) كلاهما من طريق سفيان، عن عمرو-وزاد مسلم: وابن طاوس-، عن طاوس به. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2330) and Muslim (1550:121). The wording is Muslim’s.","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Tawus used to engage in crop-sharing. Amr — meaning Ibn Dinar — said: I said to him, “O Abu Abd al-Rahman, if only you would leave this crop-sharing, for they claim that the Prophet ﷺ forbade crop-sharing.” He said: “O Amr, the one most knowledgeable among them about that — meaning Ibn Abbas — informed me that the Prophet ﷺ did not forbid it. He only said: ‘For one of you to grant it to his brother is better for him than taking a fixed payment for it.’”"]},"buhuth":{"en":["In a narration in al-Bukhari (2634), from Amr ibn Dinar, the Prophet ﷺ went out to land with crops swaying, and said: “Whose is this?” They said: “So-and-so rented it.” He said: “If he had granted it to him, that would have been better for him than taking a fixed wage for it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه الترمذي (1385). قال الترمذي: “هذا حديث حسن صحيح”."},{"num":5566,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يُحَرِّمِ الْمُزَارَعَةَ، وَلَكِنْ أَمَرَ أَنْ يَرْفُقَ بَعْضُهُمْ بِبَعْضٍ."],"takhrij":"حسن: رواه الترمذي (1385) عن محمود بن غيلان، أخبرنا الفضل بن موسى الشيباني، عن شريك، عن شعبة، عن عمرو بن دينار، عن طاوس، عن ابن عباس فذكره. ورواه مسلم (1550: 000) عن الفضل بن موسى، عن شريك، عن شعبة، عن عمرو بن دينار، عن طاوس، عن ابن عباس، عن النبي صلى الله عليه وسلم نحو حديثهم، ولم يذكر لفظ الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1385). Al-Tirmidhi said: “This is a hasan sahih hadith.”","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ did not make sharecropping unlawful, but rather instructed people to treat one another with kindness and lenience."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مسلم (1550: 000)."},{"num":5567,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ السَّائِبِ، قَالَ: دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَعْقِلٍ، فَسَأَلْنَاهُ عَنِ الْمُزَارَعَةِ، فَقَالَ: زَعَمَ ثَابِتٌ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الْمُزَارَعَةِ، وَأَمَرَ بِالْمُؤَاجَرَةِ، وَقَالَ: لاَ بَأْسَ بِهَا."],"takhrij":"صحيح: رواه مسلم في البيوع (1549: 119) عن إسحاق بن منصور، أخبرنا يحيى بن حماد، أخبرنا أبو عوانة، عن سليمان الشيباني، عن عبد الله بن السائب قال فذكره. قوله: المؤاجرة أي الإجارة، وهي تمليك منفعة بعوض لمدة معلومة.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1549:119).","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn al-Saib said: We entered upon Abdullah ibn Maqil and asked him about sharecropping. He said: “Thabit claimed that the Messenger of Allah ﷺ forbade sharecropping and commanded leasing instead,” and he said: “There is no harm in it.”"]},"buhuth":{"en":["His statement, “al-mu’ajarah,” means leasing or hiring, which is granting a benefit in return for compensation for a known period."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3405)، والترمذي (1290)، والنسائي (3911)، قال الترمذي: “حسن صحيح”."},{"num":5568,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ زَرَعَ فِي أَرْضِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَلَيْسَ لَهُ مِنَ الزَّرْعِ شَىْءٌ، وَلَهُ نَفَقَتُهُ."],"takhrij":"حسن: رواه أبو داود (3403)، والترمذي (1366)، وابن ماجه (2466)، وأحمد (15821) كلهم من حديث شريك، عن أبي إسحاق، عن عطاء، عن رافع بن خديج قال:فذكره.","grade":"حسن","chapter_ar":"باب فيمن زرع في أرض قوم بغير إذنهم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3403), al-Tirmidhi (1366), who graded it hasan, Ibn Majah (2466), and Ahmad (15821).","chapter_en":"About one who plants in the land of others without their permission","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Rafi ibn Khadij said: The Messenger of Allah ﷺ said: “Whoever plants in the land of a people without their permission has no right to any of the crop, but he is entitled to his expenses.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3403)، والترمذي (1366) وحسنه، وابن ماجه (2466)، وأحمد (15821)."},{"num":5569,"demo":false,"sanad":"","matn":["عن أَبِي جعفر الخَطْمي قَالَ: بَعَثَنِي عَمِّي أَنَا وَغُلاَمًا، لَهُ إِلَى سَعِيدِ بْنِ الْمُسَيَّبِ. قَالَ: فَقُلْنَا لَهُ: شَىْءٌ بَلَغَنَا عَنْكَ فِي الْمُزَارَعَةِ. قَالَ: كَانَ ابْنُ عُمَرَ لاَ يَرَى بِهَا بَأْسًا حَتَّى بَلَغَهُ عَنْ رَافِعِ بْنِ خَدِيجٍ، حَدِيثٌ فَأَتَاهُ، فَأَخْبَرَهُ رَافِعٌ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى بَنِي حَارِثَةَ، فَرَأَى زَرْعًا فِي أَرْضِ ظُهَيْرٍ، فَقَالَ: مَا أَحْسَنَ زَرْعَ ظُهَيْرٍ. قَالُوا: لَيْسَ لِظُهَيْرٍ. قَالَ: أَلَيْسَ أَرْضُ ظُهَيْرٍ. قَالُوا: بَلَى، وَلَكِنَّهُ زَرْعُ فُلاَنٍ. قَالَ: فَخُذُوا زَرْعَكُمْ، وَرُدُّوا عَلَيْهِ النَّفَقَةَ.","قَالَ رَافِعٌ: فَأَخَذْنَا زَرْعَنَا، وَرَدَدْنَا إِلَيْهِ النَّفَقَةَ.","قَالَ سَعِيدٌ: أَفْقِرْ أَخَاكَ أَوْ أَكْرِهِ بِالدَّرَاهِمِ."],"takhrij":"صحيح: رواه أبو داود (3399)، والنسائي (3889)، والبيهقي (11745) من طريق أبي داود- كلهم من حديث يحيى بن سعيد، ثنا أبو جعفر الخطمي قال فذكره.","grade":"صحيح","chapter_ar":"باب فيمن زرع في أرض قوم بغير إذنهم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3399), al-Nasāʾī (3889), and al-Bayhaqī (6/136).","chapter_en":"About one who plants in the land of others without their permission","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Abū Jaʿfar al-Khaṭmī said: My uncle sent me and one of his servants to Saʿīd ibn al-Musayyib. We said to him: “Something has reached us from you regarding sharecropping.” He said: “Ibn ʿUmar saw nothing wrong with it until a report from Rāfiʿ ibn Khadīj reached him, so he went to him. Rāfiʿ informed him that the Messenger of Allah ﷺ came to Banū Ḥārithah and saw crops growing on the land of Ẓuhayr. He said: ‘How excellent are the crops of Ẓuhayr!’ They said: ‘They do not belong to Ẓuhayr.’ He asked: ‘Is it not the land of Ẓuhayr?’ They replied: ‘Yes, but so-and-so planted it.’ He said: ‘Take your crop and reimburse him for his expenses.’” Rāfiʿ said: “So we took our crop and reimbursed him for his expenses.”","Saʿīd said: “Lend the land to your brother for his use, or rent it out for dirhams.”"]},"buhuth":{"en":["The expression “lend it to your brother” means to allow him to use the land without charge. The original usage of ifqār referred to lending someone the back of a riding animal so that he could ride it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3399)، والنسائي (3889)، والبيهقي (11745)."},{"num":5570,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ، فَقَالَ الأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ، فَأَبَى عَلَيْهِ، فَاخْتَصَمَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ: اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاء إِلَى جَارِكَ. فَغَضِبَ الأَنْصَارِيُّ، فَقَالَ: أَنْ كَانَ ابْنَ عَمَّتِكَ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: اسْقِ يَا زُبَيْرُ، ثُمَّ احْبِسِ الْمَاءَ، حَتَّى يَرْجِعَ إِلَى الْجَدْرِ. فَقَالَ الزُّبَيْرُ: وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ ﴿فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ﴾ [سورة النساء: 65]}."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2359)، ومسلم في الفضائل (2357) كلاهما من طريق الليث، عن الزهري، عن عروة بن الزبير أن عبدالله بن الزبير حدثه فذكره.","grade":"متفق عليه","chapter_ar":"باب الترتيب في السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2359) and Muslim (2357).","chapter_en":"The order of irrigation","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn al-Zubayr narrated to him that a man from the Ansar disputed with al-Zubayr before the Prophet ﷺ concerning the irrigation channels of al-Harrah by which they watered the palm trees. The Ansari said: “Let the water pass through.” But al-Zubayr refused. They disputed before the Prophet ﷺ, so the Messenger of Allah ﷺ said to al-Zubayr: “Water your land, O Zubayr, then let the water pass to your neighbor.” The Ansari became angry and said: “Because he is your aunt’s son?” The face of the Messenger of Allah ﷺ changed color, then he said: “Water your land, O Zubayr, then hold back the water until it returns to the walls.” Al-Zubayr said: By Allah, I think this verse was revealed about that: “But no, by your Lord, they do not truly believe until they make you judge concerning what has arisen between them.” [al-Nisa: 65]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2359)، ومسلم (2357)."},{"num":5571,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاَثَةٌ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلاَ يَنْظُرُ إِلَيْهِمْ: رَجُلٌ حَلَفَ عَلَى سِلْعَةٍ لَقَدْ أَعْطَى بِهَا أَكْثَرَ مِمَّا أَعْطَى وَهْوَ كَاذِبٌ، وَرَجُلٌ حَلَفَ عَلَى يَمِينٍ كَاذِبَةٍ بَعْدَ الْعَصْرِ لِيَقْتَطِعَ بِهَا مَالَ رَجُلٍ مُسْلِمٍ، وَرَجُلٌ مَنَعَ فَضْلَ مَاءٍ، فَيَقُولُ اللَّهُ: الْيَوْمَ أَمْنَعُكَ فَضْلِي، كَمَا مَنَعْتَ فَضْلَ مَا لَمْ تَعْمَلْ يَدَاكَ."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2369)، ومسلم في الأيمان (108: 174) كلاهما من طريق سفيان، عن عمرو (هو ابن دينار)، عن أبي صالح السمان، عن أبي هريرة قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية منع فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2369) and Muslim (108:174).","chapter_en":"The dislike of withholding excess water","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “There are three whom Allah will neither speak to on the Day of Resurrection nor look at: a man who swears concerning merchandise that he was offered more for it than he actually was, while he is lying; a man who swears a false oath after ʿAṣr in order to wrongfully take the wealth of a Muslim; and a man who withholds surplus water. Allah will say: ‘Today I will withhold My bounty from you just as you withheld the surplus of something that your own hands did not produce.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2369)، ومسلم (108: 174)."},{"num":5572,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَرْحَمُ اللَّهُ أُمَّ إِسْمَاعِيلَ، لَوْ تَرَكَتْ زَمْزَمَ ـ أَوْ قَالَ: لَوْ لَمْ تَغْرِفْ مِنَ الْمَاءِ ـ لَكَانَتْ عَيْنًا مَعِينًا، وَأَقْبَلَ جُرْهُمُ، فَقَالُوا: أَتَأْذَنِينَ أَنْ نَنْزِلَ عِنْدَكِ. قَالَتْ: نَعَمْ، وَلاَ حَقَّ لَكُمْ فِي الْمَاءِ. قَالُوا: نَعَمْ."],"takhrij":"صحيح: رواه البخاري في المساقاة (2368) عن عبد الله بن محمد، أخبرنا عبدالرزاق، أخبرنا معمر، عن أيوب، وكثير بن كثير –يزيد أحدهما على الآخر-، عن سعيد بن جبير قال: قال ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية منع فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2368).","chapter_en":"The dislike of withholding excess water","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ said: “May Allah have mercy on the mother of Ismail. Had she left Zamzam — or he said: had she not scooped from the water — it would have become a flowing spring. Then Jurhum came and said: ‘Do you permit us to settle near you?’ She said: ‘Yes, but you have no right in the water.’ They said: ‘Yes.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2368)."},{"num":5573,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَعْمَرَ أَرْضًا لَيْسَتْ لأَحَدٍ فَهْوَ أَحَقُّ. قَالَ عُرْوَةُ: قَضَى بِهِ عُمَرُ رَضِيَ اللَّهُ عَنْهُ فِي خِلاَفَتِهِ."],"takhrij":"صحيح: رواه البخاري في الحرث والمزارعة (2335) عن يحيى بن بكير، حدثنا الليث، عن عبيدالله بن أبي جعفر، عن محمد بن عبد الرحمن، عن عروة، عن عائشة قالت:فذكرته.","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2335).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Aishah narrated from the Prophet ﷺ: “Whoever cultivates or revives land that belongs to no one has the greatest right to it.” Urwah said: Umar ruled by this during his caliphate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2335)."},{"num":5574,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَحْيَا أَرْضًا مَيِّتَةً فَهِيَ لَهُ."],"takhrij":"صحيح: رواه الترمذي (1379) عن محمد بن بشار، حدثنا عبدالوهاب، حدثنا أيوب، عن هشام بن عروة، عن وهب بن كيسان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1379). Al-Tirmidhi said: “Hasan Sahih.” Ibn Hibban also authenticated it (5205), and added at the end: “And whatever is eaten from it by roaming creatures is charity for him.” Al-awafi is the plural of afiyah and refers to any creature seeking provision, including birds and others.","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that the Prophet ﷺ said: “Whoever revives dead land, it belongs to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1379). قال الترمذي: “حسن صحيح”. وصححه ابن حبان (5205)، وزاد في آخره: (( وما أكلت العوافي منها فهو له صدقة )). والعوافي: جمع عافية، وهو يطلق على كل من يطلب الرزق من الطير وغير ذلك."},{"num":5575,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْأَرْضُ أَرْضُ اللَّهِ، وَالْعِبَادُ عِبَادُ اللَّهِ، مَنْ أَحْيَا مَوَاتًا فَهِيَ لَهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (18/ح 823)، وفي مسند الشاميين (288) عن أحمد بن عبدالوهاب بن نجدة الحوطي، حدثنا يحيى بن صالح الوحاظي، حدثنا سعيد بن عبدالعزيز، عن مكحول، عن فضالة بن عبيد قال: فذكره.","grade":"حسن","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (18/318) and in Musnad al-Shamiyyin (288).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Fadalah ibn Ubayd said: The Messenger of Allah ﷺ said: “The land is Allah’s land, and the servants are Allah’s servants. Whoever revives dead land, it belongs to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (18/ح 823)، وفي مسند الشاميين (288)."},{"num":5576,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَحْيَا أَرْضًا مَيْتَةً فَهِيَ لَهُ، وَلَيْسَ لِعِرْقٍ ظَالِمٍ حَقٌّ."],"takhrij":"حسن: رواه الطبراني في الأوسط – مجمع البحرين (2180) عن أحمد – يعني ابن القاسم، حدثنا محمد بن عبدالوهاب الحارثي، حدثنا مسلم بن خالد الزنجي، عن هشام بن عروة، عن أبيه، عن عبدالله بن عمرو قال: فذكره.","grade":"حسن","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma al-Bahrayn (2180).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abdullah ibn Amr said: The Messenger of Allah ﷺ said: “Whoever revives dead land, it belongs to him, and no unjust claimant has any right.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (2180)."},{"num":5577,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جندب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَحَاطَ حَائِطًا عَلَى أَرْضٍ فَهِيَ لَهُ."],"takhrij":"صحيح: رواه الإمام أحمد (20130)، وعنه أبو داود (3077)، وابن أبي شيبة (33138)، والطبراني في الكبير (6865)، والبيهقي (11818) كلهم من طريق قتادة، عن الحسن، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20130), Abu Dawud (3077), Ibn Abi Shaybah (7/76), and al-Tabarani in al-Kabir (6865).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Whoever encloses land with a wall, it belongs to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20130)، وأبو داود (3077)، وابن أبي شيبة (33138)، والطبراني في الكبير (6865)."},{"num":5578,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: أَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْطِعَ مِنَ الْبَحْرَيْنِ، فَقَالَتِ الأَنْصَارُ: حَتَّى تُقْطِعَ لإِخْوَانِنَا مِنَ الْمُهَاجِرِينَ مِثْلَ الَّذِي تُقْطِعُ لَنَا. قَالَ: سَتَرَوْنَ بَعْدِي أَثَرَةً فَاصْبِرُوا حَتَّى تَلْقَوْنِي."],"takhrij":"صحيح: رواه البخاري في المساقاة (2376) عن سليمان بن حرب، حدثنا حماد، عن يحيى بن سعيد قال: سمعت أنسا قال فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2376).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ intended to allot land from Bahrain. The Ansar said: “Not until you allot to our brothers from the Muhajirun the same as you allot to us.” He said: “You will see favoritism after me, so be patient until you meet me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2376)."},{"num":5579,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ ابْنَةِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: كُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ الزُّبَيْرِ الَّتِي أَقْطَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَأْسِي."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3115)، ومسلم في السلام (2182) كلاهما من حديث أبي أسامة، عن هشام، عن أبيه، عن أسماء بنت أبي بكر الصديق فذكرته في قصة طويلة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3115) and Muslim (2182).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Asma bint Abi Bakr said: I used to carry date-stones on my head from the land of al-Zubayr which the Messenger of Allah ﷺ had granted him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3115)، ومسلم (2182)."},{"num":5580,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ بْنِ وَائِلٍ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَقْطَعَهُ أَرْضًا، قَالَ: فَأَرْسَلَ مَعِي مُعَاوِيَةَ أَنْ أَعْطِهَا إِيَّاهُ - أَوْ قَالَ: أَعْلِمْهَا إِيَّاهُ - قَالَ: فَقَالَ لِي مُعَاوِيَةُ: أَرْدِفْنِي خَلْفَكَ، فَقُلْتُ: لَا تَكُونُ مِنْ أَرْدَافِ الْمُلُوكِ، قَالَ: فَقَالَ: أَعْطِنِي نَعْلَكَ، فَقُلْتُ: انْتَعِلْ ظِلَّ النَّاقَةِ، قَالَ: فَلَمَّا اسْتُخْلِفَ مُعَاوِيَةُ أَتَيْتُهُ، فَأَقْعَدَنِي مَعَهُ عَلَى السَّرِيرِ، فَذَكَّرَنِي الْحَدِيثَ، فَقَالَ سِمَاكٌ: فَقَالَ: وَدِدْتُ أَنِّي كُنْتُ حَمَلْتُهُ بَيْنَ يَدَيَّ."],"takhrij":"حسن: رواه أبو داود (3058)، والتـرمذي (1381)، والدارمي (2651) كلهم من حديث شعبة، عن سماك، عن علقمة بن وائل، عن أبيه فذكره مختصرا على قوله: \"أن النبي صلى الله عليه وسلم أقطعه أرضا بحضر موت\".","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3058), al-Tirmidhi (1381), and al-Darimi (2651).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Alqamah ibn Wail narrated from his father that the Messenger of Allah ﷺ granted him land. He said: Then he sent Muawiyah with me to hand it over to him — or he said: to show it to him. Muawiyah said to me: “Let me ride behind you.” I said: “That is not for the followers of kings.” He then said: “Then give me your sandals.” I said: “Walk in the shade of the she-camel.” Then when Muawiyah became caliph, I went to him, and he seated me with him on the couch, and reminded me of that incident. Simak said: He then said: “I wish I had carried him before me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3058)، والترمذي (1381)، والدارمي (2651)."},{"num":5581,"demo":false,"sanad":"","matn":["عَنْ أَبْيَضَ بْنِ حَمَّالٍ، أَنَّهُ وَفَدَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَقْطَعَهُ، فَأَقْطَعَهُ الْمِلْحَ، فَلَمَّا أَدْبَرَ، قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَتَدْرِي مَا أَقْطَعْتَهُ، إِنَّمَا أَقْطَعْتَهُ الْمَاءَ الْعِدَّ! قَالَ: فَرَجَعَ فِيهِ، قَالَ: سَأَلْتُهُ عَمَّا يُحْمَى مِنَ الأَرَاكِ، فَقَالَ: مَا لَمْ تَبْلُغْهُ أَخْفَافُ الإِبِلِ."],"takhrij":"حسن: رواه أبو داود (3064)، والترمذي (1380)، وابن حبان (4499)، والدارقطني (4/221) كلهم من طريق محمد بن يحيى بن قيس المأربي قال: حدثنا أبي، عن ثمامة بن شراحيل، عن سمي بن قيس، عن شُمير بن عبد المدان، عن أبيض بن حمال فذكره. واللفظ لابن حبان.","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3064), al-Tirmidhi (1380), Ibn Hibban (4499), and al-Daraqutni (4/221).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abyad ibn Hammal came as a delegate to the Messenger of Allah ﷺ and asked him for a land grant, so he granted him a salt deposit. When he turned away, a man said: “O Messenger of Allah ﷺ, do you know what you have granted him? You have only granted him a never-ending supply like flowing water.” So he took it back from him. He said: I asked him about what may be reserved from arak trees, and he said: “As long as the camels’ hooves do not reach it.”"]},"buhuth":{"en":["The phrase “al-ma al-idd” means water that is constant and does not run out, such as spring water or well water. Salt was compared to that because of its continuous supply and because it is obtained without ongoing effort."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3064)، والترمذي (1380)، وابن حبان (4499)، والدارقطني (4/221)."},{"num":5582,"demo":false,"sanad":"","matn":["عن أبيض بن حمال أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حِمَى الأَرَاكِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ حِمَى فِي الأَرَاكِ. فَقَالَ: أَرَاكَةً فِي حِظَارِي. فَقَالَ النَّبِيُّ عَلَيْهِ السَّلاَمُ لاَ حِمَى فِي الأَرَاكِ."],"takhrij":"حسن: رواه أبو داود (3066) عن محمد بن أحمد القرشي، حدثنا عبــــدالله بن الزبير، حدثنا فرج بن سعيد، حدثني عمي ثابت بن سعيد، عن أبيـــــه، عن جده، عن أبيض بن حمال فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3066).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abyad ibn Hammal asked the Messenger of Allah ﷺ about reserving arak trees, and the Messenger of Allah ﷺ said: “There is no exclusive reserve in arak.” He said: “An arak tree in my enclosure?” The Prophet ﷺ said: “There is no exclusive reserve in arak.”"]},"buhuth":{"en":["Al-Khattabi said: It appears that this arak tree was already standing there when the land was revived and enclosed, so he gained ownership of the land by reviving it, but not ownership of the arak tree because it was grazing land for passing animals. But if arak grows in a person’s owned land, then it is protected for its owner, and there is no restriction on his ownership or disposal of it, and it is no different from other trees people have in their lands."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3066)."},{"num":5583,"demo":false,"sanad":"","matn":["عن عبدالله بن عباس أنه قال: أعطى النبي صلى الله عليه وسلم بلال بن الحارث المزني المعادن القبلية جلسيها وغوريها، وحيث يصلح الزرع من قدس."],"takhrij":"حسن: رواه ابن زنجويه في كتاب الأموال (1265) عن حميد، حدثنا ابن أبي أويس، حدثني أبي، عن ثور بن يزيد الديلي، وعن خاله موسى بن ميسرة، عن عكرمة مولى عبد الله بن عباس، عن عبد الله بن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Zanjawayh in Kitab al-Amwal (1265). It was also narrated by Abu Dawud (3062), Ahmad (2786), and al-Bayhaqi (6/145).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Prophet ﷺ granted Bilal ibn al-Harith al-Muzani the Qabaliyyah mines, their highlands and lowlands, and the cultivable land of Quds."]},"buhuth":{"en":["The phrase “the Qabaliyyah mines from the area of al-Far” — al-Far, with a fathah on the fa, is near Suwayqah in the lands of Juhaynah.","“Jalsiyyiha” means its elevated highlands. Najd is also called jals. Al-Asmai said: Every elevated place is called jals.","“Al-ghawr” means the low-lying parts of the land. The meaning is that he granted him both its valleys and its raised parts.","“Quds,” with a dammah on the qaf and sukun on the dal, is a known mountain. It was also said that it means elevated land suitable for cultivation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن زنجويه في كتاب الأموال (1265). ورواه أبو داود (3062)، وأحمد (2786)، والبيهقي (11842)."},{"num":5584,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ أَقْطَعَ الدُّورَ، وَأَقْطَعَ ابْنَ مَسْعُودٍ فِيمَنْ أَقْطَعَ، فَقَالَ لَهُ أَصْحَابَهُ: يَا رَسُولَ اللَّهِ، نَكِّبْهُ عَنَّا. قَالَ: فَلِمَ بَعَثَنِي اللَّهُ إِذًا؟ إِنَّ اللَّهَ لَا يُقَدِّسُ أُمَّةً لَا يُعْطُونَ الضَّعِيفَ مِنْهُمْ حَقَّهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (10534) عن أبي خليفة الفضل بن الحباب، ثنا عبد الرحمن بن سلام الجمحي، ثنا سفيان بن عيينة، عن عمرو بن دينار، عن يحيى بن جعدة، عن هبيرة بن يريم، عن ابن مسعود فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (10/274).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Ibn Masud said: When the Prophet ﷺ came to Madinah, he allotted residential plots, and Ibn Masud was among those to whom he gave land. His companions said to him: “O Messenger of Allah ﷺ, move him away from us.” He said: “Then why did Allah send me? Allah does not purify a people who do not give the weak among them their due right.”"]},"buhuth":{"en":["His statement, “move him away from us,” means: keep him apart from us. In Arabic, nakkaba means to turn away from a path, or to move someone else aside."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (10534)."},{"num":5585,"demo":false,"sanad":"","matn":["عن سَبْرة بن عَبْدِ الْعَزِيزِ بن الرَّبِيعِ الجهني، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ فِي مَوْضِعِ الْمَسْجِدِ تَحْتَ دَوْمَةٍ، فَأَقَامَ ثَلاَثًا، ثُمَّ خَرَجَ إِلَى تَبُوكَ، وَإِنَّ جُهَيْنَةَ لَحِقُوهُ بِالرَّحْبَةِ، فَقَالَ لَهُمْ: مَنْ أَهْلُ ذِي الْمَرْوَةِ. فَقَالُوا: بَنُو رِفَاعَةَ مِنْ جُهَيْنَةَ. فَقَالَ: قَدْ أَقْطَعْتُهَا لِبَنِي رِفَاعَةَ. فَاقْتَسَمُوهَا، فَمِنْهُمْ مَنْ بَاعَ، وَمِنْهُمْ مَنْ أَمْسَكَ فَعَمِلَ، ثُمَّ سَأَلْتُ أَبَاهُ عَبْدَ الْعَزِيزِ عَنْ هَذَا الْحَدِيثِ، فَحَدَّثَنِي بِبَعْضِهِ، وَلَمْ يُحَدِّثْنِي بِهِ كُلِّهِ."],"takhrij":"حسن: رواه أبو داود (3068) عن سليمان بن داود المهري، أخبرنا ابن وهب، حدثني سبرة بن عبد العزيز بن الربيع الجهني فذكره.","grade":"حسن","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3068).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Sabrah ibn Abd al-Aziz ibn al-Rabi al-Juhani narrated from his father, from his grandfather, that the Prophet ﷺ stopped at the place of the mosque beneath Dumah, stayed there three days, then departed for Tabuk. Juhaynah later caught up with him at al-Rahbah, and he said to them: “Who are the people of Dhu al-Marwah?” They said: “Banu Rifaah from Juhaynah.” He said: “I have granted it to Banu Rifaah.” So they divided it among themselves. Some of them sold their shares, while others kept them and cultivated them. Later, I asked his father Abd al-Aziz about this report, and he told me part of it, but not all of it."]},"buhuth":{"en":["The word “al-Rahbah” means a wide open land.","“Dhu al-Marwah” is a village in Wadi al-Qura, between Madinah and Syria."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3068). وقوله: (( الرحبة )) بفتح الراء وسكون الحاء، الأرض الواسعة."},{"num":5586,"demo":false,"sanad":"","matn":["عَنِ الصَّعْبِ بْنِ جَثَّامَةَ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: مَرَّ بِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالأَبْوَاءِ ـ أَوْ بِوَدَّانَ ـ وَسُئِلَ عَنْ أَهْلِ الدَّارِ يُبَيَّتُونَ مِنَ الْمُشْرِكِينَ، فَيُصَابُ مِنْ نِسَائِهِمْ وَذَرَارِيِّهِمْ، قَالَ: هُمْ مِنْهُمْ. وَسَمِعْتُهُ يَقُولُ: لاَ حِمَى إِلاَّ لِلَّهِ وَلِرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3012) ومسلم في الجهاد (1745) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن عبيد الله، عن ابن عباس، عن الصعب بن جثامة، فذكره. واللفظ للبخاري، ولفظ مسلم مثله إلا أنه لم يذكر قوله: وسمعته يقول: لا حمى إلا لله ولرسوله.","grade":"متفق عليه","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3012) and Muslim (1745). The wording is al-Bukhari’s.","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Al-Sab ibn Jaththamah said: The Prophet ﷺ passed by me at al-Abwa or Waddan, and he was asked about the polytheists who are attacked by night and whose women and children may also be harmed. He said: “They are from them.” And I heard him say: “There is no protected reserve except for Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"rep":[7907],"tks":"متفق عليه: رواه البخاري (3012)، ومسلم (1745). واللفظ للبخاري."},{"num":5587,"demo":false,"sanad":"","matn":["عن الصَّعْبِ بْنِ جَثَّامَةَ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ حِمَى إِلاَّ لِلَّهِ وَلِرَسُولِهِ."],"takhrij":"صحيح: رواه البخاري في المساقاة (2370) عن يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، عن عبيد الله بن عبد الله بن عتبة، عن ابن عباس أن الصعب بن جثامة قال فذكر الحديث.","grade":"صحيح","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2370).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Al-Sab ibn Jaththamah said: The Messenger of Allah ﷺ said: “There is no protected reserve except for Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2370)."},{"num":5588,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا حِمَى إِلَاّ للهِ وَلِرَسُولِهِ."],"takhrij":"صحيح: رواه ابن حبان (4685) عن أحمد بن الحسن بن عبد الجبار، حدثنا يحيى بن معين، حدثنا علي بن عياش، حدثنا شعيب بن أبي حمزة، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4685).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “There is no protected reserve except for Allah and His Messenger.”"]},"buhuth":{"en":["The statement “There is no protected reserve except for Allah and His Messenger” means that no one may reserve land for himself the way people in the pre-Islamic period used to do, when a powerful man or tribal chief would set aside whatever he wished for himself and keep others away from it.","The exception “except for Allah and His Messenger” means that Allah and His Messenger, and after the Messenger those who take his place such as caliphs, kings, and regional governors by lawful authority, may reserve land for the Muslims according to the public interest."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (4685)."},{"num":5589,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَمْسَكَ كَلْبًا فَإِنَّهُ يَنْقُصُ كُلَّ يَوْمٍ مِنْ عَمَلِهِ قِيرَاطٌ، إِلاَّ كَلْبَ حَرْثٍ أَوْ مَاشِيَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الحرث والمزارعة (2322)، ومسلم في المساقاة (1575: 59) كلاهما من طريق هشام الدستوائي، حدثنا يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكره. ورواه مسلم (58) من طريق الزهري، عن أبي سلمة به بلفظ: من اتخذ كلبا إلا كلب ماشية أو صيد أو زرع انتقص من أجره كل يوم قيراط. قال الزهري: فذكر لابن عمر قـول أبي هريرة، فقال: \"يرحم الله أبا هريرة، كان صاحب زرع\".","grade":"متفق عليه","chapter_ar":"باب جواز اقتناء الكلب للحرث والزرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2322) and Muslim (1575/59).","chapter_en":"The permissibility of keeping a dog for plowing and crops","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog will have one qīrāṭ deducted from his deeds every day, except a dog kept for farming or livestock.”"]},"buhuth":{"en":["Muslim also narrated through another route:","“Whoever keeps a dog, except a dog for livestock, hunting, or crops, will have one qīrāṭ deducted from his reward every day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2322)، ومسلم (1575: 59)."},{"num":5590,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ عَنْ كَعْبٍ، أَنَّهُ تَقَاضَى ابْنَ أَبِي حَدْرَدٍ دَيْنًا كَانَ لَهُ عَلَيْهِ فِي الْمَسْجِدِ، فَارْتَفَعَتْ أَصْوَاتُهُمَا، حَتَّى سَمِعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي بَيْتِهِ، فَخَرَجَ إِلَيْهِمَا حَتَّى كَشَفَ سِجْفَ حُجْرَتِهِ، فَنَادَى: يَا كَعْبُ. قَالَ: لَبَّيْكَ يَا رَسُولَ اللَّهِ. قَالَ: ضَعْ مِنْ دَيْنِكَ هَذَا. وَأَوْمَأَ إِلَيْهِ أَىِ الشَّطْرَ. قَالَ: لَقَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ. قَالَ: قُمْ فَاقْضِهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (457)، ومسلم في المساقاة (1558) كلاهما من حديث عثمان بن عمر قال: أخبرنا يونس، عن الزهري، عن عبد الله بن كعب، عن كعب بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (457) and Muslim (1558).","chapter_en":"What has been reported regarding reconciliation and settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Kab ibn Malik was demanding a debt owed to him by Ibn Abi Hadrad in the mosque, and their voices rose until the Messenger of Allah ﷺ heard them while he was in his house. He came out to them and lifted the curtain of his room, then called: “O Kab.” He said: “At your service, O Messenger of Allah ﷺ.” He said: “Reduce some of your debt,” indicating half of it. Kab said: “I have done so, O Messenger of Allah ﷺ.” He then said: “Get up and pay him.”"]}},"tuhfa":{},"full":1,"rep":[3107,5633],"tks":"متفق عليه: رواه البخاري (457)، ومسلم (1558)."},{"num":5591,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الصُّلْحُ جَائِزٌ بَيْنَ الْمُسْلِمِينَ."],"takhrij":"حسن: رواه أبو داود (3594) من وجهين:","grade":"حسن","chapter_ar":"باب ما جاء في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3594).","chapter_en":"What has been reported regarding reconciliation and settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Settlement is permissible among Muslims.”"]},"buhuth":{"en":["Abu Dawud said: Ahmad ibn Abd al-Wahhab added: “Except a settlement that makes the unlawful lawful or makes the lawful unlawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3594)."},{"num":5592,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اشْتَرَى رَجُلٌ مِنْ رَجُلٍ عَقَارًا لَهُ، فَوَجَدَ الرَّجُلُ الَّذِي اشْتَرَى الْعَقَارَ فِي عَقَارِهِ جَرَّةً فِيهَا ذَهَبٌ، فَقَالَ لَهُ الَّذِي اشْتَرَى الْعَقَارَ: خُذْ ذَهَبَكَ مِنِّي، إِنَّمَا اشْتَرَيْتُ مِنْكَ الأَرْضَ، وَلَمْ أَبْتَعْ مِنْكَ الذَّهَبَ. وَقَالَ الَّذِي لَهُ الأَرْضُ: إِنَّمَا بِعْتُكَ الأَرْضَ وَمَا فِيهَا، فَتَحَاكَمَا إِلَى رَجُلٍ، فَقَالَ الَّذِي تَحَاكَمَا إِلَيْهِ: أَلَكُمَا وَلَدٌ؟ قَالَ أَحَدُهُمَا: لِي غُلاَمٌ. وَقَالَ الآخَرُ: لِي جَارِيَةٌ. قَالَ: أَنْكِحُوا الْغُلاَمَ الْجَارِيَةَ، وَأَنْفِقُوا عَلَى أَنْفُسِهِمَا مِنْهُ، وَتَصَدَّقَا."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3472)، ومسلم في الأقضية (1721) كلاهما من حديث عبدالرزاق، عن معمر، عن همام، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب استعمال الحكمة في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3472) and Muslim (1721).","chapter_en":"Using wisdom in settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A man bought a piece of land from another man, then the buyer found in that land a jar containing gold. The buyer said to the seller: ‘Take your gold from me. I only bought the land from you, I did not buy the gold.’ The seller said: ‘I sold you the land and whatever was in it.’ So they brought their case to a man for judgment. He asked them: ‘Do either of you have children?’ One of them said: ‘I have a boy.’ The other said: ‘I have a girl.’ He said: ‘Marry the boy to the girl, spend from it on yourselves, and give charity.’”"]}},"tuhfa":{},"full":1,"rep":[8280],"tks":"متفق عليه: رواه البخاري (3472)، ومسلم (1721)."},{"num":5593,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ، فَقَالَ الأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ، فَأَبَى عَلَيْهِ، فَاخْتَصَمَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاء إِلَى جَارِكَ. فَغَضِبَ الأَنْصَارِيُّ، فَقَالَ: أَنْ كَانَ ابْنَ عَمَّتِكَ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، ثُمَّ قَالَ: اسْقِ يَا زُبَيْرُ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ. فَقَالَ الزُّبَيْرُ: وَاللَّهِ إِنِّي لأَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ﴾ [سورة النِّسَاءِ: 65]."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (2359، 2360)، ومسلم في الفضائل (2357) كلاهما من طريق الليث (ابن سعد)، عن ابن شهاب، عن عروة بن الزبير، أن عبدالله بن الزبير حدثه فذكره.","grade":"متفق عليه","chapter_ar":"باب الصلح في ماء السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2359, 2360) and Muslim (2357).","chapter_en":"Settlement regarding irrigation water","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn al-Zubayr narrated that a man from the Ansar disputed with al-Zubayr before the Messenger of Allah ﷺ over the irrigation channels of al-Harrah from which they watered the palm trees. The Ansari said: “Let the water pass through.” But al-Zubayr refused. So they brought their dispute to the Prophet ﷺ, and the Messenger of Allah ﷺ said: “Water your land, O Zubayr, then let the water pass to your neighbor.” The Ansari became angry and said: “Because he is your aunt’s son?” The face of the Messenger of Allah ﷺ changed color, then he said: “Water your land, O Zubayr, then hold back the water until it returns to the boundary wall.” Al-Zubayr said: By Allah, I believe this verse was revealed concerning that: “But no, by your Lord, they do not truly believe until they make you judge concerning what has arisen between them.” [al-Nisa: 65]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2360 ،2359)، ومسلم (2357)."},{"num":5594,"demo":false,"sanad":"","matn":["عَنْ الزُّبَيْرِ أَنَّهُ خَاصَمَ رَجُلاً مِنَ الأَنْصَارِ قَدْ شَهِدَ بَدْرًا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شِرَاجٍ مِنَ الْحَرَّةِ، كَانَا يَسْقِيَانِ بِهِ كِلاَهُمَا، فقــال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ: اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلْ إِلَى جَارِكَ. فَغَضِبَ الأَنْصَارِيُّ، فَقَالَ: يَا رَسُولَ اللَّهِ، آنْ كَانَ ابْنَ عَمَّتِكَ. فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، ثُمَّ قَالَ: اسْقِ، ثُمَّ احْبِسْ حَتَّى يَبْلُغَ الْجَدْرَ. فَاسْتَوْعَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَئِذٍ حَقَّهُ لِلزُّبَيْرِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ ذَلِكَ أَشَارَ عَلَى الزُّبَيْرِ برأي سَعَةٍ لَهُ وَلِلأَنْصَارِيِّ، فَلَمَّا أَحْفَظَ الأَنْصَارِيُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَوْعَى لِلزُّبَيْرِ حَقَّهُ فِي صَرِيحِ الْحُكْمِ. قَالَ عُرْوَةُ: قَالَ الزُّبَيْرُ: وَاللَّهِ مَا أَحْسِبُ هَذِهِ الآيَةَ نَزَلَتْ إِلاَّ فِي ذَلِكَ: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ﴾ [سورة النساء: 65]."],"takhrij":"صحيح: البخاري في الصلح (2708) عن أبي اليمان، أخبرنا شعيب، عن الزهري، أخبرني عروة بن الزبير عن الزبير فذكره.","grade":"صحيح","chapter_ar":"باب الصلح في ماء السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2708).","chapter_en":"Settlement regarding irrigation water","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Al-Zubayr reported: He disputed with a man from the Anṣār who had participated in Badr, and they brought their dispute before the Messenger of Allah ﷺ concerning an irrigation channel in al-Ḥarrah from which both of them watered their land. The Messenger of Allah ﷺ said to al-Zubayr: “Water your land, O Zubayr, then let the water pass on to your neighbor.” The Anṣārī became angry and said: “O Messenger of Allah ﷺ, is it because he is your aunt’s son?” The face of the Messenger of Allah ﷺ changed color. Then he said: “Water your land, then hold back the water until it reaches the boundary wall.” At that point, the Messenger of Allah ﷺ granted al-Zubayr his full legal right. Before that, he had advised al-Zubayr to follow a lenient arrangement that would accommodate both him and the Anṣārī. But when the Anṣārī angered the Messenger of Allah ﷺ, he granted al-Zubayr his full right according to the explicit judgment. ʿUrwah said that al-Zubayr said: “By Allah, I think this verse was revealed concerning this incident: ‘But no, by your Lord, they will not truly believe until they make you judge concerning what has arisen between them.’”"]},"buhuth":{"en":["The expression “when he angered him” means when he provoked the Messenger of Allah ﷺ to anger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2708)."},{"num":5595,"demo":false,"sanad":"","matn":["أَنَّ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو فِي الصَّلاَةِ، وَيَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ. فَقَالَ لَهُ قَائِلٌ: مَا أَكْثَرَ مَا تَسْتَعِيذُ يَا رَسُولَ اللَّهِ مِنَ الْمَغْرَمِ! قَالَ: إِنَّ الرَّجُلَ إِذَا غَرِمَ حَدَّثَ فَكَذَبَ، وَوَعَدَ فَأَخْلَفَ."],"takhrij":"متفق عليه: رواه البخاري في الاستقراض (2397)، ومسلم في المساجـد (589) كلاهما من طريق الزهري، عن عروة، عن عائشة فذكرته. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الاستعاذة من الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2397) and Muslim (589). The wording is al-Bukhari’s.","chapter_en":"Seeking refuge from debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Aishah narrated that the Messenger of Allah ﷺ used to supplicate in prayer and say: “O Allah, I seek refuge in You from sin and debt.” Someone said to him: “How often you seek refuge, O Messenger of Allah ﷺ, from debt.” He said: “When a man falls into debt, he speaks and lies, and he promises and breaks his promise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2397)، ومسلم (589). واللفظ للبخاري."},{"num":5596,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ حَالَتْ شَفَاعَتُهُ دُونَ حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ، فَقَدْ ضَادَّ اللهَ أَمْرَهُ، وَمَنْ مَاتَ وَعَلَيْهِ دَيْنٌ، فَلَيْسَ بِالدِّينَارِ وَلَا بِالدِّرْهَمِ، وَلَكِنَّهَا الْحَسَنَاتُ وَالسَّيِّئَاتُ، وَمَنْ خَاصَمَ فِي بَاطِلٍ وَهُوَ يَعْلَمُهُ، لَمْ يَزَلْ فِي سَخَطِ اللَّهِ حَتَّى يَنْزِعَ، وَمَنْ قَالَ: فِي مُؤْمِنٍ مَا لَيْسَ فِيهِ أَسْكَنَهُ اللهُ رَدْغَةَ الْخَبَالِ حَتَّى يَخْرُجَ مِمَّا قَالَ."],"takhrij":"صحيح: رواه الإمام أحمد (5385) عن حسن بن موسى قال: حدثنا زهير بن معاوية، حدثنا عمارة بن غزية، عن يحيى بن راشد قال: خرجنا حجاجا عشرة من أهل الشام، حتى أتينا مكة، فذكر الحديث، قال: فأتيناه، فخرج إلينا -يعني ابن عمر-، فقال فذكر الحديث.","grade":"صحيح","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (5385), authenticated by al-Hakim (2/27), and by al-Bayhaqi (6/82).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ say: “Whoever intercedes to prevent one of the prescribed punishments of Allah has opposed Allah in His command. Whoever dies while owing a debt, then repayment there will not be in gold coins or silver coins, but rather in good deeds and bad deeds. Whoever argues for falsehood while knowing it remains under the anger of Allah until he stops. And whoever says about a believer what is not true, Allah will make him dwell in the foul mire until he comes out of what he said.”"]},"buhuth":{"en":["The phrase “Allah will make him dwell in the foul mire” means thick mud and filth.","The word refers originally to corruption and ruin, whether in actions, bodies, or minds. It has also been explained in hadith as the discharge of the people of Hell."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5385)، وصححه الحاكم (2222)، والبيهقي (17617)."},{"num":5597,"demo":false,"sanad":"","matn":["عَنِ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَفْسُ الْمُؤْمِنِ مُعَلَّقَةٌ مَا كَانَ عَلَيْهِ دَيْنٌ."],"takhrij":"حسن: رواه أحمد (9679، 10156)، والدارمي (2633)، والبيهقي (11412) كلهم من طريق سفيان الثوري، عن سعد بن إبراهيم، عن عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (10156, 9679), al-Darimi (2633), and al-Bayhaqi (6/76).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “The soul of the believer remains suspended as long as a debt remains upon him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (10156 ،9679)، والدارمي (2633)، والبيهقي (11412)."},{"num":5598,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ فَارَقَ الرُّوحُ والجسد وَهُوَ بَرِيءٌ مِنْ ثَلاَثٍ: الكنـز وَالْغُلُولِ وَالدَّيْنِ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه الترمذي (1572)، وابن ماجه (2412)، وأحمد (22427)، وابن حبان (198)، والحاكم (2217)، والبيهقي (10964)، والدارمي (2634) كلهم من حديث سعيد بن أبي عروبة، عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة، عن ثوبان مولى رسول الله صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1572), Ibn Majah (2412), Ahmad (22427), and Ibn Hibban (198).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ said: “Whoever departs from this world free of three things — hoarded wealth, betrayal of public trust, and debt — enters Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1572)، وابن ماجه (2412)، وأحمد (22427)، وابن حبان (198)."},{"num":5599,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ مَاتَ وَعَلَيْهِ دِينَارٌ أَوْ دِرْهَمٌ قُضِيَ مِنْ حَسَنَاتِهِ لَيْسَ ثَمَّ دِينَارٌ وَلاَ دِرْهَمٌ."],"takhrij":"حسن: رواه ابن ماجه (2414) عن محمد بن ثعلبة بن سواء، قال: حدثنا عمي محمد بن سواء، عن حسين المعلم، عن مطر الوراق، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2414).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “Whoever dies owing a dinar or a dirham, it will be taken from his good deeds, for there will be no dinar or dirham there.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2414)."}]);